import socket
import time
import threading
import logging
import signal
import sys
import random

try:
    from gpiozero import DigitalOutputDevice, PWMOutputDevice
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    DigitalOutputDevice = None
    PWMOutputDevice = None
    GPIOZeroError = Exception
    DeviceClosed = Exception

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

MOTOR_A_FORWARD_PIN = 27
MOTOR_A_BACKWARD_PIN = 22
MOTOR_B_CLOCKWISE_PIN = 24
MOTOR_B_COUNTERCLOCKWISE_PIN = 25
MOTOR_A_ENABLE_PIN = 17
MOTOR_B_ENABLE_PIN = 23
SPI_CLK = 11
SPI_MOSI = 10
SPI_MISO = 9
SPI_CS_1 = 8
SPI_CS_2 = 7
MCP3008_CHANNEL_1 = 0
MCP3008_CHANNEL_2 = 1

WATERING_DURATION = 5
THRESHOLD_1 = 40
THRESHOLD_2 = 30

MOTOR_A_FORWARD = 1
MOTOR_A_BACKWARD = 0
MOTOR_A_STOP = 0
MOTOR_B_CLOCKWISE = 1
MOTOR_B_COUNTERCLOCKWISE = 0
MOTOR_B_STOP = 0

MOTOR_A_ENABLE_FREQUENCY = 1000
MOTOR_B_ENABLE_FREQUENCY = 1000

MOTOR_A_FORWARD_DUTY_CYCLE = 50
MOTOR_A_BACKWARD_DUTY_CYCLE = 50
MOTOR_B_CLOCKWISE_DUTY_CYCLE = 50
MOTOR_B_COUNTERCLOCKWISE_DUTY_CYCLE = 50

MOTOR_A_ENABLE = PWMOutputDevice(MOTOR_A_ENABLE_PIN, frequency=MOTOR_A_ENABLE_FREQUENCY)
MOTOR_B_ENABLE = PWMOutputDevice(MOTOR_B_ENABLE_PIN, frequency=MOTOR_B_ENABLE_FREQUENCY)

motor_a_forward_pin = DigitalOutputDevice(MOTOR_A_FORWARD_PIN)
motor_a_backward_pin = DigitalOutputDevice(MOTOR_A_BACKWARD_PIN)
motor_b_clockwise_pin = DigitalOutputDevice(MOTOR_B_CLOCKWISE_PIN)
motor_b_counterclockwise_pin = DigitalOutputDevice(MOTOR_B_COUNTERCLOCKWISE_PIN)

spi_clk = DigitalOutputDevice(SPI_CLK)
spi_mosi = DigitalOutputDevice(SPI_MOSI)
spi_miso = DigitalOutputDevice(SPI_MISO)
spi_cs_1 = DigitalOutputDevice(SPI_CS_1)
spi_cs_2 = DigitalOutputDevice(SPI_CS_2)

mcp3008_1 = None
mcp3008_2 = None

running = True

def read_mcp3008(spi, channel):
    if not 0 <= channel <= 7:
        raise ValueError("Channel must be between 0 and 7")
    if spi is None:
        raise RuntimeError("MCP3008 not initialized")
    try:
        spi.set_mode(0)
        spi.set_bit_order(0)
        spi.set_cs(spi_cs_1, False)
        for _ in range(5):
            spi.set_mosi(0)
            time.sleep(0.000001)
            result = spi.read_bytes(2)
            if result is None:
                raise RuntimeError("SPI read failed")
            adc_out = ((result[0] & 0x03) << 8) | result[1]
            spi.set_cs(spi_cs_1, True)
            time.sleep(0.02)
        adc_out = (adc_out >> 3) & 0xFF
        spi.set_cs(spi_cs_1, False)
        return adc_out
    except Exception as e:
        logging.error(f"Error reading MCP3008 channel {channel}: {e}")
        return -1

def get_sensor_data():
    if mcp3008_1 is None:
        return -1, -1
    try:
        val1 = read_mcp3008(mcp3008_1, MCP3008_CHANNEL_1)
        val2 = read_mcp3008(mcp3008_2, MCP3008_CHANNEL_2)
        return val1, val2
    except Exception as e:
        logging.error(f"Error getting sensor data: {e}")
        return -1, -1

def water_plant(plant_number, duration):
    global running
    if plant_number == 1:
        motor_a_forward_pin.on()
        motor_a_backward_pin.off()
        motor_b_clockwise_pin.off()
        motor_b_counterclockwise_pin.on()
        MOTOR_A_ENABLE.value = MOTOR_A_FORWARD_DUTY_CYCLE / 100.0
        MOTOR_B_ENABLE.value = MOTOR_B_CLOCKWISE_DUTY_CYCLE / 100.0
    elif plant_number == 2:
        motor_a_forward_pin.off()
        motor_a_backward_pin.on()
        motor_b_clockwise_pin.on()
        motor_b_counterclockwise_pin.off()
        MOTOR_A_ENABLE.value = MOTOR_A_BACKWARD_DUTY_CYCLE / 100.0
        MOTOR_B_ENABLE.value = MOTOR_B_CLOCKWISE_DUTY_CYCLE / 100.0
    else:
        logging.error("Invalid plant number")
        return
    start_time = time.time()
    while running and (time.time() - start_time) < duration:
        time.sleep(0.1)
    stop_motor(plant_number)

def stop_motor(plant_number):
    if plant_number == 1:
        motor_a_forward_pin.off()
        motor_a_backward_pin.off()
        motor_b_clockwise_pin.off()
        motor_b_counterclockwise_pin.off()
    elif plant_number == 2:
        motor_a_forward_pin.off()
        motor_a_backward_pin.off()
        motor_b_clockwise_pin.off()
        motor_b_counterclockwise_pin.off()
    MOTOR_A_ENABLE.value = 0
    MOTOR_B_ENABLE.value = 0

def set_threshold(threshold):
    global THRESHOLD_1, THRESHOLD_2
    if threshold <= 0:
        logging.error("Threshold must be positive")
        return
    if threshold < 10:
        THRESHOLD_1 = THRESHOLD_2 = threshold
    elif threshold < 20:
        THRESHOLD_1 = threshold
        THRESHOLD_2 = 10
    else:
        THRESHOLD_1 = 20
        THRESHOLD_2 = 10
    logging.info(f"Thresholds set to {THRESHOLD_1}, {THRESHOLD_2}")

def handle_client(conn, addr):
    global running
    try:
        logging.info(f"Connected by {addr}")
        while running:
            data = conn.recv(1024)
            if not data:
                break
            command = data.decode().strip()
            logging.info(f"Received: {command} from {addr}")
            if command == "WATER_PLANT_1":
                water_plant(1, WATERING_DURATION)
            elif command == "WATER_PLANT_2":
                water_plant(2, WATERING_DURATION)
            elif command == "GET_SENSOR_DATA":
                val1, val2 = get_sensor_data()
                if val1 != -1 and val2 != -1:
                    conn.sendall(f"Sensor Data: {val1}, {val2}\n".encode())
                else:
                    conn.sendall(b"Error getting sensor data\n")
            elif command.startswith("SET_THRESHOLD"):
                try:
                    val = int(command.split()[1])
                    set_threshold(val)
                except (IndexError, ValueError):
                    conn.sendall(b"Usage: SET_THRESHOLD <value>\n")
            elif command.startswith("SET_WATERING_DURATION"):
                try:
                    val = int(command.split()[1])
                    WATERING_DURATION = val
                    logging.info(f"Watering duration set to {val} seconds")
                    conn.sendall(b"Duration set to " + str(val).encode())
                except (IndexError, ValueError):
                    conn.sendall(b"Usage: SET_WATERING_DURATION <seconds>\n")
            else:
                conn.sendall(b"Invalid command\n")
    except Exception as e:
        logging.error(f"Error handling client {addr}: {e}")
    finally:
        conn.close()
        logging.info(f"Connection with {addr} closed")

def start_server():
    global running
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    try:
        server_socket.bind(('0.0.0.0', 12345))
        server_socket.listen(5)
        server_socket.settimeout(1.0)
        logging.info("Server listening on port 12345")
        while running:
            try:
                conn, addr = server_socket.accept()
                client_thread = threading.Thread(target=handle_client, args=(conn, addr))
                client_thread.daemon = True
                client_thread.start()
            except socket.timeout:
                continue
    except Exception as e:
        logging.error(f"Server error: {e}")
    finally:
        server_socket.close()
        logging.info("Server stopped")

def signal_handler(sig, frame):
    global running
    logging.info("Shutting down...")
    running = False

def cleanup():
    global mcp3008_1, mcp3008_2
    try:
        if mcp3008_1 is not None:
            mcp3008_1.close()
    except Exception:
        pass
    try:
        if mcp3008_2 is not None:
            mcp3008_2.close()
    except Exception:
        pass
    try:
        if MOTOR_A_ENABLE is not None:
            MOTOR_A_ENABLE.close()
    except Exception:
        pass
    try:
        if MOTOR_B_ENABLE is not None:
            MOTOR_B_ENABLE.close()
    except Exception:
        pass
    try:
        if motor_a_forward_pin is not None:
            motor_a_forward_pin.close()
    except Exception:
        pass
    try:
        if motor_a_backward_pin is not None:
            motor_a_backward_pin.close()
    except Exception:
        pass
    try:
        if motor_b_clockwise_pin is not None:
            motor_b_clockwise_pin.close()
    except Exception:
        pass
    try:
        if motor_b_counterclockwise_pin is not None:
            motor_b_counterclockwise_pin.close()
    except Exception:
        pass
    try:
        if spi_clk is not None:
            spi_clk.close()
    except Exception:
        pass
    try:
        if spi_mosi is not None:
            spi_mosi.close()
    except Exception:
        pass
    try:
        if spi_miso is not None:
            spi_miso.close()
    except Exception:
        pass
    try:
        if spi_cs_1 is not None:
            spi_cs_1.close()
    except Exception:
        pass
    try:
        if spi_cs_2 is not None:
            spi_cs_2.close()
    except Exception:
        pass
    logging.info("Cleanup complete")

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        mcp3008_1 = MCP3008(spi_clk, spi_mosi, spi_miso, spi_cs_1, MCP3008_CHANNEL_1)
        mcp3008_2 = MCP3008(spi_clk, spi_mosi, spi_miso, spi_cs_2, MCP3008_CHANNEL_2)
        server_thread = threading.Thread(target=start_server)
        server_thread.daemon = True
        server_thread.start()
        while running:
            time.sleep(60)
    except Exception as e:
        logging.error(f"Initialization error: {e}")
    finally:
        cleanup()

