import sys

# LoadCellReader class for reading and converting load cell data
class LoadCellReader:
    def __init__(self, spi_bus=0, spi_device=0, max_speed_hz=50000):
        """
        Initializes the LoadCellReader with SPI bus and device parameters.
        """
        self.spi_bus = spi_bus
        self.spi_device = spi_device
        self.max_speed_hz = max_speed_hz
        self.spi = None
        self._open_spi()

    def _open_spi(self):
        """
        Opens the SPI device and configures it for the MCP3002.
        """
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(self.spi_bus, self.spi_device)
            self.spi.max_speed_hz = self.max_speed_hz
            self.spi.mode = 0b00
            self.spi.bits_per_word = 8
        except OSError as e:
            raise OSError(f"Failed to open SPI device {self.spi_bus},{self.spi_device}: {e}")

    def read_raw_data(self):
        """
        Reads raw 10-bit data from the MCP3002 ADC.
        """
        if self.spi is None:
            raise OSError("SPI device is not initialized.")
        try:
            response = self.send_spi_command([0x01, 0x80, 0x00])
            return self.extract_10bit(response)
        except OSError as e:
            raise OSError(f"Error reading raw data from SPI: {e}")

    def convert_to_weight(self, raw_data):
        """
        Converts the raw ADC data to a weight value.
        """
        return float(raw_data) * (5.0 / 1023.0)

    def send_spi_command(self, data):
        """
        Sends a command to the MCP3002 and returns the response.
        """
        try:
            return self.spi.xfer2(data)
        except OSError as e:
            raise OSError(f"Error sending SPI command: {e}")

    def extract_10bit(self, response):
        """
        Extracts the 10-bit ADC value from the SPI response.
        """
        if len(response) < 3:
            raise OSError("Incomplete SPI response.")
        return ((response[1] & 0x03) << 8) | response[2]

    def close(self):
        """
        Closes the SPI connection.
        """
        if self.spi is not None:
            try:
                self.spi.close()
            except OSError:
                pass
            finally:
                self.spi = None


def main():
    """
    Main function to read and display weight data.
    """
    load_cell_reader = None
    try:
        load_cell_reader = LoadCellReader()
        while True:
            raw_data = load_cell_reader.read_raw_data()
            weight = load_cell_reader.convert_to_weight(raw_data)
            print(f"Weight: {weight:.2f} kg")
            time.sleep(0.5)
    except OSError as e:
        print(f"Error: {e}", file=sys.stderr)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        if load_cell_reader is not None:
            load_cell_reader.close()


if __name__ == "__main__":
    # Handle SIGTERM for clean shutdown under systemd or kill
    def _sigterm_handler(signum, frame):
        raise KeyboardInterrupt
    signal.signal(signal.SIGTERM, _sigterm_handler)
    main()

