import RPi.GPIO as GPIO
import spidev
import time
import datetime
import csv
import signal
import sys
import board
import adafruit_dht

# Constants
DHT_PIN = 4
SPI_BUS = 0
SPI_DEVICE = 0
SPI_MAX_SPEED_HZ = 1000000
GAS_SENSOR_CHANNELS = [0, 1]
MOVING_AVERAGE_WINDOW = 5
CALIBRATION_DURATION = 60
LOGGING_INTERVAL = 60
CSV_FILE = "gas_data.csv"
ERROR_LOG = "error.log"

# Global state
spi = None
dht_device = None
running = True

def log_error(message):
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    try:
        with open(ERROR_LOG, "a") as f:
            f.write(f"{timestamp} - ERROR: {message}\n")
    except Exception as e:
        print(f"Failed to write to error log: {e}")

def initialize_spi():
    global spi
    try:
        spi = spidev.SpiDev()
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_MAX_SPEED_HZ
        spi.mode = 0
        return True
    except Exception as e:
        log_error(f"SPI initialization failed: {e}")
        return False

def initialize_dht22():
    global dht_device
    try:
        dht_device = adafruit_dht.DHT22(board.D4)
        return True
    except Exception as e:
        log_error(f"DHT22 initialization failed: {e}")
        return False

def read_mcp3008(channel):
    if not 0 <= channel <= 7:
        raise ValueError("Channel must be 0-7")
    try:
        # MCP3008 single-ended read: start bit, config byte, padding
        r = spi.xfer2([1, (8 + channel) << 4, 0])
        adc_out = ((r[1] & 3) << 8) + r[2]
        return adc_out
    except Exception as e:
        log_error(f"MCP3008 read failed on channel {channel}: {e}")
        return None

def read_dht22():
    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is None or humidity is None:
            raise RuntimeError("DHT22 returned None")
        return temperature, humidity
    except Exception as e:
        log_error(f"DHT22 read failed: {e}")
        return None, None

def validate_data(temperature, humidity):
    if not -20 <= temperature <= 50:
        log_error(f"Invalid temperature: {temperature}")
        return False
    if not 0 <= humidity <= 100:
        log_error(f"Invalid humidity: {humidity}")
        return False
    return True

def moving_average(data, window_size):
    if not data:
        return 0.0
    if len(data) < window_size:
        return sum(data) / len(data)
    return sum(data[-window_size:]) / window_size

def calibrate_sensors(duration):
    print("Calibrating sensors...")
    gas_sensor_readings = [read_mcp3008(ch) for ch in GAS_SENSOR_CHANNELS]
    dht_temps = []
    dht_humids = []
    start_time = time.time()
    while time.time() - start_time < duration:
        temp, hum = read_dht22()
        if temp is not None and hum is not None:
            dht_temps.append(temp)
            dht_humids.append(hum)
        time.sleep(1)
    if not dht_temps:
        log_error("Calibration failed: no valid DHT22 readings")
        return False
    avg_temp = moving_average(dht_temps, MOVING_AVERAGE_WINDOW)
    avg_hum = moving_average(dht_humids, MOVING_AVERAGE_WINDOW)
    print(f"Calibration complete. Avg Temp: {avg_temp:.2f}C, Avg Humidity: {avg_hum:.2f}%")
    return True

def log_data(timestamp, gas_sensor_readings, dht_temperature, dht_humidity):
    try:
        with open(CSV_FILE, "a", newline="") as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow([timestamp, *gas_sensor_readings, dht_temperature, dht_humidity])
    except Exception as e:
        log_error(f"Failed to write to CSV file: {e}")

def cleanup():
    global spi, dht_device
    print("Cleaning up resources...")
    if dht_device:
        try:
            dht_device.exit()
        except Exception:
            pass
    if spi:
        try:
            spi.close()
        except Exception:
            pass
    GPIO.cleanup()
    print("Cleanup complete.")

def signal_handler(sig, frame):
    global running
    print(f"Received signal {sig}, shutting down...")
    running = False

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not initialize_spi():
        print("SPI initialization failed. Exiting.")
        sys.exit(1)

    if not initialize_dht22():
        print("DHT22 initialization failed. Exiting.")
        cleanup()
        sys.exit(1)

    if not calibrate_sensors(CALIBRATION_DURATION):
        print("Calibration failed. Exiting.")
        cleanup()
        sys.exit(1)

    print("Starting data logging...")
    while running:
        try:
            timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            gas_sensor_readings = [read_mcp3008(ch) for ch in GAS_SENSOR_CHANNELS]
            dht_temperature, dht_humidity = read_dht22()

            if dht_temperature is not None and dht_humidity is not None:
                if validate_data(dht_temperature, dht_humidity):
                    gas_sensor_readings = [r if r is not None else 0 for r in gas_sensor_readings]
                    log_data(timestamp, gas_sensor_readings, dht_temperature, dht_humidity)
                    print(f"Logged: {timestamp}, Gas: {gas_sensor_readings}, Temp: {dht_temperature:.2f}C, Humidity: {dht_humidity:.2f}%")
                else:
                    log_error("Invalid sensor data after validation")
            else:
                log_error("Failed to read DHT22 data")

            time.sleep(LOGGING_INTERVAL)
        except Exception as e:
            log_error(f"Unexpected error in main loop: {e}")
            time.sleep(LOGGING_INTERVAL)

    cleanup()

if __name__ == "__main__":
    main()

