import spidev
import RPi.GPIO as GPIO
import time
import logging
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

PUMP_RELAY_PIN = 18
DRY_THRESHOLD = 450
SPI_BUS = 0
SPI_DEVICE = 0
SPI_SPEED_HZ = 1350000


class SmartGardenController:
    def __init__(self, pump_pin, dry_threshold, spi_bus=SPI_BUS, spi_device=SPI_DEVICE, spi_speed=SPI_SPEED_HZ):
        self.pump_pin = pump_pin
        self.dry_threshold = dry_threshold
        self.spi = None
        self.spi_speed = spi_speed
        self._setup_gpio()
        self._setup_spi()

    def _setup_gpio(self):
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pump_pin, GPIO.OUT, initial=GPIO.LOW)
            logging.info("GPIO setup complete: pin %d as output, initial LOW", self.pump_pin)
        except Exception as e:
            logging.error("Failed to setup GPIO: %s", e)
            raise

    def _setup_spi(self):
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(self.spi_bus, self.spi_device)
            self.spi.max_speed_hz = self.spi_speed
            self.spi.mode = 0
            logging.info("SPI setup complete: bus %d, device %d, speed %d Hz", self.spi_bus, self.spi_device, self.spi_speed)
        except Exception as e:
            logging.error("Failed to setup SPI: %s", e)
            self.close()
            raise

    def read_moisture(self):
        """Read soil moisture from MCP3008 channel 0 (single-ended).
        Returns 10-bit value (0-1023) or None on error."""
        if self.spi is None:
            logging.error("SPI not initialized")
            return None
        try:
            # MCP3008 command: start bit (1), single-ended mode (1), channel select (3 bits)
            # For channel 0: 0b00000001 (start) | 0b00000001 (single-ended) | 0b10000000 (channel 0)
            # This sends 3 bytes: [0x01, 0x80, 0x00]
            adc = self.spi.xfer2([0x01, (0x08 | 0x00) << 4, 0x00])
            # Response: byte1 has 2 LSBs of data, byte2 has 8 bits
            data = ((adc[1] & 0x03) << 8) | adc[2]
            return data
        except Exception as e:
            logging.error("SPI read error: %s", e)
            return None

    def run_pump(self, seconds):
        """Activate pump relay for given seconds."""
        try:
            GPIO.output(self.pump_pin, GPIO.HIGH)
            logging.info("Pump ON for %d seconds", seconds)
            time.sleep(seconds)
        except Exception as e:
            logging.error("Pump control error: %s", e)
        finally:
            self.pump_off()

    def pump_off(self):
        """Deactivate pump relay."""
        try:
            GPIO.output(self.pump_pin, GPIO.LOW)
            logging.info("Pump OFF")
        except Exception as e:
            logging.error("Pump off error: %s", e)

    def irrigation_cycle(self):
        """Read moisture, log, and water if dry."""
        moisture = self.read_moisture()
        if moisture is None:
            logging.error("Moisture read failed, skipping cycle")
            return False
        logging.info("Raw moisture: %d", moisture)
        if moisture > self.dry_threshold:
            logging.info("Soil dry (%d > %d), starting irrigation", moisture, self.dry_threshold)
            self.run_pump(2)
            return True
        logging.info("Soil moist enough (%d <= %d), no watering needed", moisture, self.dry_threshold)
        return False

    def close(self):
        """Release resources."""
        try:
            self.pump_off()
        except Exception:
            pass
        if self.spi is not None:
            try:
                self.spi.close()
            except Exception:
                pass
        try:
            GPIO.cleanup()
            logging.info("GPIO cleaned up")
        except Exception as e:
            logging.error("GPIO cleanup error: %s", e)


def schedule_cycles(controller, cycle_count, interval_seconds):
    """Run a fixed number of irrigation cycles."""
    for i in range(cycle_count):
        logging.info("Cycle %d/%d", i + 1, cycle_count)
        controller.irrigation_cycle()
        if i < cycle_count - 1:
            time.sleep(interval_seconds)


def signal_handler(sig, frame):
    logging.info("Interrupt received, shutting down...")
    sys.exit(0)


if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    controller = None
    try:
        controller = SmartGardenController(PUMP_RELAY_PIN, DRY_THRESHOLD)
        schedule_cycles(controller, 10, 3)
    except KeyboardInterrupt:
        logging.info("Interrupted by user")
    except Exception as e:
        logging.error("Fatal error: %s", e)
    finally:
        if controller is not None:
            controller.close()

