class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins=None, channels=None, spi_speed=1000000, log_queue=None, sensor_ids=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.sensor_ids = sensor_ids
        self.spi = None
        self.running = False
        self.debounce_time = 0.1
        self.last_event_time = 0.0
        self.lock = threading.Lock()
        self.logger = logging.getLogger(f"SoundSensor_{sensor_id}")
        self.logger.setLevel(logging.INFO)
        self.logger.handlers.clear()
        self.logger.addHandler(logging.NullHandler())
        self.logger.propagate = False

        if self.sensor_type == "digital":
            if self.gpio_pins is None:
                raise ValueError("gpio_pins must be provided for digital sensors")
            try:
                GPIO.setmode(GPIO.BCM)
                for pin in self.gpio_pins:
                    GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
            except Exception as e:
                self.logger.error(f"GPIO setup failed: {e}")
                raise

        elif self.sensor_type == "analog":
            if self.channels is None:
                raise ValueError("channels must be provided for analog sensors")
            try:
                self.spi = spidev.SpiDev()
                self.spi.open(0, 0)
                self.spi.max_speed_hz = self.spi_speed
                self.spi.mode = 0
            except Exception as e:
                self.logger.error(f"SPI initialization failed: {e}")
                self.spi = None

        else:
            raise ValueError(f"Invalid sensor_type: {self.sensor_type}")

        self.logger.info(f"Sensor {self.sensor_id} initialized: type={self.sensor_type}, threshold={self.threshold}, sample_rate={self.sample_rate}, gpio_pins={self.gpio_pins}, channels={self.channels}, spi_speed={self.spi_speed}")

    def read_sound_level(self):
        if self.sensor_type == "digital":
            if self.gpio_pins is None:
                return None
            try:
                if self.gpio_pins:
                    return GPIO.input(self.gpio_pins[0])
            except Exception as e:
                self.logger.error(f"GPIO read error: {e}")
                return None

        elif self.sensor_type == "analog":
            if self.channels is None:
                return None
            if self.spi is None:
                return None
            try:
                if self.channels:
                    adc_value = self.spi.xfer2([1, (8 + self.channels) << 4, 0])
                    data = ((adc_value[1] & 3) << 8) + adc_value[2]
                    return data
            except Exception as e:
                self.logger.error(f"SPI read error: {e}")
                return None

        return None

    def detect_sound_event(self, sound_level):
        if self.sensor_type == "digital":
            return sound_level == 1
        elif self.sensor_type == "analog":
            return sound_level >= self.threshold
        return False

    def handle_sound_event(self, sound_level):
        current_time = time.time()
        with self.lock:
            if self.running and self.detect_sound_event(sound_level) and (current_time - self.last_event_time) > self.debounce_time:
                self.last_event_time = current_time
                if self.log_queue:
                    try:
                        self.log_queue.put((self.sensor_id, sound_level, "Sound Event Detected"))
                    except Exception as e:
                        self.logger.error(f"Failed to put event in queue: {e}")
                self.logger.info(f"Sound Event Detected by {self.sensor_id}: Level={sound_level}, ADC={sound_level if self.sensor_type == 'analog' else 'N/A'}")

    def run(self):
        self.running = True
        self.logger.info("Sound sensor started.")
        try:
            while self.running:
                sound_level = self.read_sound_level()
                if sound_level is not None:
                    self.handle_sound_event(sound_level)
                time.sleep(1 / self.sample_rate)
        except Exception as e:
            self.logger.error(f"Error in sound sensor thread: {e}")
        finally:
            self.stop()

    def stop(self):
        self.running = False
        if self.sensor_type == "digital":
            try:
                GPIO.cleanup()
            except Exception as e:
                self.logger.error(f"GPIO cleanup error: {e}")
        elif self.sensor_type == "analog" and self.spi is not None:
            try:
                self.spi.close()
            except Exception as e:
                self.logger.error(f"SPI close error: {e}")
        self.logger.info(f"Sound sensor {self.sensor_id} stopped.")

def main():
    parser = argparse.ArgumentParser(description="Raspberry Pi Sound Sensor Program")
    parser.add_argument("--sensor_type", choices=["digital", "analog"], required=True)
    parser.add_argument("--threshold", type=int, default=500)
    parser.add_argument("--sample_rate", type=int, default=10)
    parser.add_argument("--log_file", type=str, default=None)
    parser.add_argument("--gpio_pins", type=int, nargs='+', default=None)
    parser.add_argument("--channels", type=int, nargs='+', default=None)
    parser.add_argument("--spi_speed", type=int, default=1000000)
    parser.add_argument("--sensor_ids", type=str, nargs='+', default=None)

    args = parser.parse_args()

    log_queue = queue.Queue() if args.log_file else None
    sensors = []
    threads = []

    if args.sensor_ids:
        for sensor_id in args.sensor_ids:
            sensor_type = "digital" if args.gpio_pins else "analog"
            sensor = SoundSensor(
                sensor_id=sensor_id,
                sensor_type=sensor_type,
                threshold=args.threshold,
                sample_rate=args.sample_rate,
                gpio_pins=args.gpio_pins if sensor_type == "digital" else None,
                channels=args.channels if sensor_type == "analog" else None,
                spi_speed=args.spi_speed,
                log_queue=log_queue,
                sensor_ids=args.sensor_ids
            )
            sensors.append(sensor)
            t = threading.Thread(target=sensor.run, daemon=True)
            t.start()
            threads.append(t)

    if args.log_file:
        try:
            handler = logging.FileHandler(args.log_file)
            handler.setLevel(logging.INFO)
            formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
            handler.setFormatter(formatter)
            logger = logging.getLogger()
            logger.addHandler(handler)
        except Exception as e:
            print(f"Failed to create log file: {e}")

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting program...")
    finally:
        for sensor in sensors:
            sensor.stop()
        for t in threads:
            t.join(timeout=2)
        if log_queue:
            log_queue.close()

if __name__ == "__main__":
    main()

