import spidev
import time
import os
import json
import signal
import sys
from gpiozero import OutputDevice

CONFIG_FILE = "config.json"
LOG_FILE = os.path.join(os.path.expanduser("~"), "logs", "industrial_air_quality.log")

running = True

def signal_handler(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def load_config(config_file):
    try:
        with open(config_file, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        print(f"Error: Configuration file '{config_file}' not found.")
        return None
    except json.JSONDecodeError as e:
        print(f"Error: Invalid JSON in '{config_file}': {e}")
        return None

def read_mcp3008(spi, channel):
    if not 0 <= channel <= 7:
        raise ValueError(f"Invalid MCP3008 channel {channel}; must be 0-7")
    try:
        adc = spi.xfer2([0x01, (0x08 | channel) << 4, 0x00])
        return ((adc[1] & 0x03) << 8) | adc[2]
    except IOError as e:
        raise IOError(f"SPI read failed on channel {channel}: {e}")

def convert_to_voltage(adc_value, vref=3.3, rl=10000):
    return adc_value * (vref / rl)

def log_data(timestamp, mq2_voltage, mq7_voltage, mq135_voltage):
    try:
        with open(LOG_FILE, "a") as f:
            f.write(f"{timestamp},{mq2_voltage:.3f},{mq7_voltage:.3f},{mq135_voltage:.3f}\n")
    except IOError as e:
        print(f"Error writing to log file: {e}")

def main():
    config = load_config(CONFIG_FILE)
    if not config:
        sys.exit(1)

    mq2_channel = config["mq2_channel"]
    mq7_channel = config["mq7_channel"]
    mq135_channel = config["mq135_channel"]

    mq2_warning = config["mq2_warning"]
    mq2_critical = config["mq2_critical"]
    mq7_warning = config["mq7_warning"]
    mq7_critical = config["mq7_critical"]
    mq135_warning = config["mq135_warning"]
    mq135_critical = config["mq135_critical"]

    actuator_pin = config["actuator_pin"]

    spi = spidev.SpiDev()
    try:
        spi.open(0, 0)
        spi.max_speed_hz = 1000000
    except spidev.SpiDevError as e:
        print(f"Error opening SPI bus 0, CS 0: {e}")
        sys.exit(1)

    actuator = OutputDevice(actuator_pin)
    actuator.off()

    try:
        while running:
            try:
                mq2_raw = read_mcp3008(spi, mq2_channel)
                mq7_raw = read_mcp3008(spi, mq7_channel)
                mq135_raw = read_mcp3008(spi, mq135_channel)

                mq2_voltage = convert_to_voltage(mq2_raw)
                mq7_voltage = convert_to_voltage(mq7_raw)
                mq135_voltage = convert_to_voltage(mq135_raw)

                timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
                log_data(timestamp, mq2_voltage, mq7_voltage, mq135_voltage)

                print(f"{timestamp} - MQ-2: {mq2_voltage:.3f}V, MQ-7: {mq7_voltage:.3f}V, MQ-135: {mq135_voltage:.3f}V")

                if mq2_voltage > mq2_critical:
                    print("CRITICAL: MQ-2 sensor reading exceeds critical threshold!")
                    actuator.on()
                elif mq2_voltage > mq2_warning:
                    print("WARNING: MQ-2 sensor reading exceeds warning threshold!")

                if mq7_voltage > mq7_critical:
                    print("CRITICAL: MQ-7 sensor reading exceeds critical threshold!")
                    actuator.on()
                elif mq7_voltage > mq7_warning:
                    print("WARNING: MQ-7 sensor reading exceeds warning threshold!")

                if mq135_voltage > mq135_critical:
                    print("CRITICAL: MQ-135 sensor reading exceeds critical threshold!")
                    actuator.on()
                elif mq135_voltage > mq135_warning:
                    print("WARNING: MQ-135 sensor reading exceeds warning threshold!")

            except IOError as e:
                print(f"Error reading sensors: {e}")
            except Exception as e:
                print(f"Unexpected error: {e}")

            time.sleep(5)

    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        try:
            spi.close()
        except Exception:
            pass
        try:
            actuator.off()
            actuator.close()
        except Exception:
            pass
        print("Resources cleaned up. Exiting.")

if __name__ == "__main__":
    main()

