import time
import json
import logging
import signal
import sys
import os

import cv2
import numpy as np
from picamera2 import Picamera2
from gpiozero import OutputDevice

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

CONFIG_FILE = "config.json"

running = True

def signal_handler(sig, frame):
    global running
    running = False
    logging.info("Shutdown signal received. Cleaning up...")

def load_config(config_file):
    try:
        with open(config_file, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        logging.error(f"Configuration file not found: {config_file}")
        return None
    except json.JSONDecodeError:
        logging.error(f"Invalid JSON format in configuration file: {config_file}")
        return None

def capture_image(camera):
    try:
        frame = camera.capture_array()
        if frame is None:
            logging.error("Failed to capture image: camera returned None.")
            return None
        return frame
    except Exception as e:
        logging.error(f"Error capturing image: {e}")
        return None

def preprocess_image(image):
    try:
        resized_image = cv2.resize(image, (224, 224))
        normalized_image = resized_image.astype(np.float32) / 255.0
        reshaped_image = normalized_image.reshape(1, 224, 224, 3)
        return reshaped_image
    except Exception as e:
        logging.error(f"Error preprocessing image: {e}")
        return None

def predict_bird_species(model, image):
    try:
        prediction = model.predict(image, verbose=0)
        return np.argmax(prediction)
    except Exception as e:
        logging.error(f"Error during prediction: {e}")
        return None

def indicate_bird(led_pin, duration=1.0):
    try:
        led = OutputDevice(led_pin)
        led.on()
        time.sleep(duration)
        led.off()
    except Exception as e:
        logging.error(f"Error controlling LED: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

