import logging
import signal
import sys
from picamera2 import Picamera2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

running = True
cameras = []

def signal_handler(signum, frame):
    global running
    logger.info(f"Signal {signum} received, shutting down...")
    running = False

def cleanup():
    global cameras
    for cam in cameras:
        try:
            if cam.started:
                cam.stop()
            cam.close()
        except Exception as e:
            logger.warning(f"Error closing camera: {e}")
    cv2.destroyAllWindows()
    logger.info("Resources cleaned up.")

def main():
    global running, cameras
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        cam0 = Picamera2(camera_num=0)
        cam1 = Picamera2(camera_num=1)
        config0 = cam0.create_preview_configuration(
            main={"size": (640, 480), "format": "RGB888"},
            controls={"FrameDurationLimits": (33333, 33333)}
        )
        config1 = cam1.create_preview_configuration(
            main={"size": (640, 480), "format": "RGB888"},
            controls={"FrameDurationLimits": (33333, 33333)}
        )
        cam0.configure(config0)
        cam1.configure(config1)
        if not cam0.started:
            raise RuntimeError("Camera 0 failed to start")
        if not cam1.started:
            raise RuntimeError("Camera 1 failed to start")
        cameras = [cam0, cam1]
        logger.info("Both cameras initialized successfully.")
    except Exception as e:
        logger.error(f"Camera initialization failed: {e}")
        cleanup()
        sys.exit(1)

    try:
        while running:
            try:
                frame0 = cam0.capture_array()
                frame1 = cam1.capture_array()
            except Exception as e:
                logger.error(f"Frame capture failed: {e}")
                break

            if frame0 is None or frame1 is None:
                logger.warning("Received None frame, skipping.")
                continue

            combined = np.hstack((frame0, frame1))
            cv2.imshow('Dual CSI Cameras', combined)

            key = cv2.waitKey(30) & 0xFF
            if key == 27:
                logger.info("ESC pressed, exiting.")
                break

            if cv2.getWindowProperty('Dual CSI Cameras', cv2.WND_PROP_VISIBLE) < 1:
                logger.info("Display window closed by user.")
                break

    except KeyboardInterrupt:
        logger.info("KeyboardInterrupt received.")
    except Exception as e:
        logger.error(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

