#!/usr/bin/env python3
"""Wildlife camera system using PIR motion sensor and picamera2."""

import configparser
import datetime
import logging
import os
import signal
import sys
import time
from pathlib import Path

import gpiozero
from picamera2 import Picamera2
from picamera2.encoders import H264Encoder
from picamera2.outputs import FileOutput

DEFAULT_CONFIG = {
    'resolution': '640x480',
    'frame_rate': '20',
    'image_quality': '85',
    'video_bitrate': '1700000',
    'gpio_pin': '4',
    'motion_delay': '2',
    'storage_directory': '/home/pi/wildlife_media',
    'disk_space_threshold_mb': '500',
    'log_file': '/var/log/wildlifecam/wildlifecam.log',
    'log_level': 'INFO',
}

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def load_config(config_file='config.ini'):
    config = configparser.ConfigParser()
    if not config.read(config_file):
        logging.warning(f"Config file '{config_file}' not found; creating with defaults.")
        for key, value in DEFAULT_CONFIG.items():
            config.set('DEFAULT', key, value)
        with open(config_file, 'w') as f:
            config.write(f)
    return config


def setup_logging(log_file, log_level):
    log_dir = os.path.dirname(log_file)
    if not os.path.exists(log_dir):
        try:
            os.makedirs(log_dir, exist_ok=True)
        except OSError as e:
            print(f"Cannot create log directory {log_dir}: {e}", file=sys.stderr)
            return
    level = getattr(logging, log_level.upper(), logging.INFO)
    logging.basicConfig(
        filename=log_file,
        level=level,
        format='%(asctime)s - %(levelname)s - %(message)s',
    )
    logging.info("Logging initialized.")


def setup_camera(config):
    try:
        picam2 = Picamera2()
        w, h = map(int, config['resolution'].split('x'))
        video_config = picam2.create_video_configuration(
            main={"size": (w, h), "format": "RGB888"},
            lores={"size": (w, h), "format": "YUV420"},
            encode="lores",
        )
        picam2.configure(video_config)
        picam2.start()
        logging.info("Camera initialized successfully.")
        return picam2
    except Exception as e:
        logging.error(f"Camera initialization failed: {e}")
        return None


def setup_gpio(pin, config):
    try:
        pir = gpiozero.MotionSensor(pin, pull_up=False)
        logging.info(f"PIR sensor initialized on GPIO {pin}.")
        return pir
    except Exception as e:
        logging.error(f"GPIO setup failed: {e}")
        return None


def capture_images(picam2, config, pir, motion_delay, storage_dir):
    try:
        os.makedirs(storage_dir, exist_ok=True)
        now = datetime.datetime.now()
        date_dir = os.path.join(storage_dir, now.strftime("%Y/%m/%d"))
        os.makedirs(date_dir, exist_ok=True)

        image_count = 0
        for i in range(3):
            if not _running:
                break
            filename = os.path.join(date_dir, f"image_{i + 1:03d}.jpg")
            try:
                picam2.capture_file(filename, format="jpeg")
                logging.info(f"Captured image: {filename}")
                image_count += 1
            except Exception as e:
                logging.error(f"Failed to capture image {i + 1}: {e}")
            if i < 2 and _running:
                time.sleep(0.5)
        if not _running:
            return
        logging.info("Image capture complete.")

        check_and_free_space(storage_dir, config, date_dir)
        start_video(picam2, config, date_dir)
    except Exception as e:
        logging.error(f"Error during image capture: {e}")


def check_and_free_space(storage_dir, config, date_dir):
    threshold_mb = int(config['disk_space_threshold_mb'])
    try:
        stat = os.statvfs(storage_dir)
        available_mb = (stat.f_bavail * stat.f_frsize) / (1024 * 1024)
        if available_mb < threshold_mb:
            logging.warning(
                f"Disk space low ({available_mb:.1f} MB < {threshold_mb} MB). "
                "Deleting oldest files."
            )
            delete_oldest_files(storage_dir, date_dir)
    except Exception as e:
        logging.error(f"Error checking disk space: {e}")


def delete_oldest_files(storage_dir, date_dir):
    try:
        files = []
        for entry in os.scandir(storage_dir):
            if entry.is_dir():
                files.append(entry)
        if not files:
            return
        files.sort(key=lambda f: f.stat().st_ctime)
        oldest_video = os.path.join(files[0], 'video.h264')
        if os.path.exists(oldest_video):
            try:
                os.remove(oldest_video)
                logging.info(f"Deleted oldest video: {oldest_video}")
            except Exception as e:
                logging.error(f"Failed to delete oldest video: {e}")
        oldest_image = os.path.join(files[0], 'image_001.jpg')
        if os.path.exists(oldest_image):
            try:
                os.remove(oldest_image)
                logging.info(f"Deleted oldest image: {oldest_image}")
            except Exception as e:
                logging.error(f"Failed to delete oldest image: {e}")
    except Exception as e:
        logging.error(f"Error deleting files: {e}")


def start_video(picam2, config, date_dir):
    try:
        video_path = os.path.join(date_dir, 'video.h264')
        encoder = H264Encoder(bitrate=int(config['video_bitrate']))
        output = FileOutput(video_path)
        picam2.start_recording(encoder, output)
        logging.info(f"Started video recording: {video_path}")
        time.sleep(5)
        picam2.stop_recording()
        logging.info("Video recording complete.")
    except Exception as e:
        logging.error(f"Error during video recording: {e}")


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    config = load_config()
    setup_logging(config['log_file'], config['log_level'])

    storage_dir = config['storage_directory']
    picam2 = setup_camera(config)
    pir = setup_gpio(int(config['gpio_pin']), config)

    if picam2 is None and pir is None:
        logging.error("Both camera and GPIO initialization failed. Exiting.")
        sys.exit(1)

    try:
        while _running:
            if pir is not None:
                if pir.wait_for_active(timeout=10):
                    logging.info("Motion detected!")
                    capture_images(picam2, config, pir, float(config['motion_delay']), storage_dir)
            else:
                time.sleep(1)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        if picam2 is not None:
            try:
                picam2.stop()
                picam2.close()
            except Exception:
                pass
        if pir is not None:
            try:
                pir.close()
            except Exception:
                pass
        logging.info("Cleanup complete. Exiting.")


if __name__ == "__main__":
    main()

