        except Exception:
            pass
    try:
        GPIO.cleanup()
    except Exception:
        pass

def initialize_arduino():
    try:
        arduino = serial.Serial(SERIAL_PORT, SERIAL_BAUDRATE, timeout=1)
        time.sleep(2)
        return arduino
    except serial.SerialException as e:
