import time
import json
import logging
import signal
import sys
import os

try:
    from gpiozero import OutputDevice, InputDevice
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero")
    sys.exit(0)

DEFAULT_CONFIG = {
    "sensors": [
        {"trigger_pin": 17, "echo_pin": 18, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 22, "echo_pin": 23, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 24, "echo_pin": 25, "offset": 0.0, "max_distance": 200.0}
    ],
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log"
}

running = True

def signal_handler(signum, frame):
    global running
    running = False

def load_config(config_file="config.json"):
    if not os.path.exists(config_file):
        logging.warning(f"Config file '{config_file}' not found. Creating default configuration.")
        try:
            with open(config_file, "w") as f:
                json.dump(DEFAULT_CONFIG, f, indent=4)
        except OSError as e:
            logging.error(f"Failed to write default config: {e}")
        return dict(DEFAULT_CONFIG)
    try:
        with open(config_file, "r") as f:
            config = json.load(f)
        if not isinstance(config, dict):
            logging.error("Config file must be a JSON object.")
            sys.exit(1)
        return config
    except (json.JSONDecodeError, OSError) as e:
        logging.error(f"Error loading config: {e}. Using defaults.")
        return dict(DEFAULT_CONFIG)

def measure_distance(trigger_pin, echo_pin, offset, max_distance):
    try:
        trigger = OutputDevice(trigger_pin)
        echo = InputDevice(echo_pin)
    except Exception as e:
        logging.error(f"GPIO initialization failed for trigger={trigger_pin}, echo={echo_pin}: {e}")
        return None

    try:
        trigger.off()
        time.sleep(0.000002)  # 2 microseconds settle

        trigger.on()
        time.sleep(0.00001)   # 10 microsecond pulse
        trigger.off()

        timeout = time.time() + 0.05
        while not echo.is_active:
            if time.time() > timeout:
                logging.warning(f"Timeout waiting for echo rising edge on trigger={trigger_pin}, echo={echo_pin}")
                return None
            time.sleep(0.00001)

        pulse_start = time.time()
        timeout = pulse_start + 0.05
        while not echo.is_active:
            if time.time() > timeout:
                logging.warning(f"Timeout waiting for echo HIGH pulse start on trigger={trigger_pin}, echo={echo_pin}")
                return None
            time.sleep(0.00001)

        pulse_end = time.time()
        timeout = pulse_end + 0.05
        while echo.is_active:
            if time.time() > timeout:
                logging.warning(f"Timeout waiting for echo LOW pulse end on trigger={trigger_pin}, echo={echo_pin}")
                return None
            time.sleep(0.00001)

        pulse_duration = pulse_end - pulse_start
        distance = (pulse_duration * 34300) / 2.0
        distance += offset
        distance = max(0.0, min(distance, max_distance))
        return distance
    except Exception as e:
        logging.error(f"Error measuring distance on trigger={trigger_pin}, echo={echo_pin}: {e}")
        return None
    finally:
        try:
            trigger.close()
            echo.close()
        except Exception:
            pass

def get_water_level(sensor_config):
    readings = []
    for _ in range(3):
        distance = measure_distance(
            sensor_config["trigger_pin"],
            sensor_config["echo_pin"],
            sensor_config["offset"],
            sensor_config["max_distance"]
        )
        if distance is not None:
            water_level = sensor_config["max_distance"] - distance
            readings.append(water_level)
        else:
            logging.warning(f"Failed to get valid reading from sensor on trigger={sensor_config['trigger_pin']}, echo={sensor_config['echo_pin']}")
        time.sleep(0.1)

    if not readings:
        return None
    return sum(readings) / len(readings)

def check_alerts(sensor_config, water_levels):
    low_threshold = sensor_config["alert_threshold_low"]
    high_threshold = sensor_config["alert_threshold_high"]
    avg_water_level = sum(water_levels) / len(water_levels)

    if avg_water_level < low_threshold:
        logging.warning(f"Low water level alert: Average water level is {avg_water_level:.2f} cm, threshold is {low_threshold:.2f} cm")
    if avg_water_level > high_threshold:
        logging.warning(f"High water level alert: Average water level is {avg_water_level:.2f} cm, threshold is {high_threshold:.2f} cm")

    last_low_alert_time = 0.0
    last_high_alert_time = 0.0
    for i, water_level in enumerate(water_levels):
        if water_level < low_threshold:
            if time.time() - last_low_alert_time >= sensor_config["alert_repeat_delay"]:
                logging.warning(f"Low water level alert: Sensor {i+1} water level is {water_level:.2f} cm, threshold is {low_threshold:.2f} cm")
                last_low_alert_time = time.time()
        if water_level > high_threshold:
            if time.time() - last_high_alert_time >= sensor_config["alert_repeat_delay"]:
                logging.warning(f"High water level alert: Sensor {i+1} water level is {water_level:.2f} cm, threshold is {high_threshold:.2f} cm")
                last_high_alert_time = time.time()

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = load_config()
    sensors = config["sensors"]
    alert_repeat_delay = config["alert_repeat_delay"]
    log_file = config["log_file"]

    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s'
    )
    logging.info("Starting water level monitoring system")

    trigger_pins = []
    echo_pins = []
    for sensor in sensors:
        trigger_pins.append(sensor["trigger_pin"])
        echo_pins.append(sensor["echo_pin"])

    water_levels = []
    error_counts = [0] * len(sensors)
    last_error_times = [0.0] * len(sensors)

    try:
        while running:
            for i, sensor in enumerate(sensors):
                try:
                    water_level = get_water_level(sensor)
                    if water_level is not None:
                        water_levels.append(water_level)
                        error_counts[i] = 0
                        last_error_times[i] = time.time()
                        logging.info(f"Sensor {i+1}: Water level = {water_level:.2f} cm")
                    else:
                        error_counts[i] += 1
                        last_error_times[i] = time.time()
                        if error_counts[i] >= 5:
                            logging.error(f"Sensor {i+1} has failed 5 times in a row. Disabling sensor.")
                            error_counts[i] = 0
                            last_error_times[i] = 0
                except Exception as e:
                    logging.error(f"Unexpected error reading sensor {i+1}: {e}")
                    error_counts[i] += 1
                    last_error_times[i] = time.time()

            if water_levels:
                check_alerts(sensors[0], water_levels)

            time.sleep(5)
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        logging.info("Exiting water level monitoring system")

if __name__ == "__main__":
    main()

