#!/usr/bin/env python3

import os
import sys
import time
import signal
import logging
import datetime
import speech_recognition as sr
from PIL import Image
import RPi.GPIO as GPIO

# Configuration
DHT_PIN = 4
LIGHTS_PIN = 17
CAMERA_RESOLUTION = (640, 480)
WAKE_WORD = "Greenhouse"
LISTEN_TIMEOUT = 5

# Logging setup
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Global state
lights_on = False
camera = None
running = True

# GPIO setup with fallback to simulated mode
try:
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(LIGHTS_PIN, GPIO.OUT, initial=GPIO.LOW)
    logging.info("GPIO initialized successfully.")
except Exception as e:
    logging.warning(f"GPIO initialization failed: {e}. Running in simulated mode.")
    GPIO_AVAILABLE = False
else:
    GPIO_AVAILABLE = True

def simulate_gpio_output(pin, state):
    """Simulated GPIO output function."""
    logging.debug(f"Simulated GPIO output: pin={pin}, state={state}")

def turn_lights_on():
    """Turns the greenhouse lights on."""
    global lights_on
    if GPIO_AVAILABLE:
        try:
            GPIO.output(LIGHTS_PIN, GPIO.HIGH)
            lights_on = True
            logging.info("Greenhouse lights turned ON.")
        except Exception as e:
            logging.error(f"Error turning lights on: {e}")
            simulate_gpio_output(LIGHTS_PIN, GPIO.HIGH)
    else:
        simulate_gpio_output(LIGHTS_PIN, GPIO.HIGH)
        lights_on = True
        logging.info("Simulated: Greenhouse lights turned ON.")

def turn_lights_off():
    """Turns the greenhouse lights off."""
    global lights_on
    if GPIO_AVAILABLE:
        try:
            GPIO.output(LIGHTS_PIN, GPIO.LOW)
            lights_on = False
            logging.info("Greenhouse lights turned OFF.")
        except Exception as e:
            logging.error(f"Error turning lights off: {e}")
            simulate_gpio_output(LIGHTS_PIN, GPIO.LOW)
    else:
        simulate_gpio_output(LIGHTS_PIN, GPIO.LOW)
        lights_on = False
        logging.info("Simulated: Greenhouse lights turned OFF.")

def read_temperature():
    """Reads the temperature from the DHT11 sensor. Falls back to simulation if unavailable."""
    try:
        import adafruit_dht
        import board
        dht_device = adafruit_dht.DHT11(board.D4)
        temperature = dht_device.temperature
        dht_device.exit()
        if temperature is not None:
            logging.info(f"Temperature: {temperature:.1f}°C")
            return temperature
        else:
            logging.warning("DHT11 returned None temperature.")
            return None
    except ImportError:
        logging.warning("adafruit_dht library not found. Using simulated temperature.")
        return 25.0 + (time.time() % 10)
    except Exception as e:
        logging.error(f"Error reading temperature: {e}. Using simulated temperature.")
        return 25.0 + (time.time() % 10)

def take_picture():
    """Captures an image using the Raspberry Pi camera (picamera2). Falls back to simulation if unavailable."""
    global camera
    try:
        from picamera2 import Picamera2
        camera = Picamera2()
        camera.configure(camera.create_still_configuration(main={"size": CAMERA_RESOLUTION}))
        camera.start()
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = f"greenhouse_{timestamp}.jpg"
        camera.capture_file(filename)
        logging.info(f"Picture saved as {filename}")
        return filename
    except ImportError:
        logging.warning("picamera2 library not found. Using simulated image.")
        return "simulated_image.jpg"
    except Exception as e:
        logging.error(f"Error taking picture: {e}. Using simulated image.")
        return "simulated_image.jpg"
    finally:
        if camera is not None:
            try:
                camera.stop()
                camera.close()
            except Exception as e:
                logging.error(f"Error closing camera: {e}")

def cleanup(signum=None, frame=None):
    """Clean up resources on exit."""
    global running
    running = False
    logging.info("Cleaning up resources...")
    if GPIO_AVAILABLE:
        try:
            GPIO.cleanup()
            logging.info("GPIO cleaned up.")
        except Exception as e:
            logging.error(f"Error cleaning up GPIO: {e}")
    logging.info("Program finished.")
    sys.exit(0)

def main():
    """Main function to run the voice-controlled greenhouse system."""
    global running
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    r = sr.Recognizer()
    try:
        mic = sr.Microphone()
    except Exception as e:
        logging.error(f"Error initializing microphone: {e}")
        return

    with mic as source:
        logging.info("Say 'Greenhouse' followed by a command...")
        r.adjust_for_ambient_noise(source)

        while running:
            try:
                audio = r.listen(source, timeout=LISTEN_TIMEOUT)
                words = r.recognize_google(audio)
                logging.info(f"You said: {words}")

                if "Greenhouse" in words.lower():
                    if "turn on the lights" in words.lower():
                        turn_lights_on()
                    elif "turn off the lights" in words.lower():
                        turn_lights_off()
                    elif "what is the temperature" in words.lower():
                        temp = read_temperature()
                        if temp is not None:
                            print(f"Temperature: {temp:.1f}°C")
                    elif "take a picture" in words.lower():
                        take_picture()
                    else:
                        logging.warning("Unknown command.")
            except sr.WaitTimeoutError:
                logging.warning("Listening timed out. No speech detected.")
            except sr.UnknownValueError:
                logging.warning("Could not understand audio.")
            except sr.RequestError as e:
                logging.error(f"Could not request results from Google Web Speech API: {e}")
            except Exception as e:
                logging.error(f"An unexpected error occurred: {e}")

    cleanup()

if __name__ == "__main__":
    main()

