import cv2
import time
import signal
import sys
import config
import face
import hardware

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

signal.signal(signal.SIGINT, _signal_handler)

def cleanup(picam2=None):
    if picam2 is not None:
        try:
            picam2.stop()
        except Exception:
            pass
    print("Exiting...")

def main():
    global _running

    if Picamera2 is None:
        print("picamera2 is not installed. Install with: pip install picamera2")
        sys.exit(1)

    picam2 = None
    box = None
    try:
        picam2 = Picamera2()
        picam2.configure(picam2.create_preview_configuration(
            main={"size": (640, 480), "format": "XRGB8888"}
        ))
        picam2.start()
        time.sleep(2.0)

        box = hardware.Box()
        box.lock()
        print("Box is locked.")

        cascade_path = cv2.data.haarcascades + 'haarcascade_frontalface_default.xml'
        face_cascade = cv2.CascadeClassifier(cascade_path)
        if face_cascade.empty():
            print(f"Failed to load Haar cascade from {cascade_path}")
            return

        model = cv2.face.EigenFaceRecognizer_create()
        model.read(config.TRAINING_FILE)
        print("Model loaded.")

        while _running:
            if box.is_button_up():
                try:
                    frame = picam2.capture_array()
                    if frame is None or frame.size == 0:
                        print("Empty frame captured.")
                        time.sleep(0.1)
                        continue

                    gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
                    faces = face_cascade.detectMultiScale(
                        gray, scaleFactor=1.3, minNeighbors=5, minSize=(30, 30)
                    )

                    if len(faces) > 0:
                        x, y, w, h = faces[0]
                        face_roi = gray[y:y + h, x:x + w]
                        resized_face = cv2.resize(
                            face_roi, (100, 100), interpolation=cv2.INTER_AREA
                        )
                        label, confidence = model.predict(resized_face)
                        print(
                            f"Predicted label: {label}, Confidence: {confidence}"
                        )

                        if label == config.POSITIVE_LABEL and config.POSITIVE_THRESHOLD > confidence > 1500:
                            box.unlock()
                            print("Box is unlocked.")
                        else:
                            print("Access denied.")
                            box.lock()
                            print("Box is locked.")
                    else:
                        print("No faces detected.")
                except Exception as e:
                    print(f"Error during capture/detection: {e}")

            time.sleep(0.1)

    except Exception as e:
        print(f"Fatal error: {e}")
    finally:
        cleanup(picam2)

if __name__ == "__main__":
    main()

