import signal
import sys
import time

try:
    from gpiozero import Button, OutputDevice
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

INPUT_PINS = [4, 5, 6]
OUTPUT_PINS = [23, 24]
POLL_INTERVAL = 0.05

_running = True
_inputs = []
_outputs = []


def _handle_signal(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _inputs, _outputs
    for dev in _outputs:
        try:
            dev.close()
        except DeviceClosed:
            pass
        except Exception:
            pass
    for dev in _inputs:
        try:
            dev.close()
        except Exception:
            pass
    _inputs.clear()
    _outputs.clear()


def main():
    global _inputs, _outputs

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        for pin in INPUT_PINS:
            btn = Button(pin, pull_up=True, bounce_time=0.02)
            _inputs.append(btn)
        for pin in OUTPUT_PINS:
            out = OutputDevice(pin, initial_value=False)
            _outputs.append(out)
    except GPIOZeroError as e:
        print(f"GPIO initialization error: {e}", file=sys.stderr)
        _cleanup()
        sys.exit(1)
    except PermissionError:
        print("Permission denied: run with sudo or add user to gpio/gpiomem groups.", file=sys.stderr)
        _cleanup()
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error during GPIO setup: {e}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    state = [False, False]

    try:
        while _running:
            for i, btn in enumerate(INPUT_PINS):
                try:
                    if not btn.is_active:
                        if i == 0 and _outputs[0].is_active:
                            _outputs[0].on()
                        elif i == 1 and not _outputs[0].is_active:
                            _outputs[0].off()
                        elif i == 2 and state[1] and not _outputs[1].is_active:
                            state[1] = False
                            _outputs[1].on()
                        elif i == 2 and not state[1] and _outputs[1].is_active:
                            state[1] = True
                            _outputs[1].off()
                except DeviceClosed:
                    print("GPIO device closed unexpectedly.", file=sys.stderr)
                    break
                except Exception as e:
                    print(f"Error reading GPIO {btn.pin}: {e}", file=sys.stderr)

            time.sleep(POLL_INTERVAL)
    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

