import argparse
import json
import logging
import signal
import sys
import time
from collections import Counter
from pathlib import Path

import cv2
import face_recognition
import numpy as np
from gpiozero import OutputDevice
from picamera2 import Picamera2

DEFAULT_RESOLUTION = (640, 480)
DEFAULT_MOTION_THRESHOLD = 500
DEFAULT_CONFIDENCE_THRESHOLD = 0.6
DEFAULT_DOOR_OPEN_DURATION = 5
DEFAULT_DEBOUNCE_TIME = 2
DEFAULT_LOG_LEVEL = "INFO"
RELAY_PIN = 17

running = True
relay = None
picam2 = None


def parse_args():
    p = argparsement.ArgumentParser(description="Raspberry Pi facial-recognition door-access system")
    p.add_argument("--resolution", default="640x480", help="Camera resolution WxH")
    p.add_argument("--motion_threshold", type=int, default=DEFAULT_MOTION_THRESHOLD, help="Pixel-difference count to trigger motion detection")
    p.add_argument("--confidence_threshold", type=float, default=DEFAULT_CONFIDENCE_THRESHOLD, help="Face-recognition confidence threshold")
    p.add_argument("--door_open_duration", type=int, default=DEFAULT_DOOR_OPEN_DURATION, help="Relay on duration in seconds")
    p.add_argument("--debounce_time", type=int, default=DEFAULT_DEBOUNCE_TIME, help="Minimum seconds between relay activations")
    p.add_argument("--log_level", default=DEFAULT_LOG_LEVEL, choices=["DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"], help="Logging level")
    return p.parse_args()


def setup_logging(level_name):
    level = getattr(logging, level_name.upper(), logging.INFO)
    logging.basicConfig(
        level=level,
        format="%(asctime)s - %(levelname)s - %(message)s",
        datefmt="%Y-%m-%d %H:%M:%S",
    )


def load_encodings(path):
    encs = {}
    try:
        with open(path, "r") as f:
            encs = json.load(f)
        logging.info("Loaded %d encodings from %s", len(encs), path)
    except FileNotFoundError:
        logging.warning("Encodings file not found; starting with empty database.")
    except json.JSONDecodeError as exc:
        logging.error("JSON decode error in %s: %s", path, exc)
    except OSError as exc:
        logging.error("Cannot read %s: %s", path, exc)
    return encs


def init_camera(width, height):
    global picam2
    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(
            main={"format": "XRGB8888", "size": (width, height)}
        )
        picam2.configure(config)
        picam2.start()
        time.sleep(2)
        logging.info("Camera initialized at %dx%d", width, height)
        return True
    except Exception as exc:
        logging.error("Camera init failed: %s", exc)
        picam2 = None
        return False


def capture_frame():
    try:
        return picam2.capture_array()
    except Exception as exc:
        logging.error("Frame capture error: %s", exc)
        return None


def detect_motion(frame1, frame2):
    try:
        diff = cv2.absdiff(frame1, frame2)
        gray = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
        blur = cv2.GaussianBlur(gray, (5, 5), 0)
        _, thresh = cv2.threshold(blur, 20, 255, cv2.THRESH_BINARY)
        motion_pixels = int(np.count_nonzero(thresh))
        return motion_pixels > 0
    except Exception as exc:
        logging.error("Motion detection error: %s", exc)
        return False


def recognize_faces(frame):
    try:
        rgb = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
        boxes = face_recognition.face_locations(rgb)
        encs = face_recognition.face_encodings(rgb, boxes)
        known_encs = list(load_encodings("encodings.json").values())
        results = []
        for enc in encs:
            matches = face_recognition.compare_faces(known_encs, enc)
            distances = face_recognition.face_distance(known_encs, enc)
            best_idx = int(np.argmin(distances))
            if matches[best_idx] and distances[best_idx] <= 0.6:
                name = list(load_encodings("encodings.json").keys())[best_idx]
                conf = 1.0 - distances[best_idx]
                results.append((name, conf))
            else:
                results.append(("Unknown", 0.0))
        return results
    except Exception as exc:
        logging.error("Face recognition error: %s", exc)
        return []


def activate_relay():
    global relay
    if relay is None:
        logging.warning("Relay not initialized; cannot activate.")
        return
    try:
        relay.on()
        logging.info("Relay activated.")
    except Exception as exc:
        logging.error("Relay on error: %s", exc)


def deactivate_relay():
    global relay
    if relay is None:
        logging.warning("Relay not initialized; cannot deactivate.")
        return
    try:
        relay.off()
        logging.info("Relay deactivated.")
    except Exception as exc:
        logging.error("Relay off error: %s", exc)


def signal_handler(signum, frame):
    global running
    logging.info("Signal %s received; shutting down.", signum)
    running = False


def main():
    global relay
    args = parse_args()
    setup_logging(args.log_level)
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    width, height = map(int, args.resolution.split("x"))
    if not init_camera(width, height):
        sys.exit(1)
    try:
        relay = OutputDevice(RELAY_PIN, active_high=True, initial_value=False)
    except Exception as exc:
        logging.error("Relay init error on GPIO %d: %s", RELAY_PIN, exc)
        relay = None
    last_relay_off = 0.0
    frame1 = None
    try:
        while running:
            frame = capture_frame()
            if frame is None:
                time.sleep(0.1)
                continue
            if frame1 is None:
                frame1 = frame.copy()
                time.sleep(0.05)
                continue
            if detect_motion(frame1, frame):
                results = recognize_faces(frame)
                for name, conf in results:
                    logging.info("Recognized: %s (%.2f)", name, conf)
                if conf > args.confidence_threshold:
                    now = time.time()
                    if now - last_relay_off >= args.debounce_time:
                        activate_relay()
                        last_relay_off = now
                        time.sleep(args.door_open_duration)
                        deactivate_relay()
                else:
                    logging.info("No match above threshold.")
            frame1 = frame.copy()
            time.sleep(0.033)
    except Exception as exc:
        logging.error("Unexpected error: %s", exc)
    finally:
        if relay is not None:
            deactivate_relay()
        if picam2 is not None:
            try:
                picam2.stop()
            except Exception:
                pass
        logging.info("Shutdown complete.")


if __name__ == "__main__":
    main()

