    def __init__(self):
        self.connections = 0
        self.lock = threading.Lock()

    def has_connections(self) -> bool:
        with self.lock:
            return self.connections > 0

    def broadcast(self, data: bytes) -> None:
        with self.lock:
            if self.connections > 0:
                try:
                    asyncio.run_coroutine_threadsafe(self._send(data), asyncio.get_event_loop())
                except RuntimeError:
                    logger.warning("No event loop available for broadcast.")

    async def _send(self, data: bytes) -> None:
        raise NotImplementedError("Must be implemented by subclass.")


class CameraStreamHandler(WebSocketHandler):
    """Handles camera streaming and motion detection."""

    def __init__(self, detect_motion_function, loop=None):
        super().__init__()
        self.detect_motion_function = detect_motion_function
        self.loop = loop if loop else asyncio.new_event_loop()
        self.picam2 = None
        self.prev_frame = None
        self.current_frame = None
        self.lock = threading.Lock()
        self._shutdown = threading.Event()

    def _send(self, data: bytes) -> None:
        try:
            self.loop.create_task(self.detect_motion_function(data))
        except Exception as e:
            logger.error(f"Error in motion detection function: {e}")

    def start_camera(self):
        try:
            self.picam2 = Picamera2()
            config = self.picam2.create_video_configuration(
                main={"size": (640, 480), "format": "RGB888"},
                lores={"size": (640, 480), "format": "YUV420"},
            )
            self.picam2.configure(config)
            self.picam2.start()
