        if self.picam2:
            try:
                self.picam2.stop_recording()
                self.picam2.stop()
                self.picam2.close()
                logger.info("Camera recording stopped and closed.")
            except Exception as e:
                logger.error(f"Error stopping camera: {e}")
            finally:
