                except Exception as e:
                    logger.error(f"Error in motion detection function: {e}")
        except Exception as e:
            logger.error(f"Error processing frame: {e}")

    def run(self):
        if not self.loop.is_running():
            self.loop.run_until_complete(self._run_forever())
        else:
            self._run_forever()

