import smbus2
import time
import datetime
import logging
import logging.handlers
import threading
import numpy as np
import matplotlib.pyplot as plt
import configparser
import signal
import sys
import os

try:
    import adafruit_amg88xx
except ImportError:
    adafruit_amg88xx = None

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

DEFAULT_CONFIG = {
    'sampling_rate': 5,
    'motion_detection_threshold': 1.0,
    'logging_file_path': 'beehive.log',
    'log_max_size': 1048576,
    'enable_camera': False
}

class BeehiveMonitor:
    def __init__(self, config_file='config.json'):
        self.config = self._load_config(config_file)
        self.sampling_rate = self.config.getint('sampling_rate', DEFAULT_CONFIG['sampling_rate'])
        self.motion_detection_threshold = self.config.getfloat('motion_detection_threshold', DEFAULT_CONFIG['motion_detection_threshold'])
        self.logging_file_path = self.config.get('logging_file_path', DEFAULT_CONFIG['logging_file_path'])
        self.log_max_size = self.config.getint('log_max_size', DEFAULT_CONFIG['log_max_size'])
        self.enable_camera = self.config.getboolean('enable_camera', DEFAULT_CONFIG['enable_camera'])

        self.logger = self._setup_logging()
        self.i2c_bus = None
        self.thermal_sensor = None
        self.camera = None
        self.thermal_frames = None
        self.thermal_lock = threading.Lock()
        self.running = True
        self.motion_detected = False
        self.last_frame = None
        self.last_motion_time = None
        self.motion_thread = None
        self.sensor_thread = None

    def _load_config(self, config_file):
        config = configparser.ConfigParser()
        try:
            with open(config_file, 'r') as f:
                config.read_file(f)
        except FileNotFoundError:
            logging.warning(f"Config file '{config_file}' not found. Using defaults.")
            return DEFAULT_CONFIG
        except Exception as e:
            logging.error(f"Error loading config: {e}. Using defaults.")
            return DEFAULT_CONFIG
        return config

    def _setup_logging(self):
        logger = logging.getLogger(__name__)
        logger.setLevel(logging.INFO)
        handler = logging.handlers.RotatingFileHandler(
            self.logging_file_path,
            maxBytes=self.log_max_size,
            backupCount=1
        )
        formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
        handler.setFormatter(formatter)
        logger.addHandler(handler)
        return logger

    def _init_thermal_sensor(self):
        if adafruit_amg88xx is None:
            self.logger.error("adafruit_amg88xx library not installed.")
            return False
        for attempt in range(3):
            try:
                self.i2c_bus = smbus2.SMBus(1)
                self.thermal_sensor = adafruit_amg88xx.AMG88XX(self.i2c_bus, addr=0x69)
                self.logger.info("AMG88XX thermal sensor initialized successfully.")
                return True
            except Exception as e:
                self.logger.error(f"Failed to initialize thermal sensor (attempt {attempt + 1}/3): {e}")
                if self.i2c_bus:
                    try:
                        self.i2c_bus.close()
                    except Exception:
                        pass
                    self.i2c_bus = None
                if attempt < 2:
                    time.sleep(2)
        self.logger.error("Failed to initialize thermal sensor after 3 attempts.")
        return False

    def _init_camera(self):
        if Picamera2 is None:
            self.logger.warning("picamera2 library not installed. Camera disabled.")
            return False
        try:
            self.camera = Picamera2()
            self.camera.configure(self.camera.create_still_configuration())
            self.camera.start()
            self.logger.info("Camera initialized successfully.")
            return True
        except Exception as e:
            self.logger.warning(f"Failed to initialize camera: {e}. Camera disabled.")
            self.camera = None
            return False

    def _read_thermal_data(self):
        try:
            pixels = self.thermal_sensor.pixels
            return np.array(pixels, dtype=np.float32).reshape((8, 8))
        except Exception as e:
            self.logger.error(f"Error reading thermal data: {e}")
            return None

    def _capture_image(self):
        try:
            if self.camera:
                self.camera.capture_file("image.jpg")
                self.logger.info("Image captured.")
        except Exception as e:
            self.logger.error(f"Error capturing image: {e}")

    def _detect_motion(self, frame):
        global last_frame, last_motion_time
        with self.thermal_lock:
            if frame is None:
                return
            if self.last_frame is None:
                self.last_frame = frame
                return
            diff = np.abs(frame - self.last_frame)
            mean_diff = np.mean(diff)
            if mean_diff > self.motion_detection_threshold and self.enable_camera:
                self.motion_detected = True
                self.last_motion_time = datetime.datetime.now()
                self.logger.info(f"Motion detected! Mean difference: {mean_diff:.2f}")
                self._capture_image()
            else:
                self.motion_detected = False
                self.last_motion_time = None
            self.last_frame = frame

    def _render_heatmap(self, frame):
        try:
            plt.clf()
            plt.imshow(frame, cmap='jet', interpolation='nearest')
            plt.colorbar(label='Temperature (°C)')
            plt.title(f"Thermal Image - {datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
            plt.pause(0.001)
        except Exception as e:
            self.logger.error(f"Error rendering heatmap: {e}")

    def _sensor_loop(self):
        while self.running:
            try:
                frame = self._read_thermal_data()
                if frame is not None:
                    with self.thermal_lock:
                        if self.thermal_frames is None:
                            self.thermal_frames = np.zeros((300, 8, 8), dtype=np.float32)
                        self.thermal_frames = np.roll(self.thermal_frames, -1, axis=0)
                        self.thermal_frames[-1] = frame
                    self._detect_motion(frame)
                    self._render_heatmap(frame)
            except Exception as e:
                self.logger.error(f"Error in sensor loop: {e}")
            time.sleep(1 / self.sampling_rate)

    def _motion_loop(self):
        while self.running:
            try:
                with self.thermal_lock:
                    if self.thermal_frames is not None and len(self.thermal_frames) > 0:
                        if self.motion_detected and (datetime.datetime.now() - self.last_motion_time).total_seconds() > 5:
                            self._capture_image()
                            self.motion_detected = False
                            self.last_motion_time = datetime.datetime.now()
                time.sleep(5)
            except Exception as e:
                self.logger.error(f"Error in motion loop: {e}")
                time.sleep(1)

    def start(self):
        if not self._init_thermal_sensor():
            self.logger.error("Cannot start without thermal sensor. Exiting.")
            return
        if not self._init_camera():
            self.logger.warning("Cannot start without camera. Continuing without camera.")
        self.motion_thread = threading.Thread(target=self._motion_loop, daemon=True)
        self.sensor_thread = threading.Thread(target=self._sensor_loop, daemon=True)
        self.motion_thread.start()
        self.sensor_thread.start()
        self.logger.info("Beehive monitor started.")

    def stop(self):
        self.running = False
        if self.motion_thread:
            self.motion_thread.join(timeout=2)
        if self.sensor_thread:
            self.sensor_thread.join(timeout=2)
        if self.camera:
            try:
                self.camera.stop()
                self.camera.close()
            except Exception:
                pass
        if self.i2c_bus:
            try:
                self.i2c_bus.close()
            except Exception:
                pass
        self.logger.info("Beehive monitor stopped.")

def main():
    monitor = BeehiveMonitor()
    def signal_handler(signum, frame):
        monitor.logger.info(f"Signal {signum} received. Shutting down.")
        monitor.stop()
        sys.exit(0)
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    monitor.start()
    try:
        while monitor.running:
            time.sleep(1)
    except KeyboardInterrupt:
        monitor.stop()

if __name__ == "__main__":
    main()

