    except Exception as e:
        raise RuntimeError(f"Error loading ResNet-50_v2 model: {e}")

    try:
        net.hybridize()
    except Exception as e:
        raise RuntimeError(f"Error hybridizing model: {e}")

    try:
        synset_url = 'http://data.mxnet.io/models/imagenet/synset.txt'
        synset_file = download(synset_url)
        with open(synset_file, 'r') as f:
            synsets = [' '.join(l.split()[1:]) for l in f]
    except Exception as e:
