import io
import logging
import signal
import threading
import time
from typing import Callable, Optional

import cv2
import numpy as np

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class WebSocketHandler:
    """Stub WebSocket handler used by the stream and motion-detection buffers."""

    def has_connections(self) -> bool:
        return True

    def broadcast(self, data: bytes) -> None:
        logger.debug("Broadcasting %d bytes", len(data))


class CameraStreamBuffer:
    """Buffers raw JPEG bytes from picamera2 and broadcasts complete frames via WebSocket."""

    def __init__(self, websocket_handler: WebSocketHandler):
        if not isinstance(websocket_handler, WebSocketHandler):
            raise TypeError("websocket_handler must be a WebSocketHandler instance")
        self._websocket_handler = websocket_handler
        self._buffer = io.BytesIO()
        self._lock = threading.Lock()
        self._last_frame_time = 0.0
        self._running = True

    def write(self, data: bytes) -> int:
        """Called by picamera2 capture_buffer or custom output.

        Detects \xff\xd8 (JPEG SOI) to mark new image boundaries.
        Broadcasts complete frames when a new image starts.
        """
        with self._lock:
            try:
                if data.startswith(b'\xff\xd8'):
                    # Previous frame is complete: broadcast it
                    if self._buffer.tell() > 0:
                        frame_data = self._buffer.getvalue()
                        if frame_data:
                            self._last_frame_time = time.time()
                            self._broadcast_frame(frame_data)
                    # Reset buffer for the new image
                    self._buffer.seek(0)
                    self._buffer.truncate()
                self._buffer.write(data)
            except Exception as e:
                logger.error("Error in CameraStreamBuffer.write: %s", e)
        return len(data)

    def _broadcast_frame(self, frame_data: bytes) -> None:
        if not self._websocket_handler.has_connections():
            logger.debug("No WebSocket connections; dropping frame")
            return
        try:
            self._websocket_handler.broadcast(frame_data)
        except Exception as e:
            logger.error("Error broadcasting frame: %s", e)

    def flush(self) -> None:
        """Emit any remaining bytes in the buffer."""
        with self._lock:
            if self._buffer.tell() > 0:
                frame_data = self._buffer.getvalue()
                if frame_data:
                    self._last_frame_time = time.time()
                    self._broadcast_frame(frame_data)
            self._buffer.close()

    def stop(self) -> None:
        self._running = False


class MotionDetectionBuffer:
    """Buffers raw JPEG bytes and performs motion detection on complete frames."""

    def __init__(self, detect_motion_function: Callable[[np.ndarray, np.ndarray], None],
                 websocket_handler: WebSocketHandler):
        if not callable(detect_motion_function):
            raise TypeError("detect_motion_function must be callable")
        if not isinstance(websocket_handler, WebSocketHandler):
            raise TypeError("websocket_handler must be a WebSocketHandler instance")
        self._detect_motion_function = detect_motion_function
        self._websocket_handler = websocket_handler
        self._buffer = io.BytesIO()
        self._lock = threading.Lock()
        self._last_frame_time = 0.0
        self._running = True
        self.previous_frame: Optional[np.ndarray] = None
        self.current_frame: Optional[np.ndarray] = None

    def write(self, data: bytes) -> int:
        """Called by picamera2 capture_buffer or custom output.

        Detects \xff\xd8 (JPEG SOI) to mark new image boundaries.
        Assembles complete JPEG frames in the internal buffer.
        """
        with self._lock:
            try:
                if data.startswith(b'\xff\xd8'):
                    # New image: finalize previous frame and start fresh
                    if self.previous_frame is not None:
                        self._process_frame()
                    # Reset buffer for the new image
                    self._buffer.seek(0)
                    self._buffer.truncate()
                self._buffer.write(data)
            except Exception as e:
                logger.error("Error in MotionDetectionBuffer.write: %s", e)
        return len(data)

    def _process_frame(self) -> None:
        """Decode a complete JPEG buffer into OpenCV BGR frames."""
        try:
            frame_data = self._buffer.getvalue()
            if not frame_data:
                return
            # Decode with imdecode; it returns None on failure
            self.previous_frame = cv2.imdecode(
                np.frombuffer(frame_data, dtype=np.uint8),
                cv2.IMREAD_COLOR
            )
            if self.previous_frame is None:
                logger.error("Failed to decode previous frame")
                return
            self.current_frame = self.previous_frame.copy()
            if self.previous_frame.shape[0] > 0 and self.previous_frame.shape[1] > 0:
                self._detect_motion_function(self.previous_frame, self.current_frame)
        except Exception as e:
            logger.error("Error processing frame: %s", e)
        finally:
            # Reset buffer for the new image
            self._buffer.seek(0)
            self._buffer.truncate()

    def flush(self) -> None:
        """Emit any remaining bytes in the buffer."""
        with self._lock:
            if self._buffer.tell() > 0:
                frame_data = self._buffer.getvalue()
                if frame_data:
                    self._process_frame()
            self._buffer.close()

    def stop(self) -> None:
        self._running = False


def _default_detect_motion(prev_frame: np.ndarray, curr_frame: np.ndarray) -> None:
    """Placeholder motion-detection function."""
    pass


def _default_websocket_handler() -> WebSocketHandler:
    """Stub WebSocket handler for standalone testing."""
    return WebSocketHandler()


def _default_camera_config() -> dict:
    """Default picamera2 configuration for 640x480 @ 10 fps JPEG."""
    return {
        "size": (640, 480),
        "format": "RGB888",
        "controls": {"FrameRate": 10},
        "output": None,
    }


def run_camera(config: dict, websocket_handler: WebSocketHandler,
               detect_motion_function: Callable[[np.ndarray, np.ndarray], None] = _default_detect_motion):
    """Runs the camera and motion-detection loop until interrupted."""
    if Picamera2 is None:
        logger.error("picamera2 library not installed; cannot run camera")
        return

    buffer = MotionDetectionBuffer(detect_motion_function, websocket_handler)
    stream_buffer = CameraStreamBuffer(websocket_handler)

    def _signal_handler(signum, frame):
        logger.info("Signal %d received; shutting down", signum)
        buffer.stop()
        stream_buffer.stop()

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    picam2 = None
    try:
        picam2 = Picamera2()
        picam2.configure(_default_camera_config())
        picam2.start()
        logger.info("Camera started; entering capture loop")
        while buffer._running:
            frame = picam2.capture_array()
            if frame is None:
                logger.warning("capture_array returned None; retrying")
                time.sleep(0.01)
                continue
            # picamera2 returns RGB; convert to BGR for OpenCV consistency
            bgr_frame = cv2.cvtColor(frame, cv2.COLOR_RGB2BGR)
            # Convert to JPEG bytes for the buffers
            ret, jpeg = cv2.imencode('.jpg', bgr_frame)
            if ret:
                jpeg_bytes = jpeg.tobytes()
                buffer.write(jpeg_bytes)
                stream_buffer.write(jpeg_bytes)
            else:
                logger.error("Failed to encode frame to JPEG")
            time.sleep(1.0 / 10.0)  # 10 fps target
    except Exception as e:
        logger.error("Camera error: %s", e)
    finally:
        if picam2 is not None:
            try:
                picam2.stop()
                logger.info("Camera stopped")
            except Exception as e:
                logger.error("Error stopping camera: %s", e)
        buffer.flush()
        stream_buffer.flush()


if __name__ == "__main__":
    handler = _default_websocket_handler()
    run_camera(_default_camera_config(), handler, _default_detect_motion)

