            # Convert to JPEG bytes for the buffers
            ret, jpeg = cv2.imencode('.jpg', bgr_frame)
            if ret:
                jpeg_bytes = jpeg.tobytes()
                buffer.write(jpeg_bytes)
                stream_buffer.write(jpeg_bytes)
            else:
                logger.error("Failed to encode frame to JPEG")
            time.sleep(1.0 / 10.0)  # 10 fps target
    except Exception as e:
        logger.error("Camera error: %s", e)
    finally:
        if picam2 is not None:
            try:
                picam2.stop()
                logger.info("Camera stopped")
            except Exception as e:
                logger.error("Error stopping camera: %s", e)
        buffer.flush()
        stream_buffer.flush()


if __name__ == "__main__":
    handler = _default_websocket_handler()
    run_camera(_default_camera_config(), handler, _default_detect_motion)

