logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("door")

DOOR_PIN = 18
BUTTON_PIN = 17

_running = True
_door = None
_button = None
_camera = None
_mixer = None


def _signal_handler(signum, frame):
    global _running
    log.info("Signal %s received – shutting down.", signum)
    _running = False


def _cleanup():
    global _door, _button, _camera, _mixer
    log.info("Releasing resources.")
    if _door is not None:
        try:
            _door.close()
        except Exception:
            pass
    if _button is not None:
        try:
            _button.close()
        except Exception:
            pass
    if _camera is not None:
        try:
            _camera.stop()
        except Exception:
            pass
    if _mixer is not None:
        try:
            _mixer.stop()
        except Exception:
            pass


def main():
    global _door, _button, _camera, _mixer

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # --- GPIO setup (gpiozero) ---
    try:
        _door = OutputDevice(DOOR_PIN, active_high=True, initial_value=False)
        _button = Button(BUTTON_PIN, pull_up=True, bounce_time=0.05)
    except Exception as exc:
        log.error("GPIO init failed: %s", exc)
        sys.exit(1)

    # --- Camera setup (picamera2) ---
    try:
        _camera = Picamera2()
        _camera.configure(
            _camera.create_preview_configuration(
                main={"size": (640, 480), "format": "RGB888"}
            )
        )
        _camera.start()
    except Exception as exc:
        log.error("Camera init failed: %s", exc)
        _camera = None

    # --- Sound setup (pygame) ---
    try:
        pygame.mixer.init(frequency=48000, size=-16, channels=1, buffer=1024)
        _mixer = pygame.mixer.Sound(config.WELCOME_SOUND_PATH)
        _wait_sound = pygame.mixer.Sound(config.WAIT_SOUND_PATH)
        _later_sound = pygame.mixer.Sound(config.LATER_SOUND_PATH)
    except Exception as exc:
        log.error("Mixer init failed: %s", exc)
        _mixer = None

    # --- Face model ---
    try:
        log.info("Loading training data…")
        model = cv2.face.EigenFaceRecognizer_create()
        model.read(config.TRAINING_FILE)
    except Exception as exc:
        log.error("Model load failed: %s", exc)
        sys.exit(1)

    log.info("Running – press the button to trigger face recognition.")

    try:
        while _running:
            if _button.is_pressed:
                if _camera is None:
                    log.warning("Camera unavailable – skipping recognition.")
                    time.sleep(0.1)
                    continue

                try:
                    frame = _camera.capture_array()
                except Exception as exc:
                    log.error("Frame capture failed: %s", exc)
                    time.sleep(0.1)
                    continue

                if frame is None or frame.size == 0:
                    log.warning("Empty frame received.")
                    time.sleep(0.1)
                    continue

                try:
                    result = face.recognize(frame, model)
                except Exception as exc:
                    log.error("Face recognition error: %s", exc)
                    time.sleep(0.1)
                    continue

                if result is not None:
                    confidence = result[2]
                    label = result[0]

                    if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
                        log.info("Face recognized – unlocking door.")
                        if _door is not None:
                            _door.on()
                        _mixer.play(_mixer.get_sound(config.WELCOME_SOUND_PATH))
                    else:
                        log.info("Face not recognized (label=%s, conf=%.2f).", label, confidence)
                        if _mixer is not None:
                            _wait_sound.play()
                else:
                    log.info("No face detected – please try again later.")
                    if _mixer is not None:
                        _later_sound.play()

            time.sleep(0.1)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

