import signal
import sys
import threading
import time

import smbus2
from gpiozero import LED, OutputDevice
from gpiozero.exc import GPIOZeroError

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
I2C_BUS = 1
LCD_ADDR = 0x27
LCD_WIDTH = 16
LCD_CHR = 1
LCD_CMD = 0
LCD_LINE_1 = 0x80
LCD_LINE_2 = 0xC0
LCD_BACKLIGHT = 0x08
ENABLE = 0b00000100

LED_PINS = [17, 18, 23, 27, 22]

# ---------------------------------------------------------------------------
# LCD helpers (PCF8574 backpack: P0=RS, P1=RW, P2=E, P3=BL, P4-P7=D4-D7)
# ---------------------------------------------------------------------------
class LCD:
    def __init__(self, bus_num, addr):
        self.addr = addr
        self.bus = None
        self.backlight = False
        try:
            self.bus = smbus2.SMBus(bus_num)
        except OSError as exc:
            raise RuntimeError(f"Cannot open I2C bus {bus_num}: {exc}") from exc

        # Initialise the PCF8574 backlight
        self._write_byte(0x00)
        self._write_byte(LCD_BACKLIGHT)
        self._write_byte(0x00)

    def _write_byte(self, bits):
        if self.bus is None:
            return
        try:
            self.bus.write_byte(self.addr, bits)
        except OSError as exc:
            raise RuntimeError(f"I2C write failed (addr 0x{self.addr:02X}): {exc}") from exc

    def _pulse_enable(self, bits):
        self._write_byte(bits | ENABLE)
        time.sleep(0.0005)
        self._write_byte(bits & ~ENABLE)
        time.sleep(0.0005)

    def lcd_byte(self, bits, mode):
        self._write_byte(mode)
        self._pulse_enable(bits)

    def lcd_string(self, message, line):
        message = message.ljust(LCD_WIDTH, " ")[:LCD_WIDTH]
        self.lcd_byte(line, LCD_CMD)
        for ch in message:
            self.lcd_byte(ord(ch), LCD_CHR)

    def clear(self):
        self.lcd_string(" " * LCD_WIDTH, LCD_LINE_1)
        self.lcd_string(" " * LCD_WIDTH, LCD_LINE_2)

    def backlight(self, on):
        self.backlight = bool(on)
        self._write_byte(LCD_BACKLIGHT if self.backlight else 0x00)

    def close(self):
        if self.bus is not None:
            try:
                self.clear()
                self.backlight(False)
                self.bus.close()
            except Exception:
                pass
            self.bus = None

# ---------------------------------------------------------------------------
# CPU sensor
# ---------------------------------------------------------------------------
class CPUUsageMonitor:
    def __init__(self):
        self.cpu_temp = 0.0
        self.cpu_usage = 0.0
        self.running = False
        self.thread = None

    def read_cpu_data(self):
        try:
            import psutil
            self.cpu_usage = psutil.cpu_percent(interval=None)
            self.cpu_temp = psutil.sensors_temperatures()['cpu_thermal'][0].current
            print(f"CPU Usage: {self.cpu_usage:.1f}%, Temperature: {self.cpu_temp:.1f}°C")
        except Exception as exc:
            print(f"Error reading CPU data: {exc}", file=sys.stderr)

    def run(self, lcd):
        while self.running:
            self.read_cpu_data()
            time.sleep(1)

    def start(self, lcd):
        self.running = True
        self.thread = threading.Thread(target=self.run, args=(lcd,), daemon=True)
        self.thread.start()

    def stop(self):
        self.running = False
        if self.thread is not None:
            self.thread.join(timeout=2)

# ---------------------------------------------------------------------------
# LED controller
# ---------------------------------------------------------------------------
class LEDController:
    def __init__(self, pins):
        self.leds = []
        for p in pins:
            try:
                led = LED(p)
                led.off()
                self.leds.append(led)
            except GPIOZeroError as exc:
                raise RuntimeError(f"Failed to initialise GPIO {p}: {exc}") from exc

    def light_led(self, cls):
        if not 0 <= cls < len(self.leds):
            print(f"Invalid class index {cls}; no LED lit.", file=sys.stderr)
            return
        self.leds[cls].on()
        time.sleep(1)
        self.leds[cls].off()

    def cleanup(self):
        for led in self.leds:
            try:
                led.close()
            except Exception:
                pass

# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main():
    lcd = None
    led_ctrl = None
    cpu_mon = None

    def signal_handler(signum, frame):
        print("\nShutting down...")
        if cpu_mon is not None:
            cpu_mon.stop()
        if led_ctrl is not None:
            led_ctrl.cleanup()
        if lcd is not None:
            lcd.close()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)

    try:
        lcd = LCD(I2C_BUS, LCD_ADDR)
        lcd.clear()
        lcd.backlight(True)

        cpu_mon = CPUUsageMonitor()
        cpu_mon.start(lcd)

        led_ctrl = LEDController(LED_PINS)

        while True:
            cls = int(input("Enter class index (0-4): "))
            led_ctrl.light_led(cls)

    except RuntimeError as exc:
        print(f"Error: {exc}", file=sys.stderr)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        if cpu_mon is not None:
            cpu_mon.stop()
        if led_ctrl is not None:
            led_ctrl.cleanup()
        if lcd is not None:
            lcd.close()

if __name__ == "__main__":
    main()

