import os
import time
import logging
import signal
import contextlib
from PIL import Image, ImageOps

logger = logging.getLogger(__name__)


class Frame:
    """A single frame of an animated GIF, stored as a PIL RGB image."""

    def __init__(self, image, duration=0, loop=0):
        self.image = image
        self.duration = duration
        self.loop = loop


class AnimatedGif:
    """
    Plays an animated GIF on a luma.core-style display.

    Parameters
    ----------
    display : object
        A display object with a display(img) method and width/height attrs.
    width : int
        Display width in pixels. Defaults to display.width.
    height : int
        Display height in pixels. Defaults to display.height.
    folder : str
        Path to the folder containing GIF files.
    """

    def __init__(self, display, width=None, height=None, folder=None):
        if display is None:
            raise ValueError("display must not be None")
        self.display = display
