import board
import busio
import adafruit_character_lcd.character_lcd_i2c as character_lcd
import adafruit_dht

LCD_COLUMNS = 16
LCD_ROWS = 2
LCD_I2C_ADDRESS = 0x27
DHT_PIN = board.D4
UPDATE_INTERVAL_S = 2.0

running = True
lcd = None
dht_sensor = None

def signal_handler(signum, frame):
    global running
    running = False

def init_lcd():
    global lcd
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        lcd = character_lcd.Character_LCD_I2C(i2c, LCD_COLUMNS, LCD_ROWS, address=LCD_I2C_ADDRESS)
        lcd.clear()
        return lcd
    except Exception as e:
        print(f"Error initializing LCD at 0x{LCD_I2C_ADDRESS:02X}: {e}", file=sys.stderr)
        return None

def init_dht():
    global dht_sensor
    try:
        dht_sensor = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
        return dht_sensor
    except Exception as e:
        print(f"Error initializing DHT22 on GPIO4: {e}", file=sys.stderr)
        return None

def read_sensor():
    if dht_sensor is None:
        return None, None
    try:
        temperature = dht_sensor.temperature
        humidity = dht_sensor.humidity
        if temperature is None or humidity is None:
            return None, None
        return temperature, humidity
    except RuntimeError as e:
        # DHT22 checksum or timing errors are common; report and continue
        print(f"DHT22 read error: {e}", file=sys.stderr)
        return None, None
    except Exception as e:
        print(f"Unexpected DHT22 error: {e}", file=sys.stderr)
        return None, None

def update_display(lcd, temperature, humidity):
    if lcd is None:
        return
    try:
        lcd.clear()
        lcd.message = f"Temp: {temperature:.1f} C"
        lcd.message = f"Humidity: {humidity:.1f}%"
    except Exception as e:
        print(f"Error updating LCD: {e}", file=sys.stderr)

def cleanup():
    global lcd
    if lcd is not None:
        try:
            lcd.clear()
        except Exception:
            pass

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    lcd = init_lcd()
    if lcd is None:
        print("LCD initialization failed. Exiting.", file=sys.stderr)
        sys.exit(1)

    dht_sensor = init_dht()
    if dht_sensor is None:
        print("DHT22 initialization failed. Exiting.", file=sys.stderr)
        cleanup()
        sys.exit(1)

    try:
        while running:
            temperature, humidity = read_sensor()
            if temperature is not None and humidity is not None:
                update_display(lcd, temperature, humidity)
            else:
                lcd.message = "Sensor Read Error"
            time.sleep(UPDATE_INTERVAL_S)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        cleanup()

if __name__ == "__main__":
    main()

