import time
import signal
import sys
import smbus2
import gpiozero
from gpiozero import DistanceSensor
from adafruit_vl53l0x import VL53L0X

# --- Configuration ---
WATER_PUMP_PIN = 17
NUTRIENT_PUMP_PIN = 27
TRIGGER_PIN = 23
ECHO_PIN = 24
I2C_BUS = 1
I2C_ADDR = 0x29

LOW_WATER_THRESHOLD = 100   # mm
HIGH_WATER_THRESHOLD = 150   # mm
NUTRIENT_THRESHOLD = 5       # cm
NUTRIENT_DURATION = 5        # seconds

# --- Globals for cleanup ---
water_pump = None
nutrient_pump = None
vl53 = None
bus = None
running = True

def cleanup():
    global water_pump, nutrient_pump, vl53, bus
    print("\nCleaning up resources...")
    if water_pump is not None:
        try:
            water_pump.off()
            water_pump.close()
        except Exception:
            pass
    if nutrient_pump is not None:
        try:
            nutrient_pump.off()
            nutrient_pump.close()
        except Exception:
            pass
    if vl53 is not None:
        try:
            vl53.stop_ranging()
        except Exception:
            pass
    if bus is not None:
        try:
            bus.close()
        except Exception:
            pass
    print("Cleanup complete.")

def signal_handler(sig, frame):
    global running
    print("\nCtrl+C detected. Exiting...")
    running = False

def read_water_level():
    """Read water level from VL53L0X sensor. Returns distance in mm or -1 on error."""
    global vl53
    if vl53 is None:
        return -1
    try:
        distance = vl53.range
        if distance is None or distance < 0:
            print("VL53L0X returned invalid data (None or negative)")
            return -1
        return distance
    except OSError as e:
        print(f"I2C bus error reading VL53L0X: {e}")
        return -1
    except Exception as e:
        print(f"Unexpected error reading VL53L0X: {e}")
        return -1

def read_nutrient_level():
    """Read nutrient level from HC-SR04 via gpiozero DistanceSensor. Returns distance in cm or -1 on error."""
    try:
        sensor = DistanceSensor(echo=ECHO_PIN, trigger=TRIGGER_PIN, max_distance=2.0)
        distance = sensor.distance * 100  # Convert cm to mm
        sensor.close()
        if distance is None or distance < 0:
            print("HC-SR04 returned invalid data (None or negative)")
            return -1
        return distance
    except Exception as e:
        print(f"Error reading HC-SR04: {e}")
        return -1

def control_water_pump(water_level):
    """Control water pump with hysteresis."""
    global water_pump
    if water_level < LOW_WATER_THRESHOLD:
        if water_pump is None or not water_pump.is_active:
            try:
                water_pump.on()
                print("Water pump ON")
            except Exception as e:
                print(f"Error turning water pump ON: {e}")
    elif water_level > HIGH_WATER_THRESHOLD:
        if water_pump is not None and water_pump.is_active:
            try:
                water_pump.off()
                print("Water pump OFF")
            except Exception as e:
                print(f"Error turning water pump OFF: {e}")

def control_nutrient_pump(nutrient_level):
    """Activate nutrient pump for NUTRIENT_DURATION seconds, then deactivate."""
    global nutrient_pump
    if nutrient_level < NUTRIENT_THRESHOLD:
        if nutrient_pump is None or not nutrient_pump.is_active:
            try:
                nutrient_pump.on()
                print("Nutrient pump ON")
                time.sleep(NUTRIENT_DURATION)
                nutrient_pump.off()
                print("Nutrient pump OFF")
            except Exception as e:
                print(f"Error controlling nutrient pump: {e}")
    else:
        if nutrient_pump is not None and nutrient_pump.is_active:
            try:
                nutrient_pump.off()
                print("Nutrient pump OFF (threshold met)")
            except Exception as e:
                print(f"Error turning nutrient pump OFF: {e}")

def main():
    global water_pump, nutrient_pump, vl53, bus, running

    signal.signal(signal.SIGINT, signal_handler)

    # Initialize I2C bus
    try:
        bus = smbus2.SMBus(I2C_BUS)
    except Exception as e:
        print(f"Failed to initialize I2C bus {I2C_BUS}: {e}")
        sys.exit(1)

    # Initialize VL53L0X
    try:
        vl53 = VL53L0X(i2c_bus=bus, i2c_address=I2C_ADDR)
        vl53.start_ranging()
    except Exception as e:
        print(f"Failed to initialize VL53L0X at 0x{I2C_ADDR:02X}: {e}")
        vl53 = None

    # Initialize pumps
    try:
        water_pump = gpiozero.OutputDevice(WATER_PUMP_PIN, active_high=True, initial_value=False)
        nutrient_pump = gpiozero.OutputDevice(NUTRIENT_PUMP_PIN, active_high=True, initial_value=False)
    except Exception as e:
        print(f"Failed to initialize pump GPIOs: {e}")
        cleanup()
        sys.exit(1)

    print("Hydroponics system started. Press Ctrl+C to exit.")

    while running:
        water_level = read_water_level()
        nutrient_level = read_nutrient_level()

        if water_level != -1:
            print(f"Water Level: {water_level} mm")
        else:
            print("Water Level: ERROR")

        if nutrient_level != -1:
            print(f"Nutrient Level: {nutrient_level} cm")
        else:
            print("Nutrient Level: ERROR")

        control_water_pump(water_level)
        control_nutrient_pump(nutrient_level)

        time.sleep(1)

    cleanup()

if __name__ == "__main__":
    main()

