import time
import sys
import board
import adafruit_dht

# DHT11 data pin connected to GPIO4 (BCM) / physical pin 7
DHT_PIN = board.D4
MAX_RETRIES = 5
RETRY_DELAY_S = 2.0


def read_dht11(sensor):
    """Attempt up to MAX_RETRIES reads; return (temperature, humidity) or None."""
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            temperature = sensor.temperature
            humidity = sensor.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
        except RuntimeError as exc:
            # adafruit_dht raises RuntimeError on checksum / timing errors
            print(f"Read attempt {attempt}/{MAX_RETRIES} failed: {exc}", file=sys.stderr)
        except Exception as exc:
            # Unexpected error (e.g., sensor disconnected)
            print(f"Unexpected error on attempt {attempt}/{MAX_RETRIES}: {exc}", file=sys.stderr)

        if attempt < MAX_RETRIES:
            time.sleep(RETRY_DELAY_S)

    return None


def main():
    sensor = None
    try:
        sensor = adafruit_dht.DHT11(DHT_PIN, use_pulseio=False)
    except Exception as exc:
        print(f"Failed to initialize DHT11 on GPIO4: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        result = read_dht11(sensor)
        if result is None:
            print("Error: Could not read from DHT11 sensor after multiple attempts.", file=sys.stderr)
            sys.exit(1)

        temperature, humidity = result
        print(f"Temperature: {temperature:.1f} C")

    except KeyboardInterrupt:
        print("\nInterrupted by user.", file=sys.stderr)
        sys.exit(130)

    finally:
        if sensor is not None:
            try:
                sensor.exit()
            except Exception:
                pass


if __name__ == "__main__":
    main()

