import asyncio
import json
import logging
import logging.handlers
import os
import signal
import sys
import time

import RPi.GPIO as GPIO
import board
import adafruit_dht

CONFIG_FILE = "greenhouse_config.json"
DEFAULT_CONFIG = {
    "gpio_transmitter_pin": 17,
    "gpio_dht22_pin": 4,
    "dht22_read_interval": 60,
    "log_file": "greenhouse.log",
    "outlet_configurations": [
        {"system_code": "10101", "unit_codes": ["1"], "relay_pins": [17], "description": "Ventilation Fan"},
        {"system_code": "10101", "unit_codes": ["2"], "relay_pins": [17], "description": "Heater"},
        {"system_code": "10101", "unit_codes": ["3"], "relay_pins": [17], "description": "Cooling Fan"}
    ]
}

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

shutdown_event = asyncio.Event()


def load_config(config_file):
    try:
        with open(config_file, 'r') as f:
            config = json.load(f)
        if not isinstance(config, dict):
            raise ValueError("Config root must be a JSON object")
        required_keys = ["gpio_transmitter_pin", "gpio_dht22_pin", "dht22_read_interval", "log_file", "outlet_configurations"]
        for key in required_keys:
            if key not in config:
                raise KeyError(f"Missing required config key: {key}")
        if not isinstance(config["outlet_configurations"], list):
            raise ValueError("outlet_configurations must be a JSON array")
        for item in config["outlet_configurations"]:
            if not isinstance(item, dict):
                raise ValueError("Each outlet config must be a JSON object")
            required_keys = ["system_code", "unit_codes", "relay_pins", "description"]
            for k in required_keys:
                if k not in item:
                    raise KeyError(f"Missing required outlet key: {k}")
            if not isinstance(item["system_code"], str) or not item["system_code"]:
                raise ValueError("system_code must be a non-empty string")
            if not isinstance(item["unit_codes"], list) or not item["unit_codes"]:
                raise ValueError("unit_codes must be a non-empty list of strings")
            if not isinstance(item["relay_pins"], list) or not item["relay_pins"]:
                raise ValueError("relay_pins must be a non-empty list of integers")
            if not isinstance(item["description"], str) or not item["description"].strip():
                raise ValueError("description must be a non-empty string")
        return config
    except FileNotFoundError:
        logger.warning(f"Config file not found: {config_file}. Using default configuration.")
        return DEFAULT_CONFIG
    except (json.JSONDecodeError, KeyError, ValueError) as e:
        logger.error(f"Invalid configuration file: {e}. Using default configuration.")
        return DEFAULT_CONFIG
    except OSError as e:
        logger.error(f"OS error reading config file: {e}. Using default configuration.")
        return DEFAULT_CONFIG


def setup_logging(log_file):
    handler = logging.handlers.RotatingFileHandler(
        log_file, maxBytes=1024 * 1024, backupCount=5
    )
    formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
    handler.setFormatter(formatter)
    logger.addHandler(handler)
    logger.info("Logging initialized.")


def read_dht22_sensor(dht_device):
    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is None or humidity is None:
            logger.warning("DHT22 returned None values.")
            return None, None
        logger.info(f"Temperature: {temperature:.2f}C, Humidity: {humidity:.2f}%")
        return temperature, humidity
    except RuntimeError as e:
        logger.warning(f"DHT22 read error (sensor absent or bus error): {e}")
        return None, None
    except OSError as e:
        logger.error(f"DHT22 OS error: {e}")
        return None, None


def transmit_code(system_code, unit_code, state, transmitter_pin, retries=3):
    if not isinstance(system_code, str) or not system_code:
        logger.error("Invalid system_code.")
        return False
    if not isinstance(unit_code, str) or not unit_code:
        logger.error("Invalid unit_code.")
        return False
    if state not in (0, 1):
        logger.error("Invalid state. Must be 0 (off) or 1 (on).")
        return False
    if not isinstance(transmitter_pin, int) or transmitter_pin < 0:
        logger.error("Invalid transmitter_pin.")
        return False

    config = load_config(CONFIG_FILE)
    outlet_configs = config["outlet_configurations"]
    for item in outlet_configs:
        if item["system_code"] != system_code or item["unit_codes"][0] != unit_code:
            continue
        pins = item["relay_pins"]
        if transmitter_pin not in pins:
            logger.error(f"Transmitter pin {transmitter_pin} not in relay pins {pins}.")
            return False

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(transmitter_pin, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        logger.error(f"GPIO setup error on pin {transmitter_pin}: {e}")
        return False

    sync_pulse = [1, 0, 1, 0]
    code = [1, 0]
    for bit in system_code:
        code.append(int(bit))
    for bit in unit_code:
        code.append(int(bit))
    code.append(state)

    for _ in range(retries):
        for pulse in code:
            try:
                GPIO.output(transmitter_pin, GPIO.HIGH)
                time.sleep(0.0003)
                GPIO.output(transmitter_pin, GPIO.LOW)
                time.sleep(0.0003)
            except Exception as e:
                logger.error(f"GPIO output error: {e}")
                return False
        for pulse in sync_pulse:
            try:
                GPIO.output(transmitter_pin, GPIO.HIGH)
                time.sleep(0.0003)
                GPIO.output(transmitter_pin, GPIO.LOW)
                time.sleep(0.0003)
            except Exception as e:
                logger.error(f"GPIO output error: {e}")
                return False
        time.sleep(0.01)
        if shutdown_event.is_set():
            return False
    return True


def control_outlet(system_code, unit_code, state, transmitter_pin):
    if state == 1:
        new_state = 0
    else:
        new_state = 1
    if transmit_code(system_code, unit_code, new_state, transmitter_pin):
        logger.info(f"Outlet {unit_code} turned {'ON' if new_state else 'OFF'}.")
        return True
    else:
        logger.error(f"Failed to control outlet {unit_code}.")
        return False


def get_outlet_status(system_code, unit_code, transmitter_pin):
    if transmit_code(system_code, unit_code, 1, transmitter_pin):
        logger.info(f"Outlet {unit_code} is {'ON' if 1 else 'OFF'}.")
        return True
    else:
        logger.error(f"Failed to get status of outlet {unit_code}.")
        return False


def signal_handler(sig, frame):
    logger.info("Shutdown signal received. Cleaning up...")
    shutdown_event.set()


async def sensor_reading_loop(dht_device, interval):
    while not shutdown_event.is_set():
        temperature, humidity = read_dht22_sensor(dht_device)
        if temperature is not None and humidity is not None:
            logger.info(f"Temperature: {temperature:.2f}C, Humidity: {humidity:.2f}%")
        else:
            logger.warning("Failed to read DHT22 sensor.")
        try:
            await asyncio.wait_for(shutdown_event.wait(), timeout=interval)
        except asyncio.TimeoutError:
            pass


async def main():
    config = load_config(CONFIG_FILE)
    setup_logging(config["log_file"])

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    dht_pin = config["gpio_dht22_pin"]
    dht_device = None
    try:
        dht_device = adafruit_dht.DHT22(board.D4)
        logger.info(f"DHT22 initialized on BCM pin {dht_pin}.")
    except Exception as e:
        logger.error(f"Failed to initialize DHT22: {e}")

    transmitter_pin = config["gpio_transmitter_pin"]
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(transmitter_pin, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        logger.error(f"GPIO setup error on pin {transmitter_pin}: {e}")

    try:
        await sensor_reading_loop(dht_device, config["dht22_read_interval"])
    except asyncio.CancelledError:
        pass
    finally:
        if dht_device:
            try:
                dht_device.exit()
            except Exception:
                pass
        GPIO.cleanup()
        logger.info("GPIO cleanup complete.")


if __name__ == "__main__":
    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        pass

