import time
import signal
import sys
import logging
import smbus2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

DHT20_I2C_ADDR = 0x38
DHT20_CMD_REG = 0xAC
DHT20_STATUS_REG = 0x71
MEASURE_CMD = [0x33, 0x00]
CRC_POLY = 0x31
MEASURE_TIMEOUT = 0.1
POLL_INTERVAL = 0.01


class DHT20:
    def __init__(self, bus_num=1, addr=DHT20_I2C_ADDR):
        self.bus_num = bus_num
        self.addr = addr
        self.bus = None
        self.crc_error = False
        self._running = True
        try:
            self.bus = smbus2.SMBus(bus_num)
        except OSError as e:
            logger.error(f"Failed to open I2C bus {bus_num}: {e}")
            self.bus = None
            return
        try:
            status = self._read_u8(DHT20_STATUS_REG)
            if status != 0x00:
                logger.error(f"DHT20 not detected at 0x{addr:02X} on bus {bus_num} (status=0x{status:02X})")
                self.bus.close()
                self.bus = None
                return
        except OSError as e:
            logger.error(f"I/O error reading DHT20 status: {e}")
            self.bus.close()
            self.bus = None
            return
        logger.info(f"DHT20 initialized at 0x{addr:02X} on bus {bus_num}")

    def _read_u8(self, reg):
        try:
            return self.bus.read_byte_data(self.addr, reg)
        except OSError as e:
            logger.error(f"I/O error reading register 0x{reg:02X}: {e}")
            raise

    def _read_bytes(self, reg, length):
        try:
            return self.bus.read_i2c_block_data(self.addr, reg, length)
        except OSError as e:
            logger.error(f"I/O error reading {length} bytes from register 0x{reg:02X}: {e}")
            raise

    def measure(self):
        if self.bus is None:
            return None, None, True
        try:
            self.bus.write_i2c_block_data(self.addr, DHT20_CMD_REG, MEASURE_CMD)
            deadline = time.monotonic() + MEASURE_TIMEOUT
            while True:
                status = self._read_u8(DHT20_STATUS_REG)
                if status & 0x80 == 0:
