import logging
import sqlite3
import time
import random
import signal
import sys
import gpiod

# Constants and configuration
MOTOR_FORWARD_PIN = 17
MOTOR_BACKWARD_PIN = 18
MOTOR_ENABLE_PIN = 27
CONFIG_FILE = "config.txt"
LOG_FILE = "greenhouse_vent.log"
DATABASE_FILE = "greenhouse_data.db"

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    global running
    running = False

def setup_logging():
    logging.basicConfig(
        filename=LOG_FILE,
        level=logging.DEBUG,
        format='%(asctime)s - %(levelname)s - %(message)s',
        datefmt='%Y-%m-%d %H:%M:%S'
    )

def read_config():
    config = {}
    try:
        with open(CONFIG_FILE, "r") as f:
            for line in f:
                line = line.strip()
                if line and "=" in line:
                    key, value = line.split("=", 1)
                    config[key.strip()] = value.strip()
    except FileNotFoundError:
        logging.warning(f"Config file {CONFIG_FILE} not found. Using defaults.")
    except Exception as e:
        logging.error(f"Error reading config file: {e}. Using defaults.")

    defaults = {"TEMP_MIN": "25.0", "TEMP_MAX": "30.0"}
    for key, value in defaults.items():
        if key not in config:
            config[key] = value
    return config

def get_temperature():
    return random.uniform(20.0, 35.0)

def calculate_vent_position(temperature, config):
    temp_min = float(config["TEMP_MIN"])
    temp_max = float(config["TEMP_MAX"])
    if temperature <= temp_min:
        return 0.0
    elif temperature >= temp_max:
        return 100.0
    else:
        return ((temperature - temp_min) / (temp_max - temp_min)) * 100.0

def log_data(timestamp, temperature, vent_position):
    try:
        conn = sqlite3.connect(DATABASE_FILE)
        cursor = conn.cursor()
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS greenhouse_data (
                timestamp TEXT,
                temperature REAL,
                vent_position REAL
            )
        """)
        cursor.execute(
            "INSERT INTO greenhouse_data (timestamp, temperature, vent_position) VALUES (?, ?, ?)",
            (timestamp, temperature, vent_position)
        )
        conn.commit()
        conn.close()
    except sqlite3.Error as e:
        logging.error(f"Database error: {e}")

def control_motor(temperature, vent_position, config):
    temp_min = float(config["TEMP_MIN"])
    temp_max = float(config["TEMP_MAX"])
    target_position = calculate_vent_position(temperature, config)

    if temperature < temp_min:
        logging.info("Temperature below minimum. Opening vent fully.")
        return 100.0
    elif temperature > temp_max:
        logging.info("Temperature above maximum. Closing vent fully.")
        return 0.0
    elif abs(vent_position - target_position) > 1.0:
        logging.info(f"Temperature changed. Moving vent to {target_position:.1f}%.")
        return target_position
    else:
        logging.info("Temperature within range. Vent position unchanged.")
        return vent_position

def main():
    global running
    setup_logging()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = read_config()
    logging.info("Greenhouse vent controller started.")

    chip = None
    try:
        chip = gpiod.Chip('gpiochip0')
        line = chip.get_line(MOTOR_ENABLE_PIN)
        line.request(consumer='greenhouse_vent', type=gpiod.LINE_REQ_DIR_OUT)
        line.set_value(0)

        while running:
            temperature = get_temperature()
            if not (0 <= temperature <= 50):
                logging.error(f"Invalid temperature reading: {temperature}. Skipping.")
                time.sleep(60)
                continue

            vent_position = control_motor(temperature, 0.0, config)
            log_data(time.strftime("%Y-%m-%d %H:%M:%S"), temperature, vent_position)

            logging.debug(f"Temperature: {temperature:.2f}°C, Vent Position: {vent_position:.1f}%")

            time.sleep(60)

    except gpiod.error as e:
        logging.error(f"GPIO error: {e}")
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        if chip is not None:
            try:
                chip.get_line(MOTOR_ENABLE_PIN).set_value(0)
                chip.close()
            except Exception:
                pass
        logging.info("Greenhouse vent controller stopped.")

if __name__ == "__main__":
    main()

