import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Initialize I2C bus on board.SCL (GPIO3) and board.SDA (GPIO2)
try:
    i2c_bus = busio.I2C(board.SCL, board.SDA)
except Exception as e:
    print(f"Fatal: Failed to initialize I2C bus: {e}")
    raise SystemExit(1)

# Initialize TCA9548A I2C multiplexer at address 0x70
try:
    i2c_mux = adafruit_tca9548a.TCA9548A(i2c_bus, address=0x70)
except Exception as e:
    print(f"Fatal: Failed to initialize TCA9548A multiplexer at 0x70: {e}")
    raise SystemExit(1)

# Initialize BME280 sensor on multiplexer channel 0 (default 0x76)
bme280_sensor = None
try:
    bme280_sensor = adafruit_bme280.Adafruit_BME280_I2C(i2c_mux[0], address=0x76)
except Exception as e:
    print(f"Warning: BME280 sensor not found on channel 0 (0x76): {e}")

# Initialize TSL2591 sensor on multiplexer channel 1 (default 0x29)
tsl2591_sensor = None
try:
    tsl2591_sensor = adafruit_tsl2591.TSL2591(i2c_mux[1], address=0x29)
except Exception as e:
    print(f"Warning: TSL2591 sensor not found on channel 1 (0x29): {e}")

# Main loop to read and display sensor data
try:
    while True:
        # Read BME280 sensor data
        if bme280_sensor is not None:
            try:
                temperature = bme280_sensor.temperature
                humidity = bme280_sensor.humidity
                print(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %")
            except (OSError, ValueError) as e:
                print(f"Error reading BME280 sensor: {e}")
        else:
            print("BME280 sensor not initialized.")

        # Read TSL2591 sensor data
        if tsl2591_sensor is not None:
            try:
                light_intensity = tsl2591_sensor.lux
                print(f"Light Intensity: {light_intensity:.2f} lux")
            except (OSError, ValueError) as e:
                print(f"Error reading TSL2591 sensor: {e}")
        else:
            print("TSL2591 sensor not initialized.")

        # Wait for 2 seconds
        time.sleep(2)

except KeyboardInterrupt:
    print("\nExiting gracefully...")

