DHT_SAMPLE_DELAY = 2.0  # seconds (DHT11 max ~1 Hz, 4 ms transaction)

# --- Globals for cleanup -----------------------------------------------------
dht_device = None
red_pwm = None
green_pwm = None
blue_pwm = None
running = True

def cleanup():
    """Stop PWM and release GPIO resources."""
    global dht_device, red_pwm, green_pwm, blue_pwm
    try:
        if red_pwm is not None:
            red_pwm.stop()
    except Exception:
        pass
    try:
        if green_pwm is not None:
            green_pwm.stop()
    except Exception:
        pass
    try:
        if blue_pwm is not None:
            blue_pwm.stop()
    except Exception:
        pass
    try:
        GPIO.cleanup()
    except Exception:
        pass

def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    running = False

def set_color(r, g, b):
    """Set RGB LED duty cycles (100 = full on, 0 = off)."""
    if red_pwm is not None:
        red_pwm.ChangeDutyCycle(r)
    if green_pwm is not None:
        green_pwm.ChangeDutyCycle(g)
    if blue_pwm is not None:
        blue_pwm.ChangeDutyCycle(b)

def read_temperature():
    """Read temperature from DHT11 with retry logic.
    Returns float temperature in °C, or None on failure."""
    global dht_device
    if dht_device is None:
        try:
            dht_device = adafruit_dht.DHT11(DHT_PIN, use_pulseio=False)
        except Exception as e:
            print(f"Failed to initialize DHT11: {e}")
            return None

    for attempt in range(3):
        try:
            temp = dht_device.temperature
            if temp is not None:
                return float(temp)
        except RuntimeError as e:
            # DHT11 often throws transient read errors; retry
            print(f"DHT11 read attempt {attempt+1} failed: {e}")
        except Exception as e:
            print(f"Unexpected DHT11 error: {e}")
            break
        time.sleep(DHT_SAMPLE_DELAY)
    return None

def main():
    global dht_device, red_pwm, green_pwm, blue_pwm

    # --- GPIO setup ----------------------------------------------------------
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    for pin in (RED_PIN, GREEN_PIN, BLUE_PIN):
        GPIO.setup(pin, GPIO.OUT)
        GPIO.output(pin, GPIO.LOW)
    red_pwm = GPIO.PWM(RED_PIN, PWM_FREQ)
    green_pwm = GPIO.PWM(GREEN_PIN, PWM_FREQ)
    blue_pwm = GPIO.PWM(BLUE_PIN, PWM_FREQ)
    red_pwm.start(0)
    green_pwm.start(0)
    blue_pwm.start(0)

    # --- Signal handlers ------------------------------------------------------
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    last_temp = None
    last_color = None

    try:
        while running:
            temp = read_temperature()
            if temp is not None:
                if temp < 20.0:
                    color = (0, 0, 100)   # Blue
                elif 20.0 <= temp <= 25.0:
                    color = (0, 100, 0)   # Green
                else:                     # temp > 25.0
                    color = (100, 0, 0)   # Red
                if color != last_color:
                    set_color(*color)
                    last_color = color
                print(f"Temp: {temp:.1f}°C  ->  RGB: {color}")
            else:
                print("Temperature read failed; keeping last color.")
            time.sleep(1.0)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()
        print("GPIO cleanup complete.")

if __name__ == "__main__":
    main()

