    print(f"Failed to initialize I2C bus: {e}")
    raise SystemExit(1)

# Initialize TCA9548A I2C multiplexer at default address 0x70
try:
    i2c_mux = adafruit_tca9548a.TCA9548A(i2c_bus, address=0x70)
except Exception as e:
    print(f"Failed to initialize TCA9548A multiplexer: {e}")
    raise SystemExit(1)

# Initialize BME280 sensor on multiplexer channel 0 (default 0x76 or 0x77)
try:
    bme280_sensor = adafruit_bme280.Adafruit_BME280_I2C(i2c_mux[0], address=0x76)
except Exception as e:
    print(f"Failed to initialize BME280 sensor: {e}")
    raise SystemExit(1)

# Initialize TSL2591 sensor on multiplexer channel 1 (default 0x29)
try:
    tsl2591_sensor = adafruit_tsl2591.TSL2591(i2c_mux[1])
except Exception as e:
    print(f"Failed to initialize TSL2591 sensor: {e}")
    raise SystemExit(1)

# Main loop to read and display sensor data
try:
    while True:
        # Read temperature and humidity from BME280
        try:
            temperature = bme280_sensor.temperature
            humidity = bme280_sensor.humidity
            print(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %")
        except Exception as e:
