import time
import signal
import sys
from gpiozero import PWMOutputDevice

FAN_PIN = 18
PWM_FREQ = 50.0
TEMP_MIN = 40.0
TEMP_MAX = 50.0
TEMP_FILE = "/sys/class/thermal/thermal_zone0/temp"
POLL_INTERVAL = 1.0

fan = None
running = True

def cleanup(signum=None, frame=None):
    global running
    running = False
    if fan is not None:
        try:
            fan.value = 0.0
            fan.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)

def read_cpu_temp():
    try:
        with open(TEMP_FILE, "r") as f:
            return float(f.read().strip()) / 1000.0
    except (IOError, OSError, ValueError) as e:
        print(f"Error reading CPU temperature: {e}", file=sys.stderr)
        return None

def compute_duty(temp):
    if temp <= TEMP_MIN:
        return 0.0
    if temp >= TEMP_MAX:
        return 100.0
    return (100.0 / (TEMP_MAX - TEMP_MIN)) * (temp - TEMP_MIN)

def main():
    global fan
    signal.signal(signal.SIGTERM, cleanup)
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0.0)
    except Exception as e:
        print(f"Failed to initialize PWM on GPIO{FAN_PIN}: {e}", file=sys.stderr)
        sys.exit(1)
    try:
        while running:
            temp = read_cpu_temp()
            if temp is not None:
                duty = compute_duty(temp)
                fan.value = duty / 100.0
                print(f"CPU Temp: {temp:.1f}C, Fan Duty: {duty:.1f}%")
            time.sleep(POLL_INTERVAL)
    except KeyboardInterrupt:
        pass
    finally:
        cleanup()

if __name__ == "__main__":
    main()

