import time
import datetime
import json
import logging
import random
import signal
import sys
import urllib.request
import urllib.error

try:
    import board
    import adafruit_dht
except ImportError:
    board = None
    adafruit_dht = None

DEFAULT_CONFIG = {
    "dht_pin": 4,
    "webhook_url": "https://example.com/webhook",
    "temperature_threshold": 30,
    "humidity_threshold": 80,
    "moving_average_window": 5,
    "actuator_vent_fan": "vent_fan",
    "actuator_water_pump": "water_pump",
    "actuator_heater": "heater",
    "log_file": "greenhouse.log",
    "log_level": "INFO",
    "max_retries": 3,
    "retry_delay": 1,
}

config = DEFAULT_CONFIG.copy()
running = True
sensor = None

logging.basicConfig(
    filename=config["log_file"],
    level=getattr(logging, config.get("log_level", "INFO").upper(), logging.INFO),
    format="%(asctime)s - %(levelname)s - %(message)s",
)

def load_config(path="config.json"):
    global config
    try:
        with open(path, "r") as f:
            user_config = json.load(f)
        config.update(user_config)
        logging.info(f"Configuration loaded from {path}")
    except FileNotFoundError:
        logging.warning(f"Config file {path} not found; using defaults.")
    except json.JSONDecodeError as e:
        logging.error(f"Invalid JSON in {path}: {e}; using defaults.")
    except Exception as e:
        logging.error(f"Error loading config: {e}; using defaults.")

def read_dht22():
    global sensor
    if sensor is None:
        return None, None
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        if temperature is None or humidity is None:
            return None, None
        return temperature, humidity
    except RuntimeError as e:
        logging.error(f"DHT22 read error: {e}")
        return None, None
    except Exception as e:
        logging.error(f"Unexpected DHT22 error: {e}")
        return None, None

def simulate_sensor_data():
    temperature = random.uniform(20, 30) + random.uniform(-0.5, 0.5)
    humidity = random.uniform(60, 80) + random.uniform(-2, 2)
    return temperature, humidity

def validate_data(temperature, humidity):
    if not -40 <= temperature <= 80:
        logging.warning(f"Invalid temperature: {temperature}")
        return False
    if not 0 <= humidity <= 100:
        logging.warning(f"Invalid humidity: {humidity}")
        return False
    return True

def moving_average(data, window_size):
    if not data:
        return None
    if len(data) < window_size:
        return sum(data) / len(data)
    return sum(data[-window_size:]) / window_size

def send_webhook(temperature, humidity, url):
    payload = json.dumps({"temperature": temperature, "humidity": humidity}).encode("utf-8")
    headers = {"Content-Type": "application/json"}
    for attempt in range(1, config["max_retries"] + 1):
        try:
            req = urllib.request.Request(url, data=payload, headers=headers, method="POST")
            with urllib.request.urlopen(req, timeout=10) as resp:
                if 200 <= resp.status < 300:
                    logging.info(f"Webhook sent successfully (attempt {attempt}).")
                    return True
                else:
                    logging.error(f"Webhook failed with status {resp.status} (attempt {attempt}).")
        except urllib.error.URLError as e:
            logging.error(f"Webhook network error (attempt {attempt}): {e}")
        except Exception as e:
            logging.error(f"Webhook error (attempt {attempt}): {e}")
        if attempt < config["max_retries"]:
            time.sleep(config["retry_delay"] * (2 ** (attempt - 1)))
    logging.error(f"Webhook failed after {config['max_retries']} attempts.")
    return False

def control_actuators(temperature, humidity):
    if temperature > config["temperature_threshold"]:
        logging.info("Activating vent_fan")
        print("Activating vent_fan")
    if humidity < config["humidity_threshold"]:
        logging.info("Activating water_pump")
        print("Activating water_pump")
    if temperature < 15:
        logging.info("Activating heater")
        print("Activating heater")
    if temperature <= config["temperature_threshold"]:
        logging.info("Deactivating vent_fan")
        print("Deactivating vent_fan")
    if humidity >= config["humidity_threshold"]:
        logging.info("Deactivating water_pump")
        print("Deactivating water_pump")
    if temperature >= 15:
        logging.info("Deactivating heater")
        print("Deactivating heater")

def signal_handler(signum, frame):
    global running
    logging.info(f"Signal {signum} received; shutting down.")
    running = False

def cleanup():
    global sensor
    if sensor is not None:
        try:
            sensor.exit()
        except Exception:
            pass
        sensor = None
    logging.info("Cleanup complete.")

def main():
    global sensor, running
    load_config()
    logging.info("Greenhouse monitoring system starting.")
    print("Greenhouse monitoring system starting.")
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        if adafruit_dht is not None and board is not None:
            pin = getattr(board, f"D{config['dht_pin']}")
            sensor = adafruit_dht.DHT22(pin, use_pulseio=False)
            logging.info(f"DHT22 initialized on GPIO{config['dht_pin']}.")
            print(f"DHT22 initialized on GPIO{config['dht_pin']}.")
        else:
            logging.warning("adafruit-circuitpython-dht or board not available; using simulation.")
            print("adafruit-circuitpython-dht or board not available; using simulation.")
    except Exception as e:
        logging.error(f"Failed to initialize DHT22: {e}")
        print(f"Failed to initialize DHT22: {e}")
    temperature_readings = []
    humidity_readings = []
    failure_count = 0
    last_log_time = time.time()
    while running:
        try:
            if sensor is not None:
                temperature, humidity = read_dht22()
            else:
                temperature, humidity = simulate_sensor_data()
            if not validate_data(temperature, humidity):
                temperature_readings.append(None)
                humidity_readings.append(None)
                failure_count += 1
                logging.warning(f"Invalid data: temp={temperature}, hum={humidity}.")
                print(f"Invalid data: temp={temperature}, hum={humidity}.")
            else:
                temperature_readings.append(temperature)
                humidity_readings.append(humidity)
                failure_count = 0
                logging.info(f"Valid data: temp={temperature:.2f}C, hum={humidity:.2f}%")
                print(f"Valid data: temp={temperature:.2f}C, hum={humidity:.2f}%")
            if len(temperature_readings) > config["moving_average_window"]:
                temperature_readings.pop(0)
                humidity_readings.pop(0)
            avg_temperature = moving_average(temperature_readings, config["moving_average_window"])
            avg_humidity = moving_average(humidity_readings, config["moving_average_window"])
            if avg_temperature is not None and avg_humidity is not None:
                if avg_temperature > config["temperature_threshold"] or avg_humidity > config["humidity_threshold"]:
                    logging.info(f"Threshold exceeded: temp={avg_temperature:.2f}C, hum={avg_humidity:.2f}%")
                    print(f"Threshold exceeded: temp={avg_temperature:.2f}C, hum={avg_humidity:.2f}%")
                    send_webhook(avg_temperature, avg_humidity, config["webhook_url"])
                    control_actuators(avg_temperature, avg_humidity)
            if time.time() - last_log_time >= 300:
                logging.info(f"Failure count: {failure_count}")
                print(f"Failure count: {failure_count}")
                if failure_count >= 3:
                    logging.info("Pausing data acquisition for 300 seconds.")
                    print("Pausing data acquisition for 300 seconds.")
                    time.sleep(300)
                    failure_count = 0
                    logging.info("Resuming data acquisition.")
                    print("Resuming data acquisition.")
            time.sleep(60)
        except Exception as e:
            logging.error(f"Unexpected error in main loop: {e}")
            print(f"Unexpected error in main loop: {e}")
            time.sleep(60)
    cleanup()

if __name__ == "__main__":
    main()

