import time
import json
import datetime
import threading

import gpiozero
from gpiozero import PWMLED

try:
    import adafruit_dht
    import board
    DHT_AVAILABLE = True
except Exception:
    DHT_AVAILABLE = False

LED_PIN = 17
PWM_FREQUENCY = 100
SUNRISE_DURATION = 600
DAYTIME_HOLD = 10
SUNSET_DURATION = 600
DHT_PIN = 4
DHT_RETRIES = 3
DHT_RETRY_DELAY = 5

running = True
override_brightness = 0
manual_override = False
override_lock = threading.Lock()

led = None
dht_device = None

def log_message(message):
    print(message)

def log_dht_data(temperature, humidity):
    if temperature is None or humidity is None:
        log_message(json.dumps({"timestamp": datetime.datetime.now().isoformat(), "led_brightness": override_brightness, "temperature": None, "humidity": None}))
    else:
        log_message(json.dumps({"timestamp": datetime.datetime.now().isoformat(), "led_brightness": override_brightness, "temperature": temperature, "humidity": humidity}))

def read_dht22():
    global dht_device
    if not DHT_AVAILABLE:
        log_message("DHT22 library not available; skipping sensor read.")
        return None, None
    if dht_device is None:
        try:
            dht_device = adafruit_dht.DHT22(board.D4)
        except Exception as e:
            log_message(f"Failed to initialize DHT22 on GPIO4: {e}")
            return None, None
    for attempt in range(DHT_RETRIES):
        try:
            temperature = dht_device.temperature
            humidity = dht_device.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
        except RuntimeError as e:
            log_message(f"DHT22 read attempt {attempt + 1} failed: {e}")
        except Exception as e:
            log_message(f"DHT22 unexpected error on attempt {attempt + 1}: {e}")
        if attempt < DHT_RETRIES - 1:
            time.sleep(DHT_RETRY_DELAY)
    log_message("DHT22 read failed after all retries.")
    return None, None

def sunrise_sunset_cycle(brightness_min, brightness_max, hold_time):
    global override_brightness, manual_override
    with override_lock:
        manual_override = False
    while running:
        with override_lock:
            brightness_min = max(0, brightness_min)
            brightness_max = min(90, brightness_max)
        if not running:
            break
        led.value = 0
        time.sleep(0.1)
        led.value = 1
        time.sleep(0.1)
        for brightness in range(0, brightness_max + 1, int((brightness_max - brightness_min) / 10)):
            if not running:
                break
            led.value = brightness / 10.0
            time.sleep(10)
        if not running:
            break
        for brightness in range(brightness_max, brightness_min - 1, -1):
            if not running:
                break
            led.value = brightness / 10.0
            time.sleep(10)
        if not running:
            break
        with override_lock:
            manual_override = False
        time.sleep(hold_time)

def handle_manual_override(input_value):
    global override_brightness, manual_override
    with override_lock:
        manual_override = True
        if input_value.strip().lower() == "auto":
            manual_override = False
        elif input_value.strip().lower() == "exit":
            running = False
        elif input_value.isdigit():
            override_brightness = int(input_value)
            with override_lock:
                manual_override = False

def signal_handler(signum, frame):
    global running
    running = False

def cleanup():
    global led, dht_device
    if led is not None:
        try:
            led.value = 0
            led.close()
        except Exception:
            pass
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass
    log_message("Program terminated.")

def main():
    global led, running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        led = PWMLED(LED_PIN, frequency=PWM_FREQUENCY, initial_value=0)
    except Exception as e:
        log_message(f"Failed to initialize PWMLED on GPIO{LED_PIN}: {e}")
        sys.exit(1)
    sunrise_sunset_cycle(0, 90, DAYTIME_HOLD)
    while running:
        temperature, humidity = read_dht22()
        log_dht_data(temperature, humidity)
        try:
            input_value = input("Enter brightness (0-90), 'auto', or 'exit': ")
            handle_manual_override(input_value)
        except EOFError:
            break
        except KeyboardInterrupt:
            break
        time.sleep(1)
    cleanup()

if __name__ == "__main__":
    main()

