import time
import signal
import sys
import board
import busio
import adafruit_bme680

LOG_FILE = 'air_quality_log.txt'
SLEEP_INTERVAL = 10
BME680_I2C_ADDR = 0x77

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_i2c():
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        while not i2c.try_lock():
            pass
        devices = i2c.scan()
        i2c.unlock()
        if BME680_I2C_ADDR not in devices:
            print(f"Error: BME680 not found at I2C address 0x{BME680_I2C_ADDR:02X}. Detected devices: {[hex(d) for d in devices]}")
            return None
        return i2c
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None

def initialize_sensor(i2c_bus):
    try:
        sensor = adafruit_bme680.Adafruit_BME680_I2C(i2c_bus, address=BME680_I2C_ADDR)
        return sensor
    except Exception as e:
        print(f"Error initializing BME680 sensor: {e}")
        return None

def read_sensor_data(sensor):
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        pressure = sensor.pressure
        gas = sensor.gas
        return temperature, humidity, pressure, gas
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None, None, None

def log_data(temperature, humidity, pressure, gas):
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f"{timestamp},Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %, Pressure: {pressure:.2f} hPa, Gas: {gas:.2f} ohms\n"
    try:
        with open(LOG_FILE, 'a') as logfile:
            logfile.write(log_entry)
    except IOError as e:
        print(f"Error writing to log file: {e}")

def display_data(temperature, humidity, pressure, gas):
    print(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %, Pressure: {pressure:.2f} hPa, Gas: {gas:.2f} ohms")

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        sys.exit(1)

    sensor = initialize_sensor(i2c_bus)
    if sensor is None:
        sys.exit(1)

    try:
        while _running:
            temperature, humidity, pressure, gas = read_sensor_data(sensor)
            if all(v is not None for v in [temperature, humidity, pressure, gas]):
                log_data(temperature, humidity, pressure, gas)
                display_data(temperature, humidity, pressure, gas)
            time.sleep(SLEEP_INTERVAL)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        print("\nExiting program. Resources released.")

if __name__ == "__main__":
    main()

