import time
import logging
import signal
import sys
from smbus2 import SMBus

logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")
logger = logging.getLogger(__name__)


class DHT20:
    """Driver for the Aosong DHT20 temperature/humidity sensor (I2C, 7-bit 0x38)."""

    def __init__(self, bus_number=1, address=0x38):
        self.address = address
        self.bus = None
        self.last_temperature = None
        self.last_humidity = None
        self.last_humidity_valid = False
        self.last_temperature_valid = False
        self._closed = False
        self._min_interval = 2.0
        self._attempts = 5
        self._poll_interval = 0.08
        self._max_poll_delay = 0.8
        self._measurement_delay = 0.01
        self._crc_poly = 0x31
        self._crc_init = 0xFF

    def begin(self):
        """Open the I2C bus, wait 0.5 s, verify device presence, and return True."""
        try:
            self.bus = SMBus(bus_number)
        except OSError as exc:
            logger.error("Cannot open I2C bus %d: %s", bus_number, exc)
            return False

        time.sleep(0.5)

        try:
            status = self._read_u8(0x71)
        except OSError as exc:
            logger.error("Failed to read status register 0x71: %s", exc)
            self.close()
            return False

        if (status & 0x18) != 0x18:
            logger.error("DHT20 status 0x%02X does not match expected 0x18", status)
            self.close()
            return False

        logger.info("DHT20 detected (status=0x%02X)", status)
        return True

    def close(self):
        """Release the I2C bus handle."""
        if self._closed:
            return
        self._closed = True
        if self.bus is not None:
            try:
                self.bus.close()
            except OSError:
                pass
            self.bus = None

    def _read_u8(self, register):
        """Read a single unsigned byte from *register* with error handling."""
        try:
            return self.bus.read_byte_data(self.address, register)
        except OSError as exc:
            logger.warning("I2C read 0x%02X failed: %s", register, exc)
            raise

    def _read_bytes(self, register, length):
        """Read *length* bytes from *register* with error handling."""
        try:
            return self.bus.read_i2c_block_data(self.address, register, length)
        except OSError as exc:
            logger.warning("I2C block read 0x%02X len=%d failed: %s", register, length, exc)
            raise

    def _compute_crc8(self, data):
        """Compute CRC-8 with polynomial 0x31, initial 0xFF, no final XOR."""
        crc = self._crc_init
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ self._crc_poly) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def get_temperature_and_humidity(self):
        """
        Trigger a measurement and return (temperature_c, humidity_pct, error_flag).
        Returns (None, None, True) if the sensor is absent or all attempts fail.
        Enforces a minimum 2-second interval between calls.
        """
        if self._closed:
            return None, None, True

        now = time.monotonic()
        if now - self.last_temperature < self._min_interval:
            logger.info("Minimum interval %d s not reached; skipping", self._min_interval)
            return self.last_temperature, self.last_humidity, True

        for attempt in range(self._attempts):
            try:
                if not self._trigger_measurement():
                    time.sleep(self._measurement_delay)
                    continue

                for _ in range(int(self._max_poll_delay / self._poll_interval)):
                    if not self._wait_for_measurement():
                        time.sleep(self._poll_interval)

                data = self._read_bytes(0x71, 7)
                if len(data) < 7:
                    raise OSError("Short read: expected 7 bytes, got %d" % len(data))

                if self._compute_crc8(data) != data[6]:
                    raise OSError("CRC mismatch")

                self.last_humidity_valid = True
                self.last_temperature_valid = True

                humidity_raw = ((data[1] << 12) | (data[2] << 4) | ((data[3] & 0xF0) >> 4))
                self.last_humidity = humidity_raw / (1 << 20) * 100.0

                temp_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5])
                self.last_temperature = temp_raw / (1 << 19) * 200.0 - 50.0

