                self.last_temperature_valid = True

                humidity_raw = ((data[1] << 12) | (data[2] << 4) | ((data[3] & 0xF0) >> 4))
                self.last_humidity = humidity_raw / (1 << 20) * 100.0

                temp_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5])
                self.last_temperature = temp_raw / (1 << 19) * 200.0 - 50.0

                return self.last_temperature, self.last_humidity, False

            except OSError as exc:
                logger.warning("Measurement attempt %d/%d failed: %s", attempt + 1, self._attempts, exc)
                if attempt < self._attempts - 1:
                    time.sleep(self._measurement_delay)
                continue
            except Exception as exc:
                logger.error("Unexpected error during measurement: %s", exc)
                return None, None, True

        logger.error("All %d attempts exhausted", self._attempts)
        return None, None, True

    def _trigger_measurement(self):
        """Write [0x33, 0x00] to 0xAC to start a measurement."""
        try:
            self.bus.write_i2c_block_data(self.address, 0xAC, [0x33, 0x00])
            return True
        except OSError as exc:
            logger.warning("Trigger write failed: %s", exc)
            return False

    def _wait_for_measurement(self):
        """Poll status register 0x71 until bit 7 (busy) clears."""
        try:
            status = self._read_u8(0x71)
            return (status & 0x80) == 0
        except OSError:
            return False


