import time
import signal
import sys
import logging
from gpiozero import PWMOutputDevice

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

FAN_PIN = 17
PWM_FREQ = 25
MIN_TEMP = 45.0
MAX_TEMP = 55.0
MIN_SPEED = 45.0
MAX_SPEED = 100.0
HYSTERESIS = 1.0
POLL_INTERVAL = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    logging.info(f"Received signal {signum}, shutting down.")
    _running = False

def read_cpu_temp():
    try:
        with open('/sys/class/thermal/thermal_zone0/temp', 'r') as f:
            return float(f.read().strip()) / 1000.0
    except (IOError, OSError, ValueError) as e:
        logging.error(f"Error reading CPU temperature: {e}")
        return None

def compute_fan_speed(temp):
    if temp < MIN_TEMP:
        return MIN_SPEED
    elif temp >= MAX_TEMP:
        return MAX_SPEED
    else:
        return int(round(
            (MAX_SPEED - MIN_SPEED) / (MAX_TEMP - MIN_TEMP) * (temp - MIN_TEMP) + MIN_SPEED
        ))

def main():
    signal.signal(signal.SIGTERM, _signal_handler)
    signal.signal(signal.SIGINT, _signal_handler)

    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0.0)
    except Exception as e:
        logging.error(f"Failed to initialise PWM on GPIO{FAN_PIN}: {e}")
        sys.exit(1)

    last_speed = None
    try:
        while _running:
            temp = read_cpu_temp()
            if temp is None:
                time.sleep(POLL_INTERVAL)
                continue

            if last_speed is None or abs(temp - last_temp) >= HYSTERESIS:
                speed = compute_fan_speed(temp)
                try:
                    fan.value = speed / 100.0
                    last_speed = speed
                    last_temp = temp
                    logging.info(f"Temp: {temp:.1f}°C -> Fan: {speed:.0f}%")
                except Exception as e:
                    logging.error(f"Error setting fan PWM: {e}")
            else:
                logging.debug(f"Temp change below hysteresis ({temp:.1f}°C) -> skipping.")

            time.sleep(POLL_INTERVAL)
    finally:
        try:
            fan.value = 0.0
            fan.close()
        except Exception:
            pass
        logging.info("Fan stopped and GPIO released.")

if __name__ == '__main__':
    main()

