import subprocess
import time
import signal
import sys
import logging
from gpiozero import PWMOutputDevice

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

FAN_PIN = 14
PWM_FREQUENCY = 100
CHECK_INTERVAL = 5

TEMP_THRESHOLDS = [70, 60, 50, 40, 32, 25]
FAN_SPEEDS = [100, 85, 70, 50, 25, 15, 0]

running = True

def signal_handler(signum, frame):
    global running
    logging.info(f"Received signal {signum}, shutting down...")
    running = False

def get_cpu_temperature():
    try:
        output = subprocess.check_output(['vcgencmd', 'measure_temp'], text=True, timeout=5).strip()
        return float(output.split('=')[1].split("'")[0])
    except (subprocess.CalledProcessError, subprocess.TimeoutExpired, IndexError, ValueError) as e:
        logging.error(f"Error reading temperature via vcgencmd: {e}")
        try:
            with open('/sys/class/thermal/thermal_zone0/temp', 'r') as f:
                return float(f.read().strip()) / 1000.0
        except (IOError, OSError) as e2:
            logging.error(f"Error reading temperature from sysfs: {e2}")
            return None
    except FileNotFoundError:
        logging.error("vcgencmd not found; cannot read CPU temperature.")
        return None

def calculate_fan_speed(temperature):
    for i, temp_threshold in enumerate(TEMP_THRESHOLDS):
        if temperature > temp_threshold:
            return FAN_SPEEDS[i]
    return FAN_SPEEDS[-1]

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQUENCY, initial_value=0)
    except Exception as e:
        logging.error(f"Failed to initialize PWM on GPIO{FAN_PIN}: {e}")
        sys.exit(1)

    try:
        while running:
            temperature = get_cpu_temperature()
            if temperature is not None:
                fan_speed = calculate_fan_speed(temperature)
                fan.value = fan_speed / 100.0
                logging.info(f"Temperature: {temperature:.1f}°C, Fan Speed: {fan_speed}%")
            else:
                logging.warning("Temperature reading failed; maintaining current fan speed.")
            time.sleep(CHECK_INTERVAL)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        fan.close()
        logging.info("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

