import config
import signal
import sys
import time
import logging

import paho.mqtt.client as mqtt
import adafruit_dht
import board

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger(__name__)

DEGREE_CELS = "\u00B0C"

_running = True

def _signal_handler(signum, frame):
    global _running
    log.info("Signal %s received, shutting down...", signum)
    _running = False

def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        log.info("Connected to MQTT broker")
    else:
        log.error("MQTT connection failed with reason code %s", reason_code)

def on_disconnect(client, userdata, flags, reason_code, properties):
    log.warning("Disconnected from MQTT broker (reason code %s)", reason_code)

def read_dht22(sensor):
    """Return (temperature, humidity) or (None, None) after a max of 3 retries."""
    for attempt in range(1, 4):
        try:
            temp = sensor.temperature
            hum = sensor.humidity
            if temp is not None and hum is not None:
                return round(temp, 1), round(hum, 1)
        except RuntimeError as e:
            log.warning("DHT22 read attempt %d failed: %s", attempt, e)
        time.sleep(2)
    return None, None

def publish_data(client, topic, payload):
    info = client.publish(topic, payload, qos=1)
    info.wait_for_publish(timeout=5)
    if info.rc != mqtt.MQTT_ERR_SUCCESS:
        log.error("Publish failed for %s: %s", topic, info.rc)

def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    client = mqtt.Client(
        mqtt.CallbackAPIVersion.VERSION2,
        client_id=config.mqttclientid,
        clean_session=True,
    )
    client.username_pw_set(config.mqttusername, config.mqttpassword)
    client.on_connect = on_connect
    client.on_disconnect = on_disconnect

    try:
        client.connect(config.mqttbroker, port=config.mqttport, keepalive=30)
    except Exception as e:
        log.error("Failed to connect to MQTT broker: %s", e)
        sys.exit(1)

    client.loop_start()

    try:
        sensor = adafruit_dht.DHT22(getattr(board, f"D{config.dhtgpiopin}"), use_pulseio=False)
    except Exception as e:
        log.error("Failed to initialize DHT22 on GPIO %d: %s", config.dhtgpiopin, e)
        client.loop_stop()
        client.disconnect()
        sys.exit(1)

    try:
        while _running:
            temp, hum = read_dht22(sensor)
            if temp is not None and hum is not None:
                log.info("Temperature = %.1f %s, Humidity = %.1f %%", temp, DEGREE_CELS, hum)
                publish_data(client, f"homie/{config.homieclientid}/{config.homienodes}/temperature", str(temp))
                publish_data(client, f"homie/{config.homieclientid}/{config.homienodes}/humidity", str(hum))
            else:
                log.warning("DHT22 read failed after retries; skipping publish.")
            for _ in range(config.publishtime):
                if not _running:
                    break
                time.sleep(1)
    finally:
        try:
            sensor.exit()
        except Exception:
            pass
        client.loop_stop()
        client.disconnect()
        log.info("Resources released; exiting.")

if __name__ == "__main__":
    main()

