import signal
import sys
import time
from ina219 import INA219, DeviceRangeError
from smbus2 import SMBus, i2c_msg

DEVICE_BUS = 1
DEVICE_ADDR = 0x17

INA219_SUPPLY_ADDR = 0x40
INA219_BATT_ADDR = 0x45
SHUNT_SUPPLY = 0.00725
SHUNT_BATT = 0.005

running = True


def signal_handler(signum, frame):
    global running
    running = False


class INA219Sensor:
    def __init__(self, shunt_resistance, busnum, address):
        self.shunt_resistance = shunt_resistance
        self.busnum = busnum
        self.address = address
        self.ina = None
        self._init_sensor()

    def _init_sensor(self):
        try:
            self.ina = INA219(self.shunt_resistance, busnum=self.busnum, address=self.address)
            self.ina.configure()
        except Exception as e:
            print(f"Error initializing INA219 at 0x{self.address:02X}: {e}")
            self.ina = None

    def read_voltage(self):
        if self.ina is None:
            return None
        try:
            return self.ina.voltage()
        except DeviceRangeError:
            print(f"Warning: voltage out of range for INA219 at 0x{self.address:02X}")
            return None
        except Exception as e:
            print(f"Error reading voltage from INA219 at 0x{self.address:02X}: {e}")
            return None

    def read_current(self):
        if self.ina is None:
            return None
        try:
            return self.ina.current()
        except DeviceRangeError:
            print(f"Warning: current out of range for INA219 at 0x{self.address:02X}")
            return None
        except Exception as e:
            print(f"Error reading current from INA219 at 0x{self.address:02X}: {e}")
            return None

    def read_power(self):
        if self.ina is None:
            return None
        try:
            return self.ina.power()
        except DeviceRangeError:
            print(f"Warning: power out of range for INA219 at 0x{self.address:02X}")
            return None
        except Exception as e:
            print(f"Error reading power from INA219 at 0x{self.address:02X}: {e}")
            return None


class UPSPlus:
    def __init__(self, bus_num, device_addr):
        self.bus_num = bus_num
        self.device_addr = device_addr
        self.bus = None
        self.supply_sensor = INA219Sensor(SHUNT_SUPPLY, bus_num, INA219_SUPPLY_ADDR)
        self.batt_sensor = INA219Sensor(SHUNT_BATT, bus_num, INA219_BATT_ADDR)
        self._init_ups()

    def _init_ups(self):
        try:
            self.bus = SMBus(self.bus_num)
        except Exception as e:
            print(f"Error opening I2C bus {self.bus_num}: {e}")
            self.bus = None
            return
        try:
            self._read_all_registers()
        except Exception as e:
            print(f"Error reading UPS registers: {e}")

    def _read_register(self, reg):
        if self.bus is None:
            return None
        try:
            return self.bus.read_byte_data(self.device_addr, reg)
        except Exception as e:
            print(f"Error reading register 0x{reg:02X}: {e}")
            return None

    def _write_register(self, reg, value):
        if self.bus is None:
            return False
        try:
            self.bus.write_byte_data(self.device_addr, reg, value)
            return True
        except Exception as e:
            print(f"Error writing to register 0x{reg:02X}: {e}")
            return False

    def _read_multi_byte(self, reg, length):
        if self.bus is None:
            return None
        try:
            return self.bus.read_i2c_block_data(self.device_addr, reg, length)
        except Exception as e:
            print(f"Error reading multi-byte data from 0x{reg:02X}: {e}")
            return None

    def _write_multi_byte(self, reg, data):
        if self.bus is None:
            return False
        try:
            self.bus.write_i2c_block_data(self.device_addr, reg, data)
            return True
        except Exception as e:
            print(f"Error writing multi-byte data to 0x{reg:02X}: {e}")
            return False

    def _read_u16le(self, reg):
        data = self._read_multi_byte(reg, 2)
        if data is None or len(data) < 2:
            return None
        return int.from_bytes(data[0:2], byteorder='little', signed=False)

    def _read_s16le(self, reg):
        data = self._read_multi_byte(reg, 2)
        if data is None or len(data) < 2:
            return None
        return int.from_bytes(data[0:2], byteorder='little', signed=True)

    def _read_u32le(self, reg):
        data = self._read_multi_byte(reg, 4)
        if data is None or len(data) < 4:
            return None
        return int.from_bytes(data[0:4], byteorder='little', signed=False)

    def _read_s32le(self, reg):
        data = self._read_multi_byte(reg, 4)
        if data is None or len(data) < 4:
            return None
        return int.from_bytes(data[0:4], byteorder='little', signed=True)

    def _read_all_registers(self):
        self.processor_voltage = self._read_u16le(0x01)
        self.pi_voltage = self._read_u16le(0x03)
        self.batt_port_voltage = self._read_u16le(0x05)
        self.charging_port_c = self._read_u16le(0x07)
        self.charging_port_u = self._read_u16le(0x09)
        self.batt_temp = self._read_s16le(0x0B)
        self.full_batt_volt = self._read_u16le(0x0D)
        self.empty_batt_volt = self._read_u16le(0x0F)
        self.batt_protect_volt = self._read_u16le(0x11)
        self.remaining_capacity = self._read_u16le(0x13)
        self.sampling_period = self._read_u16le(0x15)
        self.power_state = self._read_register(0x17)
        self.shutdown_countdown = self._read_u16le(0x18)
        self.auto_power_on = self._read_register(0x19)
        self.restart_countdown = self._read_u16le(0x1A)

    def read_supply_data(self):
        supply_voltage = self.supply_sensor.read_voltage()
        supply_current = self.supply_sensor.read_current()
        supply_power = self.supply_sensor.read_power()
        if supply_voltage is not None:
            print(f"Supply Voltage: {supply_voltage:.3f} V")
        if supply_current is not None:
            print(f"Supply Current: {supply_current:.3f} mA")
        if supply_power is not None:
            print(f"Supply Power: {supply_power:.3f} mW")

    def read_battery_data(self):
        batt_voltage = self.batt_sensor.read_voltage()
        batt_current = self.batt_sensor.read_current()
        batt_power = self.batt_sensor.read_power()
        if batt_voltage is not None:
            print(f"Battery Voltage: {batt_voltage:.3f} V")
        if batt_current is not None:
            print(f"Battery Current: {batt_current:.3f} mA")
        if batt_power is not None:
            print(f"Battery Power: {batt_power:.3f} mW")

    def read_ups_data(self):
        print(f"Processor Voltage: {self.processor_voltage:.3f} mV")
        print(f"Raspberry Pi Voltage: {self.pi_voltage:.3f} mV")
        print(f"Battery Port Voltage: {self.batt_port_voltage:.3f} mV")
        print(f"Type-C Charging Port Voltage: {self.charging_port_c:.3f} mV")
        print(f"Micro-USB Charging Port Voltage: {self.charging_port_u:.3f} mV")
        print(f"Battery Temperature: {self.batt_temp:.3f} degC")
        print(f"Full Battery Voltage: {self.full_batt_volt:.3f} mV")
        print(f"Empty Battery Voltage: {self.empty_batt_volt:.3f} mV")
        print(f"Battery Protection Voltage: {self.batt_protect_volt:.3f} mV")
        print(f"Remaining Capacity: {self.remaining_capacity:.3f} %")
        print(f"Sampling Period: {self.sampling_period} min")
        print(f"Power State: {'ON' if self.power_state == 1 else 'OFF'}")
        print(f"Shutdown Countdown: {self.shutdown_countdown}")
        print(f"Auto Power On: {'Enabled' if self.auto_power_on == 1 else 'Disabled'}")
        print(f"Restart Countdown: {self.restart_countdown}")

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except Exception:
                pass
            self.bus = None


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    ups = None
    try:
        ups = UPSPlus(DEVICE_BUS, DEVICE_ADDR)
        if ups.bus is None:
            print("Failed to initialize UPSPlus. Check I2C connection and device address.")
            return

        while running:
            ups.read_supply_data()
            ups.read_battery_data()
            ups.read_ups_data()
            time.sleep(1)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if ups is not None:
            ups.close()


if __name__ == "__main__":
    main()

