import time
import signal
import sys
import sqlite3
import board
import adafruit_dht
from gpiozero import LED, OutputDevice

# --- Configuration ---
DHT_PIN = board.D4          # GPIO4 (BCM)
RELAY_PIN = 17              # GPIO17
LED_PIN = 27                # GPIO27
DB_FILE = 'greenhouse.db'
SAMPLE_INTERVAL = 60        # seconds
PUMP_DURATION = 10          # seconds
HUMIDITY_THRESHOLD = 40.0   # percent

# --- Globals for cleanup ---
dht_device = None
relay = None
led = None
running = True

def cleanup():
    """Release all hardware resources cleanly."""
    global dht_device, relay, led
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass
        dht_device = None
    if relay is not None:
        try:
            relay.close()
        except Exception:
            pass
        relay = None
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
        led = None

def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    running = False

def init_database():
    """Create the sensor_data table if it does not exist."""
    conn = None
    try:
        conn = sqlite3.connect(DB_FILE)
        conn.execute('''
            CREATE TABLE IF NOT EXISTS sensor_data (
                timestamp TEXT,
                temperature REAL,
                humidity REAL
            )
        ''')
        conn.commit()
    except sqlite3.Error as e:
        print(f"Database initialization error: {e}", file=sys.stderr)
        raise
    finally:
        if conn:
            conn.close()

def log_data(timestamp, temperature, humidity):
    """Insert a reading into the database."""
    conn = None
    try:
        conn = sqlite3.connect(DB_FILE)
        conn.execute(
            "INSERT INTO sensor_data (timestamp, temperature, humidity) VALUES (?, ?, ?)",
            (timestamp, temperature, humidity)
        )
        conn.commit()
    except sqlite3.Error as e:
        print(f"Database write error: {e}", file=sys.stderr)
    finally:
        if conn:
            conn.close()

def read_sensor():
    """Read temperature and humidity from the DHT22.
    Returns (temperature, humidity) or (None, None) on failure."""
    global dht_device
    if dht_device is None:
        return None, None
    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is None or humidity is None:
            return None, None
        return temperature, humidity
    except RuntimeError as e:
        # DHT22 often throws checksum or timing errors; retry on next cycle
        return None, None
    except Exception as e:
        print(f"Unexpected sensor error: {e}", file=sys.stderr)
        return None, None

def control_watering(humidity):
    """Activate relay for PUMP_DURATION seconds if humidity < threshold."""
    global relay
    if relay is None:
        return
    try:
        if humidity is not None and humidity < HUMIDITY_THRESHOLD:
            relay.on()
            time.sleep(PUMP_DURATION)
            relay.off()
    except Exception as e:
        print(f"GPIO/relay error: {e}", file=sys.stderr)

def update_led(state):
    """Set LED on/off or blink based on current failure count."""
    global led
    if led is None:
        return
    try:
        if state == 'normal':
            led.on()
        elif state == 'blink':
            led.blink(on_time=0.5, off_time=0.5, n=1, background=False)
        elif state == 'fast_blink':
            led.blink(on_time=0.25, off_time=0.25, n=1, background=False)
        elif state == 'error':
            led.off()
    except Exception as e:
        print(f"LED error: {e}", file=sys.stderr)

def main():
    global dht_device, relay, led, running

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize hardware
    try:
        dht_device = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT22 on GPIO4: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        relay = OutputDevice(RELAY_PIN)
        led = LED(LED_PIN)
    except Exception as e:
        print(f"Failed to initialize GPIO: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    # Initialize database
    try:
        init_database()
    except Exception:
        cleanup()
        sys.exit(1)

    failure_count = 0
    led_state = 'normal'

    print("Greenhouse monitor started. Press Ctrl+C to stop.")

    while running:
        timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
        temperature, humidity = read_sensor()

        if temperature is not None and humidity is not None:
            log_data(timestamp, temperature, humidity)
            control_watering(humidity)
            failure_count = 0
            led_state = 'normal'
            update_led('normal')
        else:
            failure_count += 1
            if failure_count == 1:
                led_state = 'blink'
                update_led('blink')
            elif failure_count == 2:
                led_state = 'fast_blink'
                update_led('fast_blink')
            else:
                led_state = 'error'
                update_led('error')
                print(f"Sensor read failed {failure_count} times. Stopping.", file=sys.stderr)
                break

        # Sleep in small increments so signals are caught promptly
        slept = 0
        while slept < SAMPLE_INTERVAL and running:
            time.sleep(1)
            slept += 1

    cleanup()
    print("Program terminated.")

if __name__ == '__main__':
    main()

