import logging
import logging.handlers
import random
import time
import os
from gpiozero import InputDevice

# ---------------------------------------------------------------------------
# Logging configuration
# ---------------------------------------------------------------------------
LOG_DIR = "/var/log/wearable"
FALLBACK_LOG_DIR = os.path.expanduser("~/.local/log/wearable")

log_file_path = LOG_DIR
if not os.path.isdir(LOG_DIR) or not os.access(LOG_DIR, os.W_OK):
    log_file_path = FALLBACK_LOG_DIR

logger = logging.getLogger("wearable_sensor")
logger.setLevel(logging.INFO)

try:
    handler = logging.handlers.TimedRotatingFileHandler(
        log_file_path, when="midnight", interval=1, backupCount=7
    )
except (PermissionError, OSError) as exc:
    handler = logging.handlers.TimedRotatingFileHandler(
        FALLBACK_LOG_DIR, when="midnight", interval=1, backupCount=7
    )
formatter = logging.Formatter("%(asctime)s - %(levelname)s - %(message)s")
handler.setFormatter(formatter)
logger.addHandler(handler)

# ---------------------------------------------------------------------------
# GPIO setup (placeholder digital input)
# ---------------------------------------------------------------------------
DHT_PIN = 4  # BCM GPIO4
sensor_gpio = None
try:
    sensor_gpio = InputDevice(DHT_PIN, pull_up=True)
    logger.info("GPIO %d initialised as placeholder digital input.", DHT_PIN)
except Exception as exc:
    logger.warning("Could not initialise GPIO %d: %s. Continuing without GPIO.", DHT_PIN, exc)
    sensor_gpio = None

# ---------------------------------------------------------------------------
# Sensor simulation
# ---------------------------------------------------------------------------
def simulate_sensor_reading():
    """Simulate a DHT22 reading. Returns (temperature, humidity) or None."""
    if random.random() < 0.05:  # 5% chance of a simulated sensor error
        return None
    temperature = round(random.uniform(15, 45), 1)
    humidity = round(random.uniform(40, 95), 1)
    return temperature, humidity


def validate_data(temperature, humidity):
    """Validate temperature and humidity ranges. Returns True if valid."""
    if temperature is None or humidity is None:
        return False
    try:
        temp = float(temperature)
        hum = float(humidity)
    except (TypeError, ValueError):
        return False
    if not (10 <= temp <= 55):
        logger.error("Invalid temperature: %.1f", temp)
        return False
    if not (20 <= hum <= 100):
        logger.error("Invalid humidity: %.1f", hum)
        return False
    return True


# ---------------------------------------------------------------------------
# Main loop
# ---------------------------------------------------------------------------
def main():
    logger.info("Starting wearable sensor simulation.")
    try:
        while True:
            reading = simulate_sensor_reading()
            if reading is None:
                logger.error("Simulated sensor error. Retrying...")
                for attempt in range(3):
                    time.sleep(1)
                    reading = simulate_sensor_reading()
                    if reading is not None:
                        break
                if reading is None:
                    logger.error("Failed to obtain valid reading after 3 retries.")
                    continue
            temperature, humidity = reading
            if validate_data(temperature, humidity):
                logger.info("Temperature: %.1f°C, Humidity: %.1f%%", temperature, humidity)
            else:
                logger.error("Invalid data received: temp=%.1f, humidity=%.1f", temperature, humidity)
    except KeyboardInterrupt:
        logger.info("Shutting down wearable sensor simulation.")
    except Exception as exc:
        logger.error("Unexpected error: %s", exc, exc_info=True)
    finally:
        if sensor_gpio is not None:
            try:
                sensor_gpio.close()
            except Exception:
                pass
        for handler in list(logger.handlers):
            try:
                handler.close()
            except Exception:
                pass


if __name__ == "__main__":
    main()

