import csv
import time
import atexit
from datetime import datetime
from gpiozero import DigitalInputDevice

LOW_SENSOR_PIN = 2
MEDIUM_SENSOR_PIN = 3
HIGH_SENSOR_PIN = 4
CSV_FILE = 'water_levels.csv'

water_levels = []
low_sensor = None
medium_sensor = None
high_sensor = None

def read_water_level(pin):
    """Read a digital water level sensor on the given GPIO pin.
    Returns 'PRESENT' if the pin reads HIGH (water present),
    'ABSENT' if LOW (no water), or 'UNKNOWN' on error."""
    try:
        if pin == LOW_SENSOR_PIN:
            sensor = low_sensor
        elif pin == MEDIUM_SENSOR_PIN:
            sensor = medium_sensor
        elif pin == HIGH_SENSOR_PIN:
            sensor = high_sensor
        else:
            return 'UNKNOWN'
        if sensor is None:
            return 'UNKNOWN'
        return 'PRESENT' if sensor.is_active else 'ABSENT'
    except Exception as e:
        print(f"Error reading sensor on pin {pin}: {e}")
        return 'UNKNOWN'

def log_water_levels(timestamp, low, medium, high):
    """Append a row to the CSV file and write the header if the file is new."""
    try:
        file_exists = False
        try:
            with open(CSV_FILE, 'r') as f:
                file_exists = True
        except FileNotFoundError:
            pass
        with open(CSV_FILE, 'a', newline='') as csvfile:
            writer = csv.writer(csvfile)
            if not file_exists:
                writer.writerow(['timestamp', 'low', 'medium', 'high'])
            writer.writerow([timestamp, low, medium, high])
    except Exception as e:
        print(f"Error writing to CSV file: {e}")

def cleanup():
    """Release GPIO resources."""
    global low_sensor, medium_sensor, high_sensor
    for sensor in [low_sensor, medium_sensor, high_sensor]:
        if sensor is not None:
            try:
                sensor.close()
            except Exception:
                pass

atexit.register(cleanup)

if __name__ == '__main__':
    try:
        low_sensor = DigitalInputDevice(LOW_SENSOR_PIN, pull_up=False, bounce_time=0.1)
        medium_sensor = DigitalInputDevice(MEDIUM_SENSOR_PIN, pull_up=False, bounce_time=0.1)
        high_sensor = DigitalInputDevice(HIGH_SENSOR_PIN, pull_up=False, bounce_time=0.1)
        print("Water level monitoring started. Press Ctrl+C to stop.")
        while True:
            timestamp = datetime.now().isoformat()
            low = read_water_level(LOW_SENSOR_PIN)
            medium = read_water_level(MEDIUM_SENSOR_PIN)
            high = read_water_level(HIGH_SENSOR_PIN)
            log_water_levels(timestamp, low, medium, high)
