import signal
import sys
import time

from gpiozero import DigitalInputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

# Configuration
SENSOR_PINS = [17, 27, 22]
POLL_INTERVAL_S = 1.0

# Global list to track devices for cleanup
_devices = []


def _cleanup(signum=None, frame=None):
    """Release all GPIO resources and exit cleanly."""
    for dev in _devices:
        try:
            if dev is not None and dev.closed is False:
                dev.close()
        except Exception:
            pass
    _devices.clear()
    if signum is not None:
        print(f"\nReceived signal {signum}, exiting.")
        sys.exit(0)


def main():
    global _devices

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    print(f"Starting sensor monitoring on pins {SENSOR_PINS} (BCM)...")
    print(f"Polling interval: {POLL_INTERVAL_S}s")
    print("Press Ctrl+C to stop.\n")

    # Initialize each sensor with an active-high pull-up resistor
    for pin in SENSOR_PINS:
        try:
            dev = DigitalInputDevice(pin=pin, pull_up=True, bounce_time=None)
            _devices.append(dev)
            print(f"  Pin {pin}: initialized as input with pull-up")
        except GPIOZeroError as e:
            print(f"ERROR: Failed to initialize GPIO pin {pin}: {e}", file=sys.stderr)
            _cleanup()
            sys.exit(1)
        except Exception as e:
            print(f"ERROR: Unexpected failure on pin {pin}: {e}", file=sys.stderr)
            _cleanup()
            sys.exit(1)

    # Main polling loop
    try:
        while True:
            for idx, pin in enumerate(SENSOR_PINS):
                dev = _devices[idx]
                try:
                    if dev.is_active:  # HIGH == active for pull-up configuration
                        print(f"Response for sensor {idx + 1}")
                except DeviceClosed:
                    print(f"WARNING: Pin {pin} device closed unexpectedly; skipping.", file=sys.stderr)
                except GPIOZeroError as e:
                    print(f"WARNING: Read error on pin {pin}: {e}", file=sys.stderr)
                except Exception as e:
                    print(f"WARNING: Unexpected read error on pin {pin}: {e}", file=sys.stderr)

            time.sleep(POLL_INTERVAL_S)
    except KeyboardInterrupt:
        print("\nKeyboardInterrupt received, exiting.")
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

