import signal
import sys
import time
import json
import requests
from requests.auth import HTTPBasicAuth
from gpiozero import InputDevice

SENSOR_PIN = 4
SERVER_URL = 'http://localhost:5000/sensor'
USERNAME = 'user'
PASSWORD = 'pass'
POLL_INTERVAL = 5

running = True

def handle_signal(signum, frame):
    global running
    running = False

def read_sensor(sensor):
    try:
        return int(sensor.value)
    except Exception as e:
        print(f"Sensor read error: {e}", file=sys.stderr)
        return None

def send_data(sensor_value):
    payload = {'sensor': 'digital_input', 'value': sensor_value}
    try:
        response = requests.post(
            SERVER_URL,
            json=payload,
            auth=HTTPBasicAuth(USERNAME, PASSWORD),
            timeout=10
        )
        print(f"Server response: {response.status_code}")
    except requests.RequestException as e:
        print(f"Request error: {e}", file=sys.stderr)

def main():
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    sensor = None
    try:
        sensor = InputDevice(SENSOR_PIN, pull_up=False)
        print(f"Sensor initialized on GPIO {SENSOR_PIN} (floating input).")

        while running:
            value = read_sensor(sensor)
            if value is not None:
                print(f"Sensor value: {value}")
                send_data(value)
            time.sleep(POLL_INTERVAL)

    except Exception as e:
        print(f"Initialization or runtime error: {e}", file=sys.stderr)
    finally:
        if sensor is not None:
            sensor.close()
        print("GPIO cleanup completed.")

if __name__ == '__main__':
    main()

