import sys
import threading
import time
import signal
import RPi.GPIO as GPIO

# Constants
DEFAULT_FILENAME = "data.log"
RECEIVE_INTERVAL = 0.1  # seconds

# Global state
server_running = False
log_file_name = DEFAULT_FILENAME
receive_thread = None
receive_lock = threading.Lock()
log_data = ""

# Mock DOG module (replace with actual implementation)
class DOG:
    @staticmethod
    def send(data):
        print(f"Sending: {data}")

    @staticmethod
    def receive():
        return "test"

def signal_handler(sig, frame):
    """Handle SIGINT/SIGTERM to ensure clean shutdown."""
    global server_running, receive_thread
    print("\nSignal received, shutting down...")
    server_running = False
    if receive_thread is not None and receive_thread.is_alive():
        receive_thread.join(timeout=2.0)
    GPIO.cleanup()
    sys.exit(0)

def start_server(filename):
    """Starts the server and begins receiving data."""
    global server_running, log_file_name, receive_thread, log_data
    if server_running:
        print("Server already running.")
        return

    log_file_name = filename
    try:
        with open(log_file_name, "a") as log_file:
            log_data = log_file.read()
            log_file.close()
    except IOError as e:
        print(f"Error opening log file: {e}")
        return

    server_running = True
    receive_thread = threading.Thread(target=receive_loop, daemon=True)
    receive_thread.start()
    print(f"Server started, logging to {log_file_name}")

def receive_loop():
    """Continuously receives data and appends it to the log file."""
    global log_data
    while server_running:
        try:
            data = DOG.receive()
            with receive_lock:
                log_data += (data + "\n")
        except Exception as e:
            print(f"Receive error: {e}")
        time.sleep(RECEIVE_INTERVAL)

def stop_server():
    """Stops the server and ends the receive thread."""
    global server_running, receive_thread
    if not server_running:
        print("Server not running.")
        return
    server_running = False
    if receive_thread is not None and receive_thread.is_alive():
        receive_thread.join(timeout=2.0)
    print("Server stopped.")

def help_command(args):
    """Displays help information for commands."""
    if not args:
        print("Available commands: help, start, stop, display, send, write, exit")
