        parts = args[0].split()
        command = parts[0]
        if command == "help":
            if len(parts) == 1:
                print("Available commands: help, start, stop, display, send, write, exit")
            elif len(parts) == 2 and parts[1] == "start":
                print("Usage: start ")
            elif len(parts) == 2 and parts[1] == "stop":
                print("Usage: stop")
            elif len(parts) == 2 and parts[1] == "display":
                print("Usage: display")
            elif len(parts) == 3 and parts[1] == "send" and parts[2] in ("<data>", "DATA"):
                print("Usage: send <data>")
            elif len(parts) == 3 and parts[1] == "write" and parts[2] in ("<data>", "DATA"):
                print("Usage: write <data>")
            elif len(parts) == 2 and parts[1] == "exit":
                print("Usage: exit")
            else:
                print("Unknown subcommand.")
        else:
            print(f"No help found for command: {command}")

def display_command(args):
    """Displays the contents of the log file."""
    if not server_running:
        print("Server not running. Start the server first.")
        return
    try:
        with open(log_file_name, "r") as log_file:
            print(log_file.read())
    except IOError as e:
        print(f"Error reading log file: {e}")

def send_command(args):
    """Sends data using the DOG module."""
    if not server_running:
        print("Server not running. Start the server first.")
        return
    if len(args) < 2:
        print("Usage: send <data>")
        return
    data = " ".join(args[1:])
    try:
        DOG.send(data)
        print(f"Sent: {data}")
    except Exception as e:
        print(f"Send error: {e}")

def write_command(args):
    """Writes data directly to the log file."""
    if not server_running:
        print("Server not running. Start the server first.")
        return
    if len(args) < 2:
        print("Usage: write <data>")
        return
    data = " ".join(args[1:])
    try:
        with open(log_file_name, "a") as log_file:
            log_file.write(data + "\n")
        print(f"Wrote: {data}")
    except IOError as e:
        print(f"Write error: {e}")

def exit_command(args):
    """Stops the server and exits."""
    stop_server()
    print("Exiting.")
    sys.exit(0)

def main():
    """Main function to handle user commands."""
    global server_running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    while True:
        try:
            command = input("JAYES@ROVER53:\t")
            args = command.split()
            if not args:
                continue
            command_name = args[0].lower()
            if command_name == "help":
                help_command(args)
            elif command_name == "start":
                if len(args) < 2:
                    print("Usage: start ")
                    continue
                start_server(args[1])
            elif command_name == "stop":
                stop_server()
            elif command_name == "display":
                display_command(args)
            elif command_name == "send":
                send_command(args)
            elif command_name == "write":
                write_command(args)
            elif command_name == "exit":
                exit_command(args)
            else:
                print("Unknown command. Try 'help'")
        except EOFError:
            print("\nEOF received, exiting.")
            break
        except Exception as e:
            print(f"An error occurred: {e}")

if __name__ == "__main__":
    GPIO.setmode(GPIO.BCM)
    try:
        main()
    finally:
        GPIO.cleanup()

