import spidev
import time
import signal
import sys
from gpiozero import OutputDevice
from lib_tft144 import TFT144

# Pin definitions (BCM numbering)
SPI_PORT = 0
SPI_DEVICE = 0
DC_PIN = 22
RST_PIN = 18
LED_PIN = 23

# Global resources for cleanup
_tft = None
_spi = None
_dc = None
_rst = None
_led = None
_running = True

def cleanup(signum=None, frame=None):
    """Release all hardware resources cleanly."""
    global _running, _tft, _spi, _dc, _rst, _led
    _running = False
    try:
        if _led is not None:
            _led.off()
    except Exception:
        pass
    try:
        if _tft is not None:
            _tft.clear_display(0)
    except Exception:
        pass
    try:
        if _spi is not None:
            _spi.close()
    except Exception:
        pass
    try:
        if _dc is not None:
            _dc.close()
    except Exception:
        pass
    try:
        if _rst is not None:
            _rst.close()
    except Exception:
        pass
    try:
        if _led is not None:
            _led.close()
    except Exception:
        pass
    if signum is not None:
        sys.exit(0)

def main():
    global _tft, _spi, _dc, _rst, _led

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Initialize GPIO control pins using gpiozero
    try:
        _dc = OutputDevice(DC_PIN)
        _rst = OutputDevice(RST_PIN)
        _led = OutputDevice(LED_PIN)
    except Exception as e:
        print(f"Failed to initialize GPIO pins: {e}")
        sys.exit(1)

    # Initialize SPI
    try:
        _spi = spidev.SpiDev()
        _spi.open(SPI_PORT, SPI_DEVICE)
        _spi.max_speed_hz = 32000000
        _spi.mode = 0
    except Exception as e:
        print(f"Failed to initialize SPI: {e}")
        cleanup()
        sys.exit(1)

    # Initialize the TFT144 display
    try:
        _tft = TFT144(
            _spi,
            DC_PIN,
            RST_PIN,
            LED_PIN,
            TFT144.ORIENTATION90,
        )
    except Exception as e:
        print(f"Failed to initialize TFT144 display: {e}")
        cleanup()
        sys.exit(1)

    # Cycle through colors
    colors = [
        TFT144.BLUE, TFT144.RED, TFT144.GREEN, TFT144.PINK,
        TFT144.LIGHTBLUE, TFT144.LIGHTGREEN, TFT144.YELLOW,
        TFT144.MAGENTA, TFT144.CYAN,
    ]
    for color in colors:
        if not _running:
            break
        try:
            _tft.clear_display(color)
            time.sleep(1)
        except Exception as e:
            print(f"Error displaying color {color}: {e}")
            break

    # Display 'Hello' for 2 seconds
    if _running:
        try:
            _tft.put_string("Hello", 0, 0)
            time.sleep(2)
        except Exception as e:
            print(f"Error displaying string: {e}")

    cleanup()

if __name__ == "__main__":
    main()

