import signal
import sys
import time
import logging
from gpiozero import OutputDevice, InputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DATA_OUT_PIN = 5
TIMER_OUT_PIN = 6
DATA_IN_PIN = 20
TIMER_IN_PIN = 21

START_SIGNAL = [1, 0, 1, 1, 1, 1, 1, 1]
END_SIGNAL = [1, 1, 1, 1, 1, 1, 1, 1]

_running = True

def signal_handler(signum, frame):
    global _running
    logging.info(f"Signal {signum} received, shutting down...")
    _running = False

def setup_gpio():
    try:
        data_out = OutputDevice(DATA_OUT_PIN)
        timer_out = OutputDevice(TIMER_OUT_PIN)
        data_in = InputDevice(DATA_IN_PIN)
        timer_in = InputDevice(TIMER_IN_PIN)
        logging.info("GPIO setup successful.")
        return data_out, timer_out, data_in, timer_in
    except GPIOZeroError as e:
        logging.error(f"GPIO setup failed: {e}")
        return None, None, None, None
    except Exception as e:
        logging.error(f"Unexpected error during GPIO setup: {e}")
        return None, None, None, None

def send_data(data_out, timer_out, data, transmit_delay=0.0005):
    if data_out is None or timer_out is None:
        raise RuntimeError("GPIO devices not initialized.")
    try:
        for bit in data:
            if not _running:
                raise RuntimeError("Transmission interrupted.")
            data_out.value = 1 if bit else 0
            time.sleep(transmit_delay)
            timer_out.value = 1
            time.sleep(transmit_delay)
            timer_out.value = 0
            time.sleep(transmit_delay)
    except DeviceClosed:
        raise RuntimeError("GPIO device closed during transmission.")
    except Exception as e:
        logging.error(f"Error during data transmission: {e}")
        raise

def receive_data(data_in, timer_in, receive_timeout=1.0):
    if data_in is None or timer_in is None:
        raise RuntimeError("GPIO devices not initialized.")
    try:
        start_time = time.time()
        while _running:
            if time.time() - start_time > receive_timeout:
                raise TimeoutError("Reception timeout exceeded.")
            if timer_in.value == 0:
                break
            if data_in.value == 1:
                break
            time.sleep(0.000001)
        if not _running:
            raise RuntimeError("Reception interrupted.")
        received_data = []
        for _ in range(8):
            if timer_in.value == 0:
                break
            if data_in.value == 1:
                received_data.append(1)
            else:
                received_data.append(0)
            for _ in range(7):
                if timer_in.value == 0:
                    break
                if data_in.value == 1:
                    break
                time.sleep(0.000001)
        return received_data
    except DeviceClosed:
        raise RuntimeError("GPIO device closed during reception.")
    except Exception as e:
        logging.error(f"Error during data reception: {e}")
        raise

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    data_out, timer_out, data_in, timer_in = setup_gpio()
    if data_out is None or data_in is None:
        logging.error("Failed to initialize GPIO. Exiting.")
        sys.exit(1)
    try:
        message = [1, 0, 0, 0, 0, 0, 0, 0]
        send_data(data_out, timer_out, message)
