        logging.info(f"Received data: {received_data}")
    except Exception as e:
        logging.error(f"An error occurred: {e}")
    finally:
        if data_out is not None:
            data_out.close()
        if timer_out is not None:
            timer_out.close()
        if data_in is not None:
            data_in.close()
        if timer_in is not None:
