import pigpio

class OutputPin:
    """
    Controls a GPIO pin as a digital output using pigpio.
    """
    def __init__(self, name, pin_number, value_list, initial_value=0, value_setting_list=None):
        self.name = name
        self.pin_number = pin_number
        self.value_list = value_list
        self.value_setting_list = value_setting_list if value_setting_list is not None else list(value_list)
        self.current_value = initial_value
        self.pigp = None

        if not isinstance(self.value_list, tuple) or len(self.value_list) < 2:
            raise ValueError("value_list must be a tuple of at least two values")

        try:
            self.pigp = pigpio.pi()
            if not self.pigp.connected:
                raise RuntimeError("Failed to connect to pigpio daemon. Is pigpiod running?")

            if self.pigp.set_mode(self.pin_number, pigpio.OUTPUT) != 0:
                raise RuntimeError(f"Failed to set pin {self.pin_number} as OUTPUT")

            self.set_value(self.value_list[self.current_value])
            print(f"{self.name} (GPIO{self.pin_number}) initialized to {self.value_list[self.current_value]}")
        except Exception as e:
            print(f"Error initializing {self.name} on GPIO{self.pin_number}: {e}", file=sys.stderr)
            self.shutdown()
            raise

    def set_value(self, value):
        if value not in self.value_list:
            raise ValueError(f"Value {value} not in value_list for {self.name}")

        if self.pigp is None or not self.pigp.connected:
            print(f"pigpio not connected for {self.name}", file=sys.stderr)
            return

        index = self.value_list.index(value)
        if index != self.current_value:
            self.pigp.set_mode(self.pin_number, pigpio.OUTPUT)
            self.pigp.write(self.pin_number, value)
            self.current_value = index
            print(f"{self.name} (GPIO{self.pin_number}) set to {value}")

    def get_value(self):
        return self.value_list[self.current_value]

    def shutdown(self):
        if self.pigp is not None and self.pigp.connected:
            try:
