import signal
import sys

try:
    from gpiozero import PWMOutputDevice, OutputDevice
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    logging.error("gpiozero is not installed. Install with: pip install gpiozero")
    sys.exit(1)

logger = logging.getLogger(__name__)


class PIDHandler:
    """
    Handles PID controller updates, error output, and message processing
    using gpiozero for modern, robust GPIO/PWM management on Raspberry Pi.
    """

    def __init__(self, config):
        self.config = config
        self.last_msg = time.time()
        self.global_err_state = False
        self.pwm = None
        self.digital_out = None
        self._initialized = False

        # Validate config.pwm_enabled is a bool
        if not isinstance(config.pwm_enabled, bool):
            raise ValueError("config.pwm_enabled must be a boolean")

        # Initialize GPIO devices
        try:
            if config.pwm_enabled:
                # Physical pin 12 (BCM GPIO 18) at 1000 Hz, 0% duty cycle
                self.pwm = PWMOutputDevice(
                    pin=18,
                    frequency=1000,
                    initial_value=0.0,
                )
                logger.info("PWM initialized on BCM GPIO 18 (physical pin 12)")
            else:
                # Physical pin 10 (BCM GPIO 15) as digital output
                self.digital_out = OutputDevice(
                    pin=15,
                )
                logger.info("Digital output initialized on BCM GPIO 15 (physical pin 10)")
        except GPIOZeroError as e:
            logger.error(f"Failed to initialize GPIO: {e}")
            self.cleanup()
            raise

        self._initialized = True

    # ------------------------------------------------------------------
    # Error output helpers
    # ------------------------------------------------------------------
    def update_error_output(self):
        """Set the error output based on self.global_err_state."""
        if self.pwm is not None:
            self.pwm.value = 1.0 if self.global_err_state else 0.0
        else:
            if self.global_err_state:
                self.digital_out.on()
            else:
                self.digital_out.off()

    def set_error_output(self, state: bool):
        """Directly set the error output to a boolean value."""
        if self.pwm is not None:
            self.pwm.value = 1.0 if state else 0.0
        else:
            if state:
                self.digital_out.on()
            else:
                self.digital_out.off()

    # ------------------------------------------------------------------
    # Watchdog / timeout
    # ------------------------------------------------------------------
    def check_watchdog(self):
        """Trigger error output if no data has been received for 20 seconds."""
        if time.time() - self.last_msg > 20:
            logger.warning("Watchdog timeout: no data received for 20 seconds. Triggering error output.")
            self.set_error_output(True)

    # ------------------------------------------------------------------
    # Message handling
    # ------------------------------------------------------------------
    def handle_message(self, subscription_callback):
        """
        Process incoming messages and update self.last_msg.
        Non-blocking receive with zmq.NOBLOCK; on timeout check watchdog.
        """
        try:
            msg = self.config.socket.recv(flags=zmq.NOBLOCK)
        except zmq.ZMQError as e:
            logger.debug(f"No message available (zmq.ZMQError): {e}")
            self.check_watchdog()
            return

        self.last_msg = time.time()
        try:
            subscription_callback(msg)
        except Exception as e:
            logger.error(f"Error processing subscription callback: {e}")

    # ------------------------------------------------------------------
    # Cleanup
    # ------------------------------------------------------------------
    def cleanup(self):
        """Release GPIO resources safely."""
        if self._initialized:
            if self.pwm is not None:
                try:
                    self.pwm.close()
                except DeviceClosed:
                    pass
                except Exception as e:
                    logger.error(f"Error closing PWM device: {e}")
            if self.digital_out is not None:
                try:
                    self.digital_out.close()
                except DeviceClosed:
                    pass
                except Exception as e:
                    logger.error(f"Error closing digital output: {e}")
            self._initialized = False

    def signal_handler(self, signum, frame):
        """Handle SIGINT/SIGTERM for clean shutdown."""
        logger.info(f"Received signal {signum}, shutting down.")
        self.cleanup()
        sys.exit(0)


# ----------------------------------------------------------------------
# Example usage / demo entry point
# ----------------------------------------------------------------------
if __name__ == "__main__":
    import zmq
    from src.config import Config

    # Configure logging
    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s [%(levelname)s] %(name)s: %(message)s",
    )

    # Create a Config instance (populate with real values for full test)
