    cfg.set_subscription_callback(lambda x: None)

    # Register signal handlers for clean shutdown
    pid_handler = PIDHandler(cfg)
    signal.signal(signal.SIGINT, pid_handler.signal_handler)
    signal.signal(signal.SIGTERM, pid_handler.signal_handler)

    logger.info("PIDHandler initialized. Press Ctrl+C to exit.")
    try:
        while True:
            time.sleep(0.5)
    except KeyboardInterrupt:
        pid_handler.cleanup()

