import RPi.GPIO as GPIO
import time
import logging
import threading
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DATA_OUT_PIN = 5
TIMER_OUT_PIN = 6
DATA_IN_PIN = 20
TIMER_IN_PIN = 21

START_BYTE = [1, 0, 1, 1, 1, 1, 1, 1]
END_BYTE = [1, 1, 1, 1, 1, 1, 1, 1]
BIT_DELAY = 0.0001

shutdown_event = threading.Event()

_state = {'_lock': threading.Lock(), '_gpio_initialized': False}

def _state_manager():
    return _state

def _get_state():
    return _state_manager()

def _ensure_gpio_initialized():
    if not _get_state()['_gpio_initialized']:
        _with_gpio(None, lambda: None)

def _with_gpio(func, f):
    if func is None:
        return
    try:
        _ensure_gpio_initialized()
        func()
    except Exception as e:
        logging.error(f"GPIO error in callback: {e}")
    finally:
        try:
            GPIO.cleanup()
        except Exception:
            pass

def _gpio_setup(pins):
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    for p in pins:
        GPIO.setup(p, GPIO.OUT, initial=GPIO.LOW)
    for p in pins:
        GPIO.setup(p, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    _get_state()['_gpio_initialized'] = True

def _gpio_cleanup():
    _get_state()['_gpio_initialized'] = False
    GPIO.cleanup()

def _send_bit(bit):
    _ensure_gpio_initialized()
    GPIO.output(TIMER_OUT_PIN, GPIO.LOW)
    GPIO.output(DATA_OUT_PIN, bit)
    time.sleep(BIT_DELAY)
    GPIO.output(TIMER_OUT_PIN, GPIO.HIGH)
    time.sleep(BIT_DELAY)
    GPIO.output(TIMER_OUT_PIN, GPIO.LOW)

def _send_data(data):
    try:
        _ensure_gpio_initialized()
        for bit in START_BYTE:
            _send_bit(bit)
        for char in data:
            bits = [0] + [int(bit) for bit in format(ord(char), '08b')]
            for bit in bits:
                _send_bit(bit)
        for bit in END_BYTE:
            _send_bit(bit)
        logging.info(f"Sent data: {data}")
    except Exception as e:
        logging.error(f"Error sending data: {e}")
    finally:
        _gpio_cleanup()

def _receive_bit():
    try:
        return GPIO.input(DATA_IN_PIN)
    except Exception as e:
        logging.error(f"Error reading bit: {e}")
        return None

def _receive_data(timeout):
    try:
        GPIO.add_event_detect(TIMER_IN_PIN, GPIO.RISING, callback=lambda ch: None)
        accumulated = []
        start_time = time.time()
        while time.time() - start_time < timeout:
            if shutdown_event.is_set():
                return ""
            bit = _receive_bit()
            if bit is None:
                continue
            accumulated.append(bit)
            if len(accumulated) == 8:
                byte = ''.join(map(str, accumulated))
                accumulated = []
                if byte == START_BYTE:
                    while True:
                        if shutdown_event.is_set():
                            return ""
                        bit = _receive_bit()
                        if bit is None:
                            continue
                        accumulated.append(bit)
                        byte = ''.join(map(str, accumulated))
                        accumulated = []
                        if byte == END_BYTE:
                            return ''.join(map(str, accumulated))
        return ""
    except Exception as e:
        logging.error(f"Error receiving data: {e}")
        return ""
    finally:
        GPIO.remove_event_detect(TIMER_IN_PIN)
        _gpio_cleanup()

def _signal_handler(signum, frame):
    logging.info(f"Signal {signum} received, shutting down.")
    shutdown_event.set()

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    _gpio_setup([DATA_OUT_PIN, TIMER_OUT_PIN, DATA_IN_PIN, TIMER_IN_PIN])
    try:
        data_to_send = "Hello"
        received = _receive_data(timeout=5.0)
        if received:
            logging.info(f"Received data: {received}")
        _send_data(data_to_send)
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        _gpio_cleanup()

if __name__ == "__main__":
    main()

