import signal
import sys
import time

try:
    from smbus2 import SMBus, i2c_msg
except ImportError:
    print("Error: smbus2 library not found. Install with: pip install smbus2")
    sys.exit(1)

I2C_BUS = 1
BH1750_ADDR = 0x23
POWER_ON = 0x01
CONTINUOUS_HIGH_RES = 0x10

_running = True

def _handle_sigint(signum, frame):
    global _running
    _running = False

def init_sensor(bus):
    try:
        bus.write_byte(BH1750_ADDR, POWER_ON)
        time.sleep(0.01)
        bus.write_byte(BH1750_ADDR, CONTINUOUS_HIGH_RES)
        time.sleep(0.08)
    except OSError as e:
        raise RuntimeError(f"BH1750 init failed at 0x{BH1750_ADDR:02X}: {e}")

def read_lux(bus):
    try:
        data = bus.read_i2c_block_data(BH1750_ADDR, 0x00, 2)
        raw = (data[0] << 8) | data[1]
        return raw / 1.2
    except OSError as e:
        raise RuntimeError(f"BH1750 read failed: {e}")

def main():
    signal.signal(signal.SIGINT, _handle_sigint)
    try:
        bus = SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}")
        sys.exit(1)

    try:
        init_sensor(bus)
        print("BH1750 initialized. Reading lux (Ctrl+C to stop)...")
        while _running:
            try:
                lux = read_lux(bus)
                print(f"Lux: {lux:.2f}")
            except RuntimeError as e:
                print(f"Read error: {e}")
            time.sleep(1)
    finally:
        bus.close()
        print("\nExiting cleanly.")

if __name__ == "__main__":
    main()

