#!/usr/bin/env python3
"""
Rainbow HAT 3-bit binary counter.

Touchpads A (GPIO5), B (GPIO6), C (GPIO12) toggle bits 4, 2, 1 respectively.
The decimal value (0-7) is shown on the HT16K33 14-segment display,
the discrete red/green/blue LEDs reflect the bit states,
a single APA102 pixel at the value index is lit with a color derived from the
touchpads, and a 0.5-second tone at MIDI note 60 + value plays on the buzzer.

Degrades gracefully when individual peripherals are unavailable.
"""

import signal
import sys
import time

import board
import busio

try:
    import adafruit_ht16k33.segments as segments
except Exception:
    segments = None

try:
    from adafruit_apa102 import APA102
except Exception:
    APA102 = None

from gpiozero import Button
from gpiozero.exc import GPIOZeroError

# --- Configuration -----------------------------------------------------------

TOUCH_PINS = {
    "A": 5,   # Most significant bit (MSB)
    "B": 6,   # Middle bit
    "C": 12,  # Least significant bit (LSB)
}

LED_PINS = {
    "red": 7,
    "green": 8,
    "blue": 13,
}

I2C_ADDR = 0x70

# --- Globals -----------------------------------------------------------------

bit_states = [False, False, False]
running = True

# --- Hardware helpers ---------------------------------------------------------

def init_display():
    """Initialize the HT16K33 14-segment display. Returns segments or None."""
    if segments is None:
        print("Warning: adafruit-circuitpython-ht16k33 not installed; display disabled.",
              file=sys.stderr)
        return None
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        display = segments.Segments(i2c, address=I2C_ADDR)
        display.brightness = 0.5
        display.fill(segments.color.BLACK)
        return display
    except Exception as e:
        print(f"Warning: display init failed ({e}); display disabled.", file=sys.stderr)
        return None

def init_leds():
    """Initialize discrete red/green/blue LEDs. Returns dict of Button or None."""
    leds = {}
    for color, pin in LED_PINS.items():
        try:
            leds[color] = Button(pin, pull_up=True)
        except GPIOZeroError as e:
            print(f"Warning: LED {color} on GPIO{pin} init failed ({e}); disabled.",
                  file=sys.stderr)
            leds[color] = None
    return leds

def init_buzzer():
    """Initialize the piezo buzzer on GPIO13. Returns Button or None."""
    try:
        buzzer = Button(13, pull_up=True)
        return buzzer
    except GPIOZeroError as e:
        print(f"Warning: buzzer on GPIO13 init failed ({e}); disabled.", file=sys.stderr)
        return None

def init_strip():
    """Initialize the APA102 LED strip. Returns APA102 instance or None."""
    if APA102 is None:
        print("Warning: adafruit-circuitpython-apa102 not installed; LED strip disabled.",
              file=sys.stderr)
        return None
    try:
        strip = APA102(1, board.D10, board.D11, brightness=0.5)
        strip.fill((0, 0, 0))
        return strip
    except Exception as e:
        print(f"Warning: APA102 init failed ({e}); LED strip disabled.", file=sys.stderr)
        return None

def update_display(display, value):
    """Show decimal *value* (0-7) on the HT16K33 display."""
    if display is None:
        return
    try:
        display.fill(segments.color.BLACK)
        for i in range(14):
            if (value >> i) & 1:
                display.set_segment(i, segments.CHAR_DIG_0)
            else:
                display.set_segment(i, segments.CHAR_BLANK)
        display.show()
    except Exception as e:
        print(f"Warning: display update failed ({e}).", file=sys.stderr)

def update_leds(leds, bit_states):
    """Drive the discrete red/green/blue LEDs from *bit_states*."""
    for color, led in leds.items():
        if led is None:
            continue
        try:
            if bit_states[0]:
                led.on()
            else:
                led.off()
        except Exception as e:
            print(f"Warning: LED {color} update failed ({e}).", file=sys.stderr)

def update_strip(strip, value):
    """Light the APA102 strip: dim white at 0, all white at 7, single pixel at *value*."""
    if strip is None:
        return
    try:
        strip.fill((0, 0, 0))
        if value == 0:
            for i in range(7):
                strip.set_pixel(i, 0, 0, 0, 0)
        elif value == 7:
            for i in range(7):
                strip.set_pixel(i, 255, 255, 255)
        else:
            for i in range(7):
                r, g, b = 0, 0, 0
                if bit_states[0]:
                    r = 255
                if bit_states[1]:
                    g = 255
                if bit_states[2]:
                    b = 255
                strip.set_pixel(i, r, g, b, 0)
        strip.show()
    except Exception as e:
        print(f"Warning: LED strip update failed ({e}).", file=sys.stderr)

def play_tone(buzzer, value):
    """Play a 0.5-second tone at MIDI note 60 + *value* on the buzzer."""
    if buzzer is None:
        return
    try:
        midi_note = 60 + value
        freq = 440.0 * (2.0 ** ((midi_note - 69) / 12.0))
        buzzer.on()
        time.sleep(0.5)
        buzzer.off()
    except Exception as e:
        print(f"Warning: buzzer tone failed ({e}).", file=sys.stderr)

# --- Signal handling --------------------------------------------------------

def signal_handler(signum, frame):
    global running
    running = False

# --- Main --------------------------------------------------------------------

def main():
    global running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    display = init_display()
    leds = init_leds()
    buzzer = init_buzzer()
    strip = init_strip()

    print("Rainbow HAT binary counter ready. Press Ctrl+C to exit.")

    try:
        while running:
            for pad in TOUCH_PINS:
                if not running:
                    break
                try:
                    if Button(TOUCH_PINS[pad], pull_up=True).is_pressed:
                        bit_states[TOUCH_PINS[pad]] = not bit_states[TOUCH_PINS[pad]]
                        value = 0
                        for state in bit_states:
                            value |= (1 << (2 - (bit_states.index(state))))
                        update_display(display, value)
                        update_leds(leds, bit_states)
                        update_strip(strip, value)
                        play_tone(buzzer, value)
                        time.sleep(0.05)
                except Exception as e:
                    print(f"Warning: touchpad {pad} event failed ({e}).", file=sys.stderr)
    finally:
        print("\nShutting down...")
        try:
            if display is not None:
                display.fill(segments.color.BLACK)
                display.show()
        except Exception:
            pass
        try:
            if leds:
                for color, led in leds.items():
                    if led is not None:
                        led.off()
        except Exception:
            pass
        try:
            if strip is not None:
                strip.fill((0, 0, 0))
                strip.show()
        except Exception:
            pass
        try:
            if buzzer is not None:
                buzzer.off()
        except Exception:
            pass
        print("Cleanup complete.")

if __name__ == "__main__":
    main()

