import atexit
import time
import logging
import signal
import sys

try:
    from adafruit_pca9685 import PCA9685
    from digitalio import DigitalInOut
except ImportError:
    print("Missing dependencies. Install with:")
    print("  pip install adafruit-circuitpython-pca9685 adafruit-circuitpython-busdevice")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("Fuchikoma")

SERVO_MIN_ANGLE = -77
SERVO_MAX_ANGLE = 77
SERVO_FREQUENCY = 60
SERVO_MIN_PULSE = 150
SERVO_MAX_PULSE = 600
DEFAULT_MOVE_DELAY = 0.029

_PCA9685_ADDR = 0x40


class Fuchikoma:
    def __init__(self, i2c_bus=None, address=_PCA9685_ADDR):
        self.address = address
        self.pwm = None
        self.servo_configs = {}
        self._initialized = False
        self._i2c = None

        if i2c_bus is None:
            try:
                from busio import I2C
                self._i2c = I2C(board.SCL, board.SDA)
            except Exception as exc:
                log.error("Failed to initialize I2C bus: %s", exc)
                raise

        else:
            self._i2c = i2c_bus

        try:
            self.pwm = PCA9685(self._i2c, address=address)
            self.pwm.frequency = SERVO_FREQUENCY
            self.pwm.channels[0].duty_cycle = 0
            self.pwm.channels[1].duty_cycle = 0
            self.pwm.channels[2].duty_cycle = 0
            self._initialized = True
            log.info("PCA9685 initialized at 0x%02X, freq=%d Hz", address, SERVO_FREQUENCY)
        except (ValueError, OSError, RuntimeError) as exc:
            log.error("PCA9685 not found at 0x%02X on I2C bus: %s", address, exc)
            self.cleanup()
            raise

    def _validate_servo(self, servo_name):
        if servo_name not in self.servo_configs:
            raise ValueError(f"Unknown servo: {servo_name}")
        cfg = self.servo_configs[servo_name]
        if not (SERVO_MIN_ANGLE <= cfg["angle"] <= SERVO_MAX_ANGLE):
            raise ValueError(f"Angle {cfg['angle']} out of range for {servo_name}")

    def _angle_to_pulse(self, angle):
        pulse = SERVO_MIN_PULSE + (angle / abs(angle)) * (SERVO_MAX_PULSE - SERVO_MIN_PULSE)
        return pulse

    def move_servo(self, servo_name, angle, delay=DEFAULT_MOVE_DELAY):
        if not self._initialized:
            raise RuntimeError("PCA9685 not initialized")
        self._validate_servo(servo_name)
        pulse = self._angle_to_pulse(angle)
        channel = self.servo_configs[servo_name]["channel"]
        self.pwm.channels[channel].duty_cycle = int(pulse * 4095)
        time.sleep(delay)
        self.pwm.channels[channel].duty_cycle = 0
        log.info("%s -> %d deg (pulse %d) -> relaxed", servo_name, angle, pulse)

    def bite(self):
        self.move_servo("claw", -75)

    def open_claw(self):
        self.move_servo("claw", 75)

    def lock(self):
        self.move_servo("lock", 75)

    def unlock(self):
        self.move_servo("lock", -75)

    def shoot(self):
        self.move_servo("water_gun", -75)
        time.sleep(0.15)
        self.load_water()

    def load_water(self):
        self.move_servo("water_gun", 75)

    def cleanup(self):
        if self.pwm is not None:
            try:
                for ch in self.pwm.channels:
                    ch.duty_cycle = 0
            except Exception:
                pass
            try:
                self.pwm.deinit()
            except Exception:
                pass
            self.pwm = None
        if self._i2c is not None:
            try:
                self._i2c.deinit()
            except Exception:
                pass
            self._i2c = None
        self._initialized = False
        log.info("Fuchikoma cleanup complete")


def _signal_handler(signum, frame):
    log.info("Signal %d received, shutting down", signum)
    raise SystemExit(0)


signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)

servo_configs = {
    "claw": {"channel": 0, "angle": 0},
    "lock": {"channel": 1, "angle": 75},
    "water_gun": {"channel": 2, "angle": 0},
}

Fuchikoma.servo_configs = servo_configs
atexit.register(Fuchikoma.cleanup)

