import time
import signal
import sys
import board
import busio
import adafruit_tcs34725
from PIL import Image

# Global resources for cleanup
i2c_bus = None
color_sensor = None
running = True

def cleanup(signum=None, frame=None):
    """Release resources on exit."""
    global running, i2c_bus, color_sensor
    running = False
    if color_sensor is not None:
        try:
            color_sensor = None
        except Exception:
            pass
    if i2c_bus is not None:
        try:
            i2c_bus.deinit()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)

def get_sensor_color_data():
    """Read color data from the TCS34725 sensor.

    Returns:
        tuple: (R, G, B, Clear) channel values, or (0, 0, 0, 0) on error.
    """
    try:
        if color_sensor is None:
            raise RuntimeError("Color sensor not initialized")
        return color_sensor.color_rgb_bytes
    except Exception as e:
        print(f"Error reading color sensor data: {e}")
        return (0, 0, 0, 0)

def find_dominant_image_color(image_path):
    """Find the dominant color in an image file.

    Args:
        image_path (str): Path to the image file.

    Returns:
        tuple: Dominant (R, G, B) color, or (0, 0, 0) on error.
    """
    try:
        with Image.open(image_path) as img:
            img = img.resize((100, 100))
            colors = img.getcolors(10000)
            if colors:
                dominant_color = max(colors, key=lambda item: item[0])[1]
                return dominant_color
            else:
                return (0, 0, 0)
    except FileNotFoundError:
        print(f"Error: Image file not found at {image_path}")
        return (0, 0, 0)
    except Exception as e:
        print(f"Error processing image: {e}")
        return (0, 0, 0)

def main():
    global i2c_bus, color_sensor

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Initialize I2C bus
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        sys.exit(1)

    # Initialize TCS34725 color sensor at default address 0x29
    try:
        color_sensor = adafruit_tcs34725.TCS34725(i2c_bus)
        # Set integration time to 50 ms and gain to 4x
        color_sensor.integration_time = adafruit_tcs34725.INTEGRATION_TIME_50MS
        color_sensor.gain = adafruit_tcs34725.GAIN_4X
    except Exception as e:
        print(f"Error initializing TCS34725 sensor: {e}")
        cleanup()
        sys.exit(1)

    print("TCS34725 color sensor initialized. Reading color data...")

    while running:
        # Get color data from the sensor
        r, g, b, clear = get_sensor_color_data()
        print(f"Sensor Color Data: R={r}, G={g}, B={b}, Clear={clear}")

        # Find dominant color in image.jpg
        dominant_color = find_dominant_image_color("image.jpg")
        print(f"Dominant Image Color: {dominant_color}")

        # Wait 1 second before the next reading
        time.sleep(1)

    cleanup()

if __name__ == "__main__":
    main()

