import smbus2
import time
import math
import logging
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

MPU6050_ADDRESS = 0x68
POWER_MGMT_REGISTER = 0x6B
ACCEL_XOUT_H = 0x3B
ACCEL_SENSITIVITY = 16384.0
SAMPLE_COUNT = 8
SAMPLE_DELAY = 0.01

class TinyMLQualityControl:
    def __init__(self, magnitude_limit=2.5, variance_limit=0.4):
        self.magnitude_limit = magnitude_limit
        self.variance_limit = variance_limit
        self.bus = None
        self.running = True

    def initialize_accelerometer(self):
        try:
            self.bus = smbus2.SMBus(1)
            self.bus.write_byte_data(MPU6050_ADDRESS, POWER_MGMT_REGISTER, 0)
            logging.info("Accelerometer initialized successfully.")
        except Exception as e:
            logging.error(f"Failed to initialize accelerometer: {e}")
            raise

    def read_accelerometer_data(self):
        try:
            data = []
            for _ in range(SAMPLE_COUNT):
                if not self.running:
                    return None
                x_raw = self.bus.read_byte_data(MPU6050_ADDRESS, ACCEL_XOUT_H)
                y_raw = self.bus.read_byte_data(MPU6050_ADDRESS, ACCEL_XOUT_H + 2)
                z_raw = self.bus.read_byte_data(MPU6050_ADDRESS, ACCEL_XOUT_H + 4)
                x = self._convert_to_signed(x_raw)
                y = self._convert_to_signed(y_raw)
                z = self._convert_to_signed(z_raw)
                data.append([x, y, z])
                time.sleep(SAMPLE_DELAY)
            return data
        except Exception as e:
            logging.error(f"Error reading accelerometer data: {e}")
            return None

    @staticmethod
    def _convert_to_signed(raw_value):
        if raw_value > 127:
            return raw_value - 256
        return raw_value

    def extract_features(self, data):
        if not data:
            return None
        magnitudes = [math.sqrt(x**2 + y**2 + z**2) for x, y, z in data]
        rms_magnitude = sum(magnitudes) / len(magnitudes)
        variance = sum((m - rms_magnitude) ** 2 for m in magnitudes) / len(magnitudes)
        return rms_magnitude, variance

    def run_tiny_model(self, feature_vector):
        if feature_vector is None:
            return False
        return (feature_vector[0] > self.magnitude_limit or
                feature_vector[1] > self.variance_limit)

    def signal_handler(self, signum, frame):
        logging.info(f"Signal {signum} received, shutting down...")
        self.running = False

    def cleanup(self):
        if self.bus:
            try:
                self.bus.close()
                logging.info("I2C bus closed.")
            except Exception as e:
                logging.error(f"Error closing I2C bus: {e}")

def main():
    quality_control = TinyMLQualityControl()
    signal.signal(signal.SIGINT, quality_control.signal_handler)
    signal.signal(signal.SIGTERM, quality_control.signal_handler)
    try:
        quality_control.initialize_accelerometer()
        while quality_control.running:
            data = quality_control.read_accelerometer_data()
            if data:
                features = quality_control.extract_features(data)
                if features:
                    verdict = "DEFECTIVE" if quality_control.run_tiny_model(features) else "PASS"
                    logging.info(f"Part verdict: {verdict}")
            time.sleep(0.1)
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        quality_control.cleanup()

if __name__ == "__main__":
    main()

