import random
import time
from gpiozero import LED
from gpiozero.exc import GPIOZeroError

LED_PIN = 17
CYCLES = 5
DELAY_SECONDS = 2


def simulate_light_level() -> int:
    """Simulate an ambient light sensor reading (0-100 inclusive)."""
    return random.randint(0, 100)


def control_led(led: LED, light_level: int) -> None:
    """Turn the LED on or off based on the simulated light level."""
    if light_level < 50:
        led.on()
        print("LED ON: Ambient light is low")
    else:
        led.off()
        print("LED OFF: Ambient light is sufficient")


def main() -> None:
    """Run the simulated light-sensor / LED control loop."""
    try:
        with LED(LED_PIN) as led:
            for cycle in range(1, CYCLES + 1):
                light = simulate_light_level()
                print(f"Cycle {cycle}/{CYCLES}: Ambient Light = {light}%")
                control_led(led, light)
                if cycle < CYCLES:
                    time.sleep(DELAY_SECONDS)
    except KeyboardInterrupt:
        print("\nScript interrupted by user. Exiting...")
    except GPIOZeroError as exc:
        print(f"GPIO error: {exc}")
    except Exception as exc:
        print(f"Unexpected error: {exc}")
    finally:
        print("Script finished.")


if __name__ == "__main__":
    main()

