import serial
import time
import signal
import sys
from gpiozero import PWMOutputDevice

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
SERVO_PIN = 17
PWM_FREQUENCY = 50

running = True

def signal_handler(sig, frame):
    global running
    running = False

def move_servo(servo, angle):
    if not 0 <= angle <= 180:
        print(f"Error: Angle must be between 0 and 180, got {angle}")
        return
    try:
        duty_cycle = angle / 18.0 + 2.0
        servo.value = duty_cycle / 100.0
        time.sleep(1)
        servo.value = 0.0
    except Exception as e:
        print(f"Error moving servo: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        sys.exit(1)

    try:
        servo = PWMOutputDevice(SERVO_PIN, frequency=PWM_FREQUENCY, initial_value=0)
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        ser.close()
        sys.exit(1)

    try:
        while running:
            try:
                data = ser.readline().decode('ascii', errors='replace').strip()
                if data:
                    try:
                        angle = int(data)
                        move_servo(servo, angle)
                    except ValueError:
                        print(f"Invalid data received: {data}")
            except serial.SerialException as e:
                print(f"Serial read error: {e}")
                time.sleep(0.1)
    finally:
        servo.value = 0.0
        servo.close()
        ser.close()
        print("Resources cleaned up.")

if __name__ == '__main__':
    main()

