import signal
import sys
import time
from gpiozero import AngularServo, exc

BASE_PIN = 17
SHOULDER_PIN = 27
GRIPPER_PIN = 22

MIN_PULSE_WIDTH = 0.5 / 1000   # 0.5 ms
MAX_PULSE_WIDTH = 2.5 / 1000   # 2.5 ms
PWM_FREQUENCY = 50            # 50 Hz


class RoboticArm:
    """Control three SG90 servos for a robotic arm using gpiozero."""

    def __init__(self, base_pin, shoulder_pin, gripper_pin):
        self.base_servo = None
        self.shoulder_servo = None
        self.gripper_servo = None
        self._initialized = False

        try:
            self.base_servo = AngularServo(
                base_pin,
                min_angle=-90,
                max_angle=90,
                min_pulse_width=MIN_PULSE_WIDTH,
                max_pulse_width=MAX_PULSE_WIDTH,
                frame_width=1.0 / PWM_FREQUENCY,
            )
            self.shoulder_servo = AngularServo(
                shoulder_pin,
                min_angle=-90,
                max_angle=90,
                min_pulse_width=MIN_PULSE_WIDTH,
                max_pulse_width=MAX_PULSE_WIDTH,
                frame_width=1.0 / PWM_FREQUENCY,
            )
            self.gripper_servo = AngularServo(
                gripper_pin,
                min_angle=-90,
                max_angle=90,
                min_pulse_width=MIN_PULSE_WIDTH,
                max_pulse_width=MAX_PULSE_WIDTH,
                frame_width=1.0 / PWM_FREQUENCY,
            )
            self._initialized = True
        except exc.OutputDeviceBadValue as e:
            raise ValueError(f"Invalid servo angle range: {e}") from e
        except exc.PinInvalidPin as e:
            raise ValueError(f"Invalid GPIO pin: {e}") from e
        except Exception as e:
            raise RuntimeError(f"Failed to initialize servos: {e}") from e

    def move_joint(self, servo, target_angle):
        """Move a single servo to the target angle with a 0.4 s settling delay."""
        if not self._initialized:
            raise RuntimeError("RoboticArm not initialized")
        if servo is None:
            raise ValueError("Servo object is None")
        if not -90 <= target_angle <= 90:
            raise ValueError(f"Target angle {target_angle} out of range [-90, 90]")

        try:
            servo.angle = target_angle
            time.sleep(0.4)
        except exc.OutputDeviceBadValue as e:
            raise ValueError(f"Invalid angle {target_angle} for servo on pin {servo.pin.number}") from e

    def go_to_pose(self, base_angle, shoulder_angle, gripper_angle):
        """Move all three joints sequentially to their target angles."""
        self.move_joint(self.base_servo, base_angle)
        self.move_joint(self.shoulder_servo, shoulder_angle)
        self.move_joint(self.gripper_servo, gripper_angle)

    def release(self):
        """Detach all servos so they stop holding torque."""
        if self._initialized:
            for servo in (self.base_servo, self.shoulder_servo, self.gripper_servo):
                if servo is not None:
                    try:
                        servo.angle = None
                    except Exception:
                        pass
            self._initialized = False

    def __del__(self):
        self.release()


def run_demo_sequence(robot_arm):
    """Step through a demo sequence of arm poses."""
    poses = [
        (0, 0, 0),
        (45, -30, 20),
        (-45, 30, -20),
        (0, 0, 0),
    ]
    for pose in poses:
        robot_arm.go_to_pose(*pose)
        print(f"Arm moved to pose: {pose}")
        time.sleep(1.0)


def main():
    arm = None
    try:
        arm = RoboticArm(BASE_PIN, SHOULDER_PIN, GRIPPER_PIN)
        run_demo_sequence(arm)
    except (ValueError, RuntimeError) as e:
        print(f"Error: {e}", file=sys.stderr)
    except KeyboardInterrupt:
        print("\nInterrupted by user.", file=sys.stderr)
    finally:
        if arm is not None:
            arm.release()


def _signal_handler(signum, frame):
    print(f"\nReceived signal {signum}, exiting.", file=sys.stderr)
    sys.exit(0)


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    main()

