#!/usr/bin/env python3
"""
Garage door controller using Pimoroni Automation HAT.

Wiring:
  - Automation HAT state_pin 1 (GPIO26) -> magnetic reed switch.
    HIGH  -> door closed, LOW -> door open.
  - automationhat.relay.one -> relay that drives the garage-door opener.

The script toggles the door between open and closed each time the state
changes, energizing the relay for 0.5 s on each transition.
"""

import logging
import signal
import sys
import time

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

try:
    import automationhat
except ImportError:
    logging.error("automationhat library not installed. Install with: pip install automationhat")
    sys.exit(0)

DOOR_CLOSED = "closed"
DOOR_OPEN = "open"
RELAY_DURATION = 0.5

# Module-level reference so the signal handler can clean up.
_door: "GarageDoor | None" = None


class GarageDoor:
    """Manage a garage door via Automation HAT relay and state pin."""

    def __init__(self, name: str, state_pin: int = 1):
        if not 1 <= state_pin <= 4:
            raise ValueError(f"state_pin must be 1-4, got {state_pin}")
        self.name = name
        self.state_pin = state_pin
        self._closed_count = 0
        self._open_count = 0
        self._last_state = None
        self._last_action = None

        try:
            automationhat.relay.one.write(0)  # Ensure relay starts OFF
        except Exception as exc:
            logging.error(f"{self.name}: failed to initialise relay: {exc}")
            raise

        try:
            self._last_state = self.state
        except Exception as exc:
            logging.error(f"{self.name}: failed to read initial state: {exc}")
            raise

        logging.info(
            f"{self.name}: initialised on state_pin {self.state_pin} "
            f"(GPIO{self.state_pin * 26}) "
            f"-> current state: {self.state}"
        )

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------
    def trigger(self) -> None:
        """Energise the relay for RELAY_DURATION seconds, then release."""
        try:
            automationhat.relay.one.write(1)
            logging.info(f"{self.name}: relay ON")
            time.sleep(RELAY_DURATION)
        except Exception as exc:
            logging.error(f"{self.name}: failed to energise relay: {exc}")
            raise
        finally:
            try:
                automationhat.relay.one.write(0)
                logging.info(f"{self.name}: relay OFF")
            except Exception as exc:
                logging.error(f"{self.name}: failed to de-energise relay: {exc}")

    @property
    def state(self) -> str:
        """Read the door state from the Automation HAT state pin."""
        try:
            value = automationhat.input[self.state_pin - 1].read()
        except Exception as exc:
            logging.error(f"{self.name}: failed to read state pin {self.state_pin}: {exc}")
            raise
        if value is None:
            raise RuntimeError(f"{self.name}: state pin {self.state_pin} returned None")
        if value not in (0, 1):
            raise RuntimeError(
                f"{self.name}: state pin {self.state_pin} read {value!r}, "
                f"expected 0 or 1"
            )
        return DOOR_CLOSED if value == 1 else DOOR_OPEN

    @state.setter
    def state(self, value: str) -> None:
        """Set the door state; used internally by the getter."""
        if value == DOOR_CLOSED:
            self._closed_count += 1
            self._open_count = 0
        elif value == DOOR_OPEN:
            self._open_count += 1
            self._closed_count = 0
        else:
            raise ValueError(f"Invalid door state '{value}'; expected 'closed' or 'open'")

    @property
    def is_closed(self) -> bool:
        return self.state == DOOR_CLOSED

    @property
    def is_open(self) -> bool:
        return self.state == DOOR_OPEN

    @property
    def closed_count(self) -> int:
        return self._closed_count

    @property
    def open_count(self) -> int:
        return self._open_count

    @property
    def last_action(self) -> str | None:
        return self._last_action

    @property
    def last_state(self) -> str | None:
        return self._last_state

    # ------------------------------------------------------------------
    # Internal helpers
    # ------------------------------------------------------------------
    def _update_counters(self) -> None:
        if self.last_state == DOOR_CLOSED and self.state == DOOR_OPEN:
            self._last_action = "opened"
        elif self.last_state == DOOR_OPEN and self.state == DOOR_CLOSED:
            self._last_action = "closed"
        else:
            self._last_action = None

    def _log_transition(self) -> None:
        if self.last_action:
            logging.info(
                f"{self.name}: transition from {self.last_state} -> {self.state} "
                f"(action: {self.last_action})"
            )
        else:
            logging.info(f"{self.name}: state changed to {self.state}")

    def _cleanup(self) -> None:
        """Turn the relay OFF and reset counters on exit."""
        try:
            automationhat.relay.one.write(0)
        except Exception as exc:
            logging.error(f"{self.name}: error during cleanup: {exc}")
        self._closed_count = 0
        self._open_count = 0
        self._last_action = None
        self._last_state = None


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for clean shutdown."""
    logging.info(f"Received signal {signum}; shutting down.")
    global _door
    if _door is not None:
        _door._cleanup()
    sys.exit(0)


def main() -> None:
    global _door

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _door = GarageDoor(name="My_Garage", state_pin=1)
    except Exception as exc:
        logging.error(f"Failed to initialise garage door: {exc}")
        sys.exit(0)

    logging.info("Entering main loop. Press Ctrl+C to exit.")
    try:
        while True:
            try:
                current_state = _door.state
            except Exception as exc:
                logging.error(f"Error reading door state: {exc}")
                time.sleep(1)
                continue

            if current_state == DOOR_CLOSED:
                _door.trigger()
                logging.info("Door opened.")
            else:
                _door.trigger()
                logging.info("Door closed.")

            _door._update_counters()
            _door._log_transition()

            time.sleep(1)
    except Exception as exc:
        logging.error(f"Unexpected error in main loop: {exc}")
    finally:
        if _door is not None:
            _door._cleanup()


if __name__ == "__main__":
    main()

