from flask import Flask, request, jsonify
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

app = Flask(__name__)

RELAY_PIN = 23
relay = None

logging.basicConfig(level=logging.INFO, format='%(asctime)s [%(levelname)s] %(message)s')
logger = logging.getLogger(__name__)

def init_relay():
    global relay
    try:
        relay = OutputDevice(RELAY_PIN, active_high=True, initial_value=False)
        logger.info(f"Relay initialized on GPIO{RELAY_PIN}")
    except GPIOZeroError as e:
        logger.error(f"Failed to initialize relay on GPIO{RELAY_PIN}: {e}")
        sys.exit(1)

def cleanup(signum=None, frame=None):
    global relay
    if relay is not None:
        try:
            relay.close()
            logger.info("GPIO resource released")
        except Exception as e:
            logger.error(f"Error during GPIO cleanup: {e}")
    if signum is not None:
        sys.exit(0)

@app.route('/relay', methods=['POST'])
def handle_relay_request():
    try:
        req_data = request.get_json(silent=True)
        if req_data is None:
            return jsonify({'error': 'Invalid request'}), 400

        if not isinstance(req_data, dict):
            return jsonify({'error': 'Invalid request'}), 400

        state = req_data.get('state')
        if state is None:
            return jsonify({'error': 'Invalid request'}), 400

        if state == 'on':
            relay.on()
            logger.info("Relay turned ON")
        elif state == 'off':
            relay.off()
            logger.info("Relay turned OFF")
        else:
            return jsonify({'error': 'Invalid state. Use "on" or "off".'}), 400

        return jsonify({'status': 'Relay state changed'}), 200

    except Exception as e:
        logger.error(f"Error processing relay request: {e}")
        return jsonify({'error': 'Internal server error'}), 500

if __name__ == '__main__':
    init_relay()
    signal.signal(signal.SIGTERM, cleanup)
    signal.signal(signal.SIGINT, cleanup)
    try:
        app.run(host='0.0.0.0', port=5000, debug=False)
    finally:
        cleanup()

