import smbus2
import time
import signal
import sys

# Constants
I2C_BUS = 1
SENSOR_ADDRESS = 0x5A
APP_START_REGISTER = 0xF4
ALG_RESULT_DATA_REGISTER = 0x02
READ_INTERVAL_SECONDS = 2
NUM_READINGS = 5

# Global flag for graceful shutdown
_running = True

def signal_handler(sig, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False

def initialize_sensor(bus, address):
    """Initializes the CCS811 sensor."""
    try:
        bus.write_byte_data(address, APP_START_REGISTER, 0x20)
        return True
    except OSError:
        return False

def read_co2_level(bus, address):
    """Reads the CO2 level from the sensor."""
    try:
        data = bus.read_i2c_block_data(address, ALG_RESULT_DATA_REGISTER, 2)
        co2_level = (data[0] << 8) | data[1]
        return co2_level
    except OSError:
        return None

def display_co2_concentration(co2_level):
    """Displays the CO2 concentration."""
    print(f"CO2 Concentration: {co2_level} ppm")

def main():
    """Main function to read and display CO2 levels."""
    global _running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    bus = None
    try:
        bus = smbus2.SMBus(I2C_BUS)
        if not initialize_sensor(bus, SENSOR_ADDRESS):
            print("Error: Sensor initialization failed. Check wiring and address.")
            return

        for i in range(NUM_READINGS):
            if not _running:
                print("\nMeasurement interrupted.")
                break

            co2_level = read_co2_level(bus, SENSOR_ADDRESS)
            if co2_level is not None:
                display_co2_concentration(co2_level)
            else:
                print(f"Reading {i+1}/{NUM_READINGS}: Sensor read failed.")

            if i < NUM_READINGS - 1 and _running:
                time.sleep(READ_INTERVAL_SECONDS)

    except OSError as e:
        print(f"I2C communication error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if bus is not None:
            try:
                bus.close()
            except Exception:
                pass
        print("Program terminated.")

if __name__ == "__main__":
    main()

