import serial
import time
import signal
import sys

SERIAL_PORT = "/dev/serial0"
BAUD_RATE = 9600
TIMEOUT = 1

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def nmea_to_decimal(raw_value, hemisphere):
    """Convert NMEA ddmm.mmmm format to decimal degrees."""
    if not raw_value or not hemisphere:
        raise ValueError("Empty coordinate value or hemisphere")
    dot = raw_value.find('.')
    if dot < 0:
        raise ValueError("Invalid coordinate format")
    degrees_length = dot - 2
    if degrees_length < 1:
        raise ValueError("Invalid coordinate format")
    degrees = float(raw_value[:degrees_length])
    minutes = float(raw_value[degrees_length:])
    decimal = degrees + minutes / 60.0
    if hemisphere in ('S', 'W'):
        decimal = -decimal
    return decimal

def parse_gprmc(data):
    """Parse a $GPRMC sentence and return (lat_decimal, lon_decimal) or None."""
    if not data.startswith('$GPRMC'):
        return None
    parts = data.split(',')
    if len(parts) < 8:
        return None
    status = parts[2]
    if status != 'A':
        return None
    lat_raw = parts[3]
    lat_dir = parts[4]
    lon_raw = parts[5]
    lon_dir = parts[6]
    try:
        lat_decimal = nmea_to_decimal(lat_raw, lat_dir)
        lon_decimal = nmea_to_decimal(lon_raw, lon_dir)
        return lat_decimal, lon_decimal
    except ValueError:
        return None

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        ser = serial.Serial(SERIAL_PORT, baudrate=BAUD_RATE, timeout=TIMEOUT)
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                raw = ser.readline()
                if not raw:
                    continue
                line = raw.decode('ascii', errors='replace').strip()
                if not line:
                    continue
                result = parse_gprmc(line)
                if result:
                    lat, lon = result
                    print(f"Latitude: {lat:.6f}, Longitude: {lon:.6f}")
            except serial.SerialException as e:
                print(f"Serial read error: {e}", file=sys.stderr)
                break
            except UnicodeDecodeError as e:
                print(f"Decode error: {e}", file=sys.stderr)
                continue
            time.sleep(1)
    finally:
        if ser.is_open:
            ser.close()
        print("Exiting program.")

if __name__ == "__main__":
    main()

