import serial
import time
import signal
import sys

# Configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'gps_coordinates_log.txt'

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    """Handle SIGINT (Ctrl+C) for graceful shutdown."""
    global running
    running = False

def initialize_serial(port, baudrate, timeout):
    """Initializes the serial connection with error handling."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}")
        return None

def parse_gpgga(data):
    """Parses a $GPGGA sentence to extract latitude, longitude, and altitude."""
    try:
        parts = data.split(',')
        if len(parts) < 15:
            return None, None, None
        # Check for $GPGGA at the start
        if not parts[0].startswith('$GPGGA'):
            return None, None, None
        # Check fix quality (must be '1' for valid fix)
        if parts[6] != '1':
            return None, None, None
        latitude = decode_coordinate(parts[2], parts[3])
        longitude = decode_coordinate(parts[4], parts[5])
        altitude = decode_altitude(parts[9])
        return latitude, longitude, altitude
    except (IndexError, ValueError) as e:
        print(f"Error parsing GPS data: {e}")
        return None, None, None

def decode_coordinate(coordinate, direction):
    """Decodes a coordinate (DDMM.MMMM) and direction (N/S/E/W) into a string."""
    try:
        deg_digits = len(coordinate) - 2
        degrees = int(coordinate[:deg_digits])
        minutes = float(coordinate[deg_digits:])
        if direction in ('S', 'W'):
            degrees -= minutes
        elif direction in ('N', 'E'):
            minutes += degrees
        return f"{degrees} deg {minutes} min"
    except (ValueError, IndexError) as e:
        print(f"Error decoding coordinate: {e}")
        return None

def decode_altitude(altitude_str):
    """Decodes altitude units (e.g., meters, feet)."""
    try:
        if 'm' in altitude_str:
            return f"{float(altitude_str[:-2])} meters"
        elif 'ft' in altitude_str:
            return f"{float(altitude_str[:-3])} feet"
        else:
            return altitude_str
    except (ValueError, IndexError) as e:
        print(f"Error decoding altitude: {e}")
        return None

def log_coordinates(latitude, longitude, altitude):
    """Logs the coordinates to a file with an ISO 8601 timestamp."""
    timestamp = time.strftime('%Y-%m-%dT%H:%M:%S')
    log_entry = f"{timestamp} - Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude}\n"
    try:
        with open(LOG_FILE, 'a') as logfile:
            logfile.write(log_entry)
    except IOError as e:
        print(f"Error writing to log file: {e}")

def main():
    """Main function to read GPS data, parse it, and log the coordinates."""
    global running

    # Register signal handler for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)

    ser = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if ser is None:
        sys.exit(1)

    try:
        while running:
            try:
                raw_data = ser.readline()
                if not raw_data:
                    continue

                data = raw_data.decode('ascii', errors='ignore').strip()
                if not data:
                    continue

                latitude, longitude, altitude = parse_gpgga(data)
                if latitude and longitude and altitude:
                    log_coordinates(latitude, longitude, altitude)
                    print(f"Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude}")
            except serial.SerialException as e:
                print(f"Serial communication error: {e}")
                break
            except Exception as e:
                print(f"An unexpected error occurred: {e}")
                break
    finally:
        if ser and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

