import serial
import time
import threading
import signal
import sys
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'water_flow_log.txt'

stop_event = threading.Event()


def signal_handler(signum, frame):
    print(f"\nReceived signal {signum}, stopping data acquisition...")
    stop_event.set()


def read_flow_rate(serial_connection):
    try:
        raw = serial_connection.readline()
        if not raw:
            return None
        data = raw.decode('ascii', errors='replace').strip()
        if not data:
            return None
        return float(data)
    except ValueError:
        print(f"Warning: Invalid data received from sensor: {data!r}")
        return None
    except serial.SerialException as e:
        print(f"Serial I/O error during read: {e}")
        return None


def log_flow_rate(flow_rate, log_file):
    timestamp = datetime.now().isoformat(timespec='seconds')
    log_entry = f"{timestamp} - Flow Rate: {flow_rate} L/min\n"
    try:
        with open(log_file, 'a') as f:
            f.write(log_entry)
    except OSError as e:
        print(f"Error writing to log file: {e}")


def data_acquisition_loop(serial_connection, log_file):
    while not stop_event.is_set():
        flow_rate = read_flow_rate(serial_connection)
        if flow_rate is not None:
            print(f"Flow Rate: {flow_rate} L/min")
            log_flow_rate(flow_rate, log_file)
        stop_event.wait(1.0)


def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    serial_connection = None
    try:
        serial_connection = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=TIMEOUT
        )
        print(f"Connected to {SERIAL_PORT} at {BAUD_RATE} baud.")

        data_thread = threading.Thread(
            target=data_acquisition_loop,
            args=(serial_connection, LOG_FILE),
            daemon=True
        )
        data_thread.start()

        while not stop_event.is_set():
            stop_event.wait(0.1)

    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        stop_event.set()
        if serial_connection is not None and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")
        print("Program terminated.")


