import serial
import signal
import sys
import logging
from dataclasses import dataclass
from typing import Optional

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

@dataclass
class GPS_readings:
    latitude: Optional[float] = None
    latitude_dir: Optional[str] = None
    longitude: Optional[float] = None
    longitude_dir: Optional[str] = None
    altitude: Optional[float] = None
    satellites: Optional[int] = None

class GPSReader:
    def __init__(self, port: str = '/dev/serial0', baudrate: int = 9600, timeout: float = 1.0):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_port: Optional[serial.Serial] = None
        self._closed = False

    def connect(self) -> bool:
        try:
            self.serial_port = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self.timeout
            )
            logging.info(f"Connected to GPS on {self.port} at {self.baudrate} baud.")
            return True
        except serial.SerialException as e:
            logging.error(f"Failed to connect to GPS on {self.port}: {e}")
            self.serial_port = None
            return False
        except Exception as e:
            logging.error(f"Unexpected error opening {self.port}: {e}")
            self.serial_port = None
            return False

    def disconnect(self) -> None:
        if self._closed:
            return
        self._closed = True
        if self.serial_port is not None:
            try:
                if self.serial_port.is_open:
                    self.serial_port.close()
                    logging.info("Serial port closed.")
            except Exception as e:
                logging.error(f"Error closing serial port: {e}")
            finally:
                self.serial_port = None

    def get_readings(self) -> Optional[GPS_readings]:
        if self.serial_port is None or not self.serial_port.is_open:
            logging.warning("Serial port not open. Call connect() first.")
            return None

        try:
            raw = self.serial_port.readline()
            if not raw:
                return None

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                return None

            if not line.startswith('$GPGGA'):
                return None

            fields = line.split(',')
            if len(fields) < 15:
                logging.warning(f"Incomplete GPGGA sentence (field count: {len(fields)}): {line}")
                return None

            talker = fields[0]
            if talker != '$GPGGA':
                logging.warning(f"Not a GPGGA sentence (talker: {talker}).")
                return None

            try:
                fix_quality = int(fields[6])
                if fix_quality == 0:
                    logging.warning("GPS fix not valid (fix quality = 0).")
                    return None

                latitude = float(fields[2])
                latitude_dir = fields[3]
                longitude = float(fields[4])
                longitude_dir = fields[5]
                altitude = float(fields[9])
                satellites = int(fields[7]) if fields[7] else None

                if not (-90.0 <= latitude <= 90.0):
                    logging.warning(f"Latitude out of range: {latitude}")
                    return None
                if not (-180.0 <= longitude <= 180.0):
                    logging.warning(f"Longitude out of range: {longitude}")
                    return None
                if satellites is not None and satellites < 0:
                    logging.warning(f"Invalid satellite count: {satellites}")
                    return None

                return GPS_readings(
                    latitude=latitude,
                    latitude_dir=latitude_dir,
                    longitude=longitude,
                    longitude_dir=longitude_dir,
                    altitude=altitude,
                    satellites=satellites
                )
            except ValueError as e:
                logging.error(f"Numeric conversion error in GPGGA: {e}")
                return None
            except Exception as e:
                logging.error(f"Error parsing GPGGA sentence: {e}")
                return None

        except serial.SerialException as e:
            logging.error(f"Serial read error: {e}")
            return None
        except Exception as e:
            logging.error(f"Unexpected error reading from serial port: {e}")
            return None

def main():
    gps = GPSReader()
    running = True

    def signal_handler(signum, frame):
        nonlocal running
        logging.info(f"Signal {signum} received, shutting down.")
        running = False

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not gps.connect():
        logging.error("Could not connect to GPS. Exiting.")
        sys.exit(1)

    try:
        while running:
            readings = gps.get_readings()
            if readings is not None:
                logging.info(
                    f"GPS Fix: Lat={readings.latitude}{readings.latitude_dir}, "
                    f"Lon={readings.longitude}{readings.longitude_dir}, "
                    f"Alt={readings.altitude}m, Sats={readings.satellites}"
                )
            else:
                logging.debug("No valid GPS data received.")
    finally:
        gps.disconnect()

if __name__ == "__main__":
    main()

