import serial
import time
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'access_log.txt'

def log_access(tag_id):
    """Append a timestamped RFID access entry to the log file."""
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} - RFID Tag: {tag_id}\n'
    try:
        with open(LOG_FILE, 'a', encoding='utf-8') as logfile:
            logfile.write(log_entry)
            logfile.flush()
    except OSError as e:
        print(f'Error writing to log file: {e}', file=sys.stderr)

def main():
    serial_connection = None
    try:
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f'Monitoring RFID reader on {SERIAL_PORT} @ {BAUD_RATE} baud. Press Ctrl+C to stop.')

        while True:
            try:
                raw_line = serial_connection.readline()
                if not raw_line:
                    continue

                rfid_data = raw_line.decode('ascii', errors='replace').strip()
                if not rfid_data:
                    continue

                log_access(rfid_data)
                print(f'Access granted for RFID Tag: {rfid_data}')

            except serial.SerialException as e:
                print(f'Serial communication error: {e}', file=sys.stderr)
                break
            except OSError as e:
                print(f'I/O error during read: {e}', file=sys.stderr)
                break

    except serial.SerialException as e:
        print(f'Error opening serial port {SERIAL_PORT}: {e}', file=sys.stderr)
        sys.exit(1)
    except KeyboardInterrupt:
        print('\nProgram terminated by user.')
    finally:
        if serial_connection is not None and serial_connection.is_open:
            serial_connection.close()
            print('Serial port closed.')

if __name__ == '__main__':
    main()

