import serial
import time
import sys

# Configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_TIMEOUT = 1  # seconds

def parse_and_print(data):
    """Parse the received data and print the heart rate and SpO2."""
    try:
        heart_rate, spo2 = data.split(',')
        print(f"Heart Rate: {heart_rate} bpm, SpO2: {spo2} %")
    except ValueError:
        print(f"Invalid data format received: {data}")

def main():
    """Main function to read and process data from the serial port."""
    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=READ_TIMEOUT)
        print(f"Connected to {SERIAL_PORT} at {BAUD_RATE} baud.")

        while True:
            try:
                raw_data = ser.readline()
                if raw_data:
                    data = raw_data.decode('ascii', errors='replace').strip()
                    if data:
                        parse_and_print(data)
            except serial.SerialException as e:
                print(f"Serial communication error: {e}")
                break
            except OSError as e:
                print(f"I/O error: {e}")
                break

            time.sleep(1)

    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}")
        sys.exit(1)
    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

