import serial
import time
import sys

BLUETOOTH_DEVICE = "/dev/rfcomm4"
BLUETOOTH_BAUD_RATE = 38400


def send_command(ser, command):
    """Send a command prefixed with 'X' and terminated with a newline."""
    try:
        command_with_prefix = f"X{command}\n"
        ser.write(command_with_prefix.encode("utf-8"))
        ser.flush()
        time.sleep(0.1)
    except serial.SerialException as e:
        raise RuntimeError(f"Failed to send command '{command}': {e}") from e


def main():
    ser = None
    try:
        ser = serial.Serial(
            port=BLUETOOTH_DEVICE,
            baudrate=BLUETOOTH_BAUD_RATE,
            timeout=1,
        )
        print(f"Connected to {BLUETOOTH_DEVICE} at {BLUETOOTH_BAUD_RATE} baud.")

        while True:
            try:
                user_command = input("Enter command (or 'exit' to quit): ")
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_command.strip().lower() == "exit":
                break

            try:
                send_command(ser, user_command)
            except RuntimeError as e:
                print(f"Error: {e}", file=sys.stderr)

    except serial.SerialException as e:
        print(f"Error connecting to Bluetooth device: {e}", file=sys.stderr)
        sys.exit(1)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial connection closed.")


if __name__ == "__main__":
    main()

